		message string
		alter   bool
		want    bool
	}{
		{
			name:    "valid signature",
			message: "Hello, world!",
			alter:   false,
			want:    true,
		},
		{
			name:    "invalid signature",
			message: "Hello, world!",
			alter:   true,
			want:    false,
		},
	}
