			r, s := dsa.Sign(
				[]byte(tt.message),
				params.P,
				params.Q,
				params.G,
				privKey,
			)

			if tt.alter {
				// Alter the signature
				r.Add(r, big.NewInt(1))
			}

			// Verify the signature
			if got := dsa.Verify(
				[]byte(tt.message),
				r,
				s,
				params.P,
				params.Q,
				params.G,
				pubKey,
			); got != tt.want {
