					expected: 7,
				},
				{
					u:        0,
					v:        8,
					expected: 6,
				},
			},
		},
	}
	// Test #2:
	//							7
	//						 /
	//						6
	//					/  \
	//				2    8
	//			/ | \
	//		 0  3  4
	//		/   |
