}

func (n *Leaf) Left() Node {
	if n.NodeLeft != nil {
		n.NodeLeft.Parent = n // Leaf is the parent of its left child always
	}

	return n.NodeLeft
}

func (n *Leaf) Right() Node {
	return n.NodeRight
}

func (n *Leaf) Kind() string {
