* find the sum of the even-valued terms.
*
* @author ddaniel27
 */
package problem2

func Problem2(n uint) uint {
	sum := uint(0)
	a, b := uint(1), uint(2)

	for b < n {
		if b%2 == 0 {
			sum += b
		}

		a, b = b, a+b
	}

	return sum
}

