func TestTreeMinAndMax(t *testing.T) {
	helper := func(tree TestTree[int], nums []int) {
		ll := len(nums)
		if _, ok := tree.Min(); ok {
			t.Errorf("Error with Min method.")
		}
		if _, ok := tree.Max(); ok {
			t.Errorf("Error with Max method.")
		}
		tree.Push(nums...)
		if min, ok := tree.Min(); !ok || min != nums[0] {
			t.Errorf("Error with Min method.")
		}
		if max, ok := tree.Max(); !ok || max != nums[ll-1] {
			t.Errorf("Error with Max method.")
