  First output :
  Random Node : 15
  Second output :
  Random Node : 99
 */
/* Time Complexity : O(n)
  Auxiliary Space Complexity : O(1)
 */

package com.thealgorithms.datastructures.trees;

import java.util.HashMap;

/**
 * Represents a Trie Node that stores a character and pointers to its children.
 * Each node has a hashmap which can point to all possible characters.
 * Each node also has a boolean value to indicate if it is the end of a word.
 */
class TrieNode {
    char value;
    HashMap<Character, TrieNode> child;
    boolean end;

    /**
     * Constructor to initialize a TrieNode with an empty hashmap
     * and set end to false.
     */
    TrieNode(char value) {
        this.value = value;
        this.child = new HashMap<>();
        this.end = false;
    }
}

/**
 * Trie Data structure implementation without any libraries.
 * <p>
 * The Trie (also known as a prefix tree) is a special tree-like data structure
 * that is used to store a dynamic set or associative array where the keys are
 * usually strings. It is highly efficient for prefix-based searches.
 * <p>
 * This implementation supports basic Trie operations like insertion, search,
 * and deletion.
 * <p>
 * Each node of the Trie represents a character and has child nodes for each
 * possible character.
 *
 * @author <a href="https://github.com/dheeraj92">Dheeraj Kumar Barnwal</a>
 * @author <a href="https://github.com/sailok">Sailok Chinta</a>
 */

public class Trie {
    private static final char ROOT_NODE_VALUE = '*';

    private final TrieNode root;

    /**
     * Constructor to initialize the Trie.
     * The root node is created but doesn't represent any character.
     */
    public Trie() {
        root = new TrieNode(ROOT_NODE_VALUE);
    }

    /**
     * Inserts a word into the Trie.
     * <p>
     * The method traverses the Trie from the root, character by character, and adds
     * nodes if necessary. It marks the last node of the word as an end node.
     *
     * @param word The word to be inserted into the Trie.
     */
    public void insert(String word) {
        TrieNode currentNode = root;
        for (int i = 0; i < word.length(); i++) {
            TrieNode node = currentNode.child.getOrDefault(word.charAt(i), null);

            if (node == null) {
                node = new TrieNode(word.charAt(i));
                currentNode.child.put(word.charAt(i), node);
            }
            currentNode = node;
        }

        currentNode.end = true;
    }

    /**
     * Searches for a word in the Trie.
     * <p>
     * This method traverses the Trie based on the input word and checks whether
     * the word exists. It returns true if the word is found and its end flag is
     * true.
     *
     * @param word The word to search in the Trie.
     * @return true if the word exists in the Trie, false otherwise.
     */
    public boolean search(String word) {
        TrieNode currentNode = root;
        for (int i = 0; i < word.length(); i++) {
            TrieNode node = currentNode.child.getOrDefault(word.charAt(i), null);

            if (node == null) {
                return false;
            }
            currentNode = node;
        }

        return currentNode.end;
    }

    /**
     * Deletes a word from the Trie.
     * <p>
     * The method traverses the Trie to find the word and marks its end flag as
     * false.
     * It returns true if the word was successfully deleted, false if the word
     * wasn't found.
     *
     * @param word The word to be deleted from the Trie.
     * @return true if the word was found and deleted, false if it was not found.
     */
    public boolean delete(String word) {
        TrieNode currentNode = root;
        for (int i = 0; i < word.length(); i++) {
            TrieNode node = currentNode.child.getOrDefault(word.charAt(i), null);
            if (node == null) {
                return false;
            }

            currentNode = node;
        }

        if (currentNode.end) {
            currentNode.end = false;
            return true;
        }

        return false;
    }

    /**
     * Counts the number of words in the trie
     *<p>
     * The method traverses the Trie and counts the number of words.
     *
     * @return count of words
     */
    public int countWords() {
        return countWords(root);
    }

    private int countWords(TrieNode node) {
        if (node == null) {
            return 0;
        }

        int count = 0;
        if (node.end) {
            count++;
        }

        for (TrieNode child : node.child.values()) {
            count += countWords(child);
        }

        return count;
    }

    /**
     * Check if the prefix exists in the trie
     *
     * @param prefix the prefix to be checked in the Trie
     * @return true / false depending on the prefix if exists in the Trie
     */
    public boolean startsWithPrefix(String prefix) {
        TrieNode currentNode = root;

        for (int i = 0; i < prefix.length(); i++) {
            TrieNode node = currentNode.child.getOrDefault(prefix.charAt(i), null);
            if (node == null) {
                return false;
            }

            currentNode = node;
        }

        return true;
    }

    /**
     * Count the number of words starting with the given prefix in the trie
     *
     * @param prefix the prefix to be checked in the Trie
     * @return count of words
     */
    public int countWordsWithPrefix(String prefix) {
        TrieNode currentNode = root;

        for (int i = 0; i < prefix.length(); i++) {
            TrieNode node = currentNode.child.getOrDefault(prefix.charAt(i), null);
            if (node == null) {
                return 0;
            }

            currentNode = node;
        }

        return countWords(currentNode);
    }
}

package com.thealgorithms.datastructures.trees;

// Java Program to implement Auto-Complete
// Feature using Trie
class TrieAutocomplete {

    // Alphabet size (# of symbols)
    public static final int ALPHABET_SIZE = 26;

    // Trie node
    static class TrieNode {

        TrieNode[] children = new TrieNode[ALPHABET_SIZE];

        // isWordEnd is true if the node represents
        // end of a word
        boolean isWordEnd;
    }

    // Returns new trie node (initialized to NULLs)
    static TrieNode getNode() {
        TrieNode pNode = new TrieNode();
        pNode.isWordEnd = false;

        for (int i = 0; i < ALPHABET_SIZE; i++) {
            pNode.children[i] = null;
        }

        return pNode;
    }

    // If not present, inserts key into trie. If the
    // key is prefix of trie node, just marks leaf node
    static void insert(TrieNode root, final String key) {
        TrieNode pCrawl = root;

        for (int level = 0; level < key.length(); level++) {
            int index = (key.charAt(level) - 'a');
            if (pCrawl.children[index] == null) {
                pCrawl.children[index] = getNode();
            }
            pCrawl = pCrawl.children[index];
        }

        // mark last node as leaf
        pCrawl.isWordEnd = true;
    }

    // Returns true if key presents in trie, else false
    boolean search(TrieNode root, final String key) {
        int length = key.length();
        TrieNode pCrawl = root;

        for (int level = 0; level < length; level++) {
            int index = (key.charAt(level) - 'a');

            if (pCrawl.children[index] == null) {
                pCrawl = pCrawl.children[index];
            }
        }

        return (pCrawl != null && pCrawl.isWordEnd);
    }

    // Returns 0 if current node has a child
    // If all children are NULL, return 1.
    static boolean isLastNode(TrieNode root) {
        for (int i = 0; i < ALPHABET_SIZE; i++) {
            if (root.children[i] != null) {
                return false;
            }
        }
        return true;
    }

    // Recursive function to print auto-suggestions
    // for given node.
    static void suggestionsRec(TrieNode root, String currPrefix) {
        // found a string in Trie with the given prefix
        if (root.isWordEnd) {
            System.out.println(currPrefix);
        }

        // All children struct node pointers are NULL
        if (isLastNode(root)) {
            return;
        }

        for (int i = 0; i < ALPHABET_SIZE; i++) {
            if (root.children[i] != null) {
                // append current character to currPrefix string
                currPrefix += (char) (97 + i);

                // recur over the rest
                suggestionsRec(root.children[i], currPrefix);
            }
        }
    }

    // Function  to print suggestions for
    // given query prefix.
    static int printAutoSuggestions(TrieNode root, final String query) {
        TrieNode pCrawl = root;

        // Check if prefix is present and find the
        // the node (of last level) with last character
        // of given string.
        int level;
        int n = query.length();

        for (level = 0; level < n; level++) {
            int index = (query.charAt(level) - 'a');

            // no string in the Trie has this prefix
            if (pCrawl.children[index] == null) {
                return 0;
            }

            pCrawl = pCrawl.children[index];
        }

        // If prefix is present as a word.
        boolean isWord = (pCrawl.isWordEnd);

        // If prefix is last node of tree (has no
        // children)
        boolean isLast = isLastNode(pCrawl);

        // If prefix is present as a word, but
        // there is no subtree below the last
        // matching node.
        if (isWord && isLast) {
            System.out.println(query);
            return -1;
        }

        // If there are nodes below the last
        // matching character.
        if (!isLast) {
            String prefix = query;
            suggestionsRec(pCrawl, prefix);
            return 1;
        }

        return 0;
    }

    // Driver code
    public static void main(String[] args) {
        TrieNode root = getNode();
        insert(root, "hello");
        insert(root, "dog");
        insert(root, "hell");
        insert(root, "cat");
        insert(root, "a");
        insert(root, "hel");
        insert(root, "help");
        insert(root, "helps");
        insert(root, "helping");
        int comp = printAutoSuggestions(root, "hel");

        if (comp == -1) {
            System.out.println("No other strings found "
                + "with this prefix\n");
        } else if (comp == 0) {
            System.out.println("No string found with"
                + " this prefix\n");
        }
    }
}

package com.thealgorithms.datastructures.trees;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.Map;
import java.util.Queue;

/* The following class implements a vertical order traversal
in a tree from top to bottom and left to right, so for a tree :
           1
          / \
         2   3
        / \   \
       4   5   6
        \     / \
         7   8   10
          \
           9
 the sequence will be :
 4 2 7 1 5 9 3 8 6 10
 */
public final class VerticalOrderTraversal {
    private VerticalOrderTraversal() {
    }

    /*Function that receives a root Node and prints the tree
        in Vertical Order.*/
    public static ArrayList<Integer> verticalTraversal(BinaryTree.Node root) {
        if (root == null) {
            return new ArrayList<>();
        }

        /*Queue to store the Nodes.*/
        Queue<BinaryTree.Node> queue = new LinkedList<>();

        /*Queue to store the index of particular vertical
                 column of a tree , with root at 0, Nodes on left
                 with negative index and Nodes on right with positive
                 index. */
        Queue<Integer> index = new LinkedList<>();

        /*Map of Integer and ArrayList to store all the
                 elements in a particular index in a single arrayList
                 that will have a key equal to the index itself. */
        Map<Integer, ArrayList<Integer>> map = new HashMap<>();

        /* min and max stores leftmost and right most index to
                 later print the tree in vertical fashion.*/
        int max = 0;
        int min = 0;
        queue.offer(root);
        index.offer(0);

        while (!queue.isEmpty()) {
            if (queue.peek().left != null) {
                /*Adding the left Node if it is not null
                                and its index by subtracting 1 from it's
                                parent's index*/
                queue.offer(queue.peek().left);
                index.offer(index.peek() - 1);
            }
            if (queue.peek().right != null) {
                /*Adding the right Node if it is not null
                                and its index by adding 1 from it's
                                parent's index*/
                queue.offer(queue.peek().right);
                index.offer(index.peek() + 1);
            }
            /*If the map does not contains the index a new
                         ArrayList is created with the index as key.*/
            if (!map.containsKey(index.peek())) {
                ArrayList<Integer> a = new ArrayList<>();
                map.put(index.peek(), a);
            }
            /*For an index, corresponding Node data is added
                         to the respective ArrayList present at that
                         index. */
            map.get(index.peek()).add(queue.peek().data);
            max = Math.max(max, index.peek());
            min = Math.min(min, index.peek());
            /*The Node and its index are removed
                         from their respective queues.*/
            index.poll();
            queue.poll();
        }
        /*Finally map data is printed here which has keys
                from min to max. Each ArrayList represents a
                vertical column that is added in ans ArrayList.*/
        ArrayList<Integer> ans = new ArrayList<>();
        for (int i = min; i <= max; i++) {
            ans.addAll(map.get(i));
        }
        return ans;
    }
}

package com.thealgorithms.datastructures.trees;

import java.util.ArrayList;
import java.util.List;

/**
 * A Wavelet Tree is a highly efficient data structure used to store sequences
 * and answer queries like rank, select, and quantile in O(log(max_val - min_val)) time.
 * This structure is particularly useful in competitive programming and text compression.
 */
public class WaveletTree {

    private class Node {
        int low;
        int high;
        Node left;
        Node right;
        List<Integer> leftCount; // Prefix sums of elements going to the left child

        /**
         * Recursively constructs the tree nodes by partitioning the array.
         *
         * @param arr  the subarray for the current node
         * @param low  the minimum possible value in the current node
         * @param high the maximum possible value in the current node
         */
        Node(int[] arr, int low, int high) {
            this.low = low;
            this.high = high;

            if (low == high) {
                return;
            }

            int mid = low + (high - low) / 2;
            leftCount = new ArrayList<>(arr.length + 1);
            leftCount.add(0);

            List<Integer> leftArr = new ArrayList<>();
            List<Integer> rightArr = new ArrayList<>();

            for (int x : arr) {
                if (x <= mid) {
                    leftArr.add(x);
                    leftCount.add(leftCount.get(leftCount.size() - 1) + 1);
                } else {
                    rightArr.add(x);
                    leftCount.add(leftCount.get(leftCount.size() - 1));
                }
            }

            if (!leftArr.isEmpty()) {
                this.left = new Node(leftArr.stream().mapToInt(i -> i).toArray(), low, mid);
            }
            if (!rightArr.isEmpty()) {
                this.right = new Node(rightArr.stream().mapToInt(i -> i).toArray(), mid + 1, high);
            }
        }
    }

    private Node root;
    private final int n;

    /**
     * Constructs a Wavelet Tree from the given array.
     * The min and max values are determined dynamically from the array.
     *
     * @param arr the input array
     */
    public WaveletTree(int[] arr) {
        if (arr == null || arr.length == 0) {
            this.n = 0;
            return;
        }
        this.n = arr.length;
        int min = arr[0];
        int max = arr[0];
        for (int x : arr) {
            if (x < min) {
                min = x;
            }
            if (x > max) {
                max = x;
            }
        }
        root = new Node(arr, min, max);
    }

    /**
     * Constructs a Wavelet Tree from the given array with specific min and max values.
     *
     * @param arr      the input array
     * @param minValue the minimum possible value
     * @param maxValue the maximum possible value
     */
    public WaveletTree(int[] arr, int minValue, int maxValue) {
        if (arr == null || arr.length == 0) {
            this.n = 0;
            return;
        }
        this.n = arr.length;
        root = new Node(arr, minValue, maxValue);
    }

    /**
     * How many times does the number x appear in the array from index 0 to i (inclusive)?
     *
     * @param x the number to search for
     * @param i the end index (0-based, inclusive)
     * @return the number of occurrences of x in arr[0...i]
     */
    public int rank(int x, int i) {
        if (root == null || x < root.low || x > root.high || i < 0) {
            return 0;
        }
        // If i is out of bounds, cap it at n - 1
        int endIdx = Math.min(i, n - 1);
        return rank(root, x, endIdx + 1);
    }

    private int rank(Node node, int x, int count) {
        if (node == null || count == 0) {
            return 0;
        }
        if (node.low == node.high) {
            return count;
        }
        int mid = node.low + (node.high - node.low) / 2;
        int leftC = node.leftCount.get(count);
        if (x <= mid) {
            return rank(node.left, x, leftC);
        } else {
            return rank(node.right, x, count - leftC);
        }
    }

    /**
     * What is the 0-based index of the k-th occurrence of the number x in the array?
     *
     * @param x the number to search for
     * @param k the occurrence count (1-based)
     * @return the 0-based index in the original array, or -1 if x occurs less than k times
     */
    public int select(int x, int k) {
        if (root == null || x < root.low || x > root.high || k <= 0) {
            return -1;
        }
        if (rank(x, n - 1) < k) {
            return -1;
        }
        return select(root, x, k);
    }

    private int select(Node node, int x, int k) {
        if (node.low == node.high) {
            return k - 1; // 0-based index within the imaginary array at the leaf
        }
        int mid = node.low + (node.high - node.low) / 2;
        if (x <= mid) {
            int posInLeft = select(node.left, x, k);
            return binarySearchLeft(node.leftCount, posInLeft + 1);
        } else {
            int posInRight = select(node.right, x, k);
            return binarySearchRight(node.leftCount, posInRight + 1);
        }
    }

    private int binarySearchLeft(List<Integer> prefixSums, int k) {
        int l = 1;
        int r = prefixSums.size() - 1;
        int ans = -1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (prefixSums.get(mid) >= k) {
                ans = mid;
                r = mid - 1;
            } else {
                l = mid + 1;
            }
        }
        return ans == -1 ? -1 : ans - 1; // Convert to 0-based index
    }

    private int binarySearchRight(List<Integer> prefixSums, int k) {
        int l = 1;
        int r = prefixSums.size() - 1;
        int ans = -1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (mid - prefixSums.get(mid) >= k) {
                ans = mid;
                r = mid - 1;
            } else {
                l = mid + 1;
            }
        }
        return ans == -1 ? -1 : ans - 1; // Convert to 0-based index
    }

    /**
     * If you sort the subarray from index left to right, what would be the k-th smallest element?
     * This query is also commonly known as the quantile query.
     *
     * @param left  the start index of the subarray (0-based, inclusive)
     * @param right the end index of the subarray (0-based, inclusive)
     * @param k     the rank of the smallest element (1-based, e.g., k=1 is the minimum)
     * @return the k-th smallest element in the subarray, or -1 if invalid parameters
     */
    public int kthSmallest(int left, int right, int k) {
        if (root == null || left > right || left < 0 || k < 1 || k > right - left + 1) {
            return -1;
        }
        return kthSmallest(root, left, right, k);
    }

    private int kthSmallest(Node node, int left, int right, int k) {
        if (node.low == node.high) {
            return node.low;
        }

        int countLeftInLMinus1 = (left == 0) ? 0 : node.leftCount.get(left);
        int countLeftInR = node.leftCount.get(right + 1);
        int elementsToLeft = countLeftInR - countLeftInLMinus1;

        if (k <= elementsToLeft) {
            int newL = countLeftInLMinus1;
            int newR = countLeftInR - 1;
            return kthSmallest(node.left, newL, newR, k);
        } else {
            int newL = left - countLeftInLMinus1;
            int newR = right - countLeftInR;
            return kthSmallest(node.right, newL, newR, k - elementsToLeft);
        }
    }
}

package com.thealgorithms.datastructures.trees;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedList;
import java.util.List;

/**
 * Given a binary tree.
 * This code returns the zigzag level order traversal of its nodes' values.
 * Binary tree:
 *                               7
 *                   /                         \
 *                6                           3
 *         /                \             /             \
 *      2                    4         10                19
 * Zigzag traversal:
 * [[7], [3, 6], [2, 4, 10, 19]]
 * <p>
 * This solution implements the breadth-first search (BFS) algorithm using a queue.
 * 1. The algorithm starts with a root node. This node is added to a queue.
 * 2. While the queue is not empty:
 *  - each time we enter the while-loop we get queue size. Queue size refers to the number of nodes
 * at the current level.
 *  - we traverse all the level nodes in 2 ways: from left to right OR from right to left
 *    (this state is stored on `prevLevelFromLeftToRight` variable)
 *  - if the current node has children we add them to a queue
 *  - add level with nodes to a result.
 * <p>
 * Complexities:
 * O(N) - time, where N is the number of nodes in a binary tree
 * O(N) - space, where N is the number of nodes in a binary tree
 *
 * @author Albina Gimaletdinova on 11/01/2023
 */
public final class ZigzagTraversal {
    private ZigzagTraversal() {
    }
    public static List<List<Integer>> traverse(BinaryTree.Node root) {
        if (root == null) {
            return List.of();
        }

        List<List<Integer>> result = new ArrayList<>();

        // create a queue
        Deque<BinaryTree.Node> q = new ArrayDeque<>();
        q.offer(root);
        // start with writing nodes from left to right
        boolean prevLevelFromLeftToRight = false;

        while (!q.isEmpty()) {
            int nodesOnLevel = q.size();
            List<Integer> level = new LinkedList<>();
            // traverse all the level nodes
            for (int i = 0; i < nodesOnLevel; i++) {
                BinaryTree.Node node = q.poll();
                if (prevLevelFromLeftToRight) {
                    level.add(0, node.data);
                } else {
                    level.add(node.data);
                }
                if (node.left != null) {
                    q.offer(node.left);
                }
                if (node.right != null) {
                    q.offer(node.right);
                }
            }
            // the next level node traversal will be from the other side
            prevLevelFromLeftToRight = !prevLevelFromLeftToRight;
            result.add(level);
        }
        return result;
    }
}

package com.thealgorithms.datastructures.trees;

import java.util.Scanner;
import java.util.concurrent.ThreadLocalRandom;

final class NearestRightKey {
    private NearestRightKey() {
    }

    public static void main(String[] args) {
        NRKTree root = buildTree();
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter first number: ");
        int inputX0 = sc.nextInt();
        int toPrint = nearestRightKey(root, inputX0);
        System.out.println("Key: " + toPrint);
        sc.close();
    }

    public static NRKTree buildTree() {
        int randomX = ThreadLocalRandom.current().nextInt(0, 100 + 1);
        NRKTree root = new NRKTree(null, null, randomX);

        for (int i = 0; i < 1000; i++) {
            randomX = ThreadLocalRandom.current().nextInt(0, 100 + 1);
            root = root.insertKey(root, randomX);
        }

        return root;
    }

    public static int nearestRightKey(NRKTree root, int x0) {
        // Check whether tree is empty
        if (root == null) {
            return 0;
        } else {
            if (root.data - x0 > 0) {
                // Go left
                int temp = nearestRightKey(root.left, x0);
                if (temp == 0) {
                    return root.data;
                }
                return temp;
            } else {
                // Go right
                return nearestRightKey(root.right, x0);
            }
        }
    }
}

class NRKTree {

    public NRKTree left;
    public NRKTree right;
    public int data;

    NRKTree(int x) {
        this.left = null;
        this.right = null;
        this.data = x;
    }

    NRKTree(NRKTree right, NRKTree left, int x) {
        this.left = left;
        this.right = right;
        this.data = x;
    }

    public NRKTree insertKey(NRKTree current, int value) {
        if (current == null) {
            return new NRKTree(value);
        }

        if (value < current.data) {
            current.left = insertKey(current.left, value);
        } else if (value > current.data) {
            current.right = insertKey(current.right, value);
        }

        return current;
    }
}

