import java.util.Arrays;
/**
 * @author Md Asif Joardar
 *
 * Description: The partition problem is a classic problem in computer science
 * that asks whether a given set can be partitioned into two subsets such that
 * the sum of elements in each subset is the same.
 *
 * Example:
 * Consider nums = {1, 2, 3}
 * We can split the array "nums" into two partitions, where each having a sum of 3.
 * nums1 = {1, 2}
 * nums2 = {3}
 *
 * The time complexity of the solution is O(n × sum) and requires O(n × sum) space
 */
public final class PartitionProblem {
    private PartitionProblem() {
    }

    /**
     * Test if a set of integers can be partitioned into two subsets such that the sum of elements
     * in each subset is the same.
     *
     * @param nums the array contains integers.
     * @return {@code true} if two subset exists, otherwise {@code false}.
     */
    public static boolean partition(int[] nums) {
        // calculate the sum of all the elements in the array
        int sum = Arrays.stream(nums).sum();

        // it will return true if the sum is even and the array can be divided into two
        // subarrays/subset with equal sum. and here i reuse the SubsetSum class from dynamic
        // programming section to check if there is exists a subsetsum into nums[] array same as the
        // given sum
        return (sum & 1) == 0 && SubsetSum.subsetSum(nums, sum / 2);
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * A Dynamic Programming solution for the Rod cutting problem.
 * Returns the best obtainable price for a rod of length n and price[] as prices of different pieces.
 */
public final class RodCutting {
    private RodCutting() {
    }

    /**
     * This method calculates the maximum obtainable value for cutting a rod of length n
     * into different pieces, given the prices for each possible piece length.
     *
     * @param price An array representing the prices of different pieces, where price[i-1]
     *              represents the price of a piece of length i.
     * @param n     The length of the rod to be cut.
     * @throws IllegalArgumentException if the price array is null or empty, or if n is less than 0.
     * @return The maximum obtainable value.
     */
    public static int cutRod(int[] price, int n) {
        if (price == null || price.length == 0) {
            throw new IllegalArgumentException("Price array cannot be null or empty.");
        }
        if (n < 0) {
            throw new IllegalArgumentException("Rod length cannot be negative.");
        }

        // Create an array to store the maximum obtainable values for each rod length.
        int[] val = new int[n + 1];
        val[0] = 0;

        // Calculate the maximum value for each rod length from 1 to n.
        for (int i = 1; i <= n; i++) {
            int maxVal = Integer.MIN_VALUE;
            // Try all possible ways to cut the rod and find the maximum value.
            for (int j = 1; j <= i; j++) {
                maxVal = Math.max(maxVal, price[j - 1] + val[i - j]);
            }
            // Store the maximum value for the current rod length.
            val[i] = maxVal;
        }

        // The final element of 'val' contains the maximum obtainable value for a rod of length 'n'.
        return val[n];
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Class that provides methods to calculate the length of the shortest
 * supersequence of two given strings. The shortest supersequence is the smallest string
 * that contains both given strings as subsequences.
 */
final class ShortestCommonSupersequenceLength {
    private ShortestCommonSupersequenceLength() {
    }

    /**
     * Finds the length of the shortest supersequence of two given strings.
     * The shortest supersequence is defined as the smallest string that contains both
     * given strings as subsequences.
     *
     * @param x The first input string.
     * @param y The second input string.
     * @return The length of the shortest supersequence of the two strings.
     */
    static int shortestSuperSequence(String x, String y) {
        int m = x.length();
        int n = y.length();

        // find lcs
        int l = lcs(x, y, m, n);

        // Result is sum of input string
        // lengths - length of lcs
        return m + n - l;
    }

    /**
     * Calculates the length of the longest common subsequence (LCS) between two strings.
     * The LCS is the longest sequence that can be derived from both strings by deleting some
     * (or none) of the characters without changing the order of the remaining characters.
     *
     * @param x The first input string.
     * @param y The second input string.
     * @param m The length of the first input string.
     * @param n The length of the second input string.
     * @return The length of the longest common subsequence of the two strings.
     */
    static int lcs(String x, String y, int m, int n) {
        int[][] lN = new int[m + 1][n + 1];
        int i;
        int j;

        // Following steps build lN[m + 1][n + 1]
        // in bottom up fashion. Note that
        // lN[i][j] contains length of lNCS
        // of x[0..i - 1]and y[0..j - 1]
        for (i = 0; i <= m; i++) {
            for (j = 0; j <= n; j++) {
                if (i == 0 || j == 0) {
                    lN[i][j] = 0;
                } else if (x.charAt(i - 1) == y.charAt(j - 1)) {
                    lN[i][j] = lN[i - 1][j - 1] + 1;
                } else {
                    lN[i][j] = Math.max(lN[i - 1][j], lN[i][j - 1]);
                }
            }
        }

        // lN[m][n] contains length of LCS
        // for x[0..n - 1] and y[0..m - 1]
        return lN[m][n];
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Smith–Waterman algorithm for local sequence alignment.
 * Finds the highest scoring local alignment between substrings of two sequences.
 *
 * Time Complexity: O(n * m)
 * Space Complexity: O(n * m)
 */
public final class SmithWaterman {

    private SmithWaterman() {
        // Utility Class
    }

    /**
     * Computes the Smith–Waterman local alignment score between two strings.
     *
     * @param s1 first string
     * @param s2 second string
     * @param matchScore score for a match
     * @param mismatchPenalty penalty for mismatch (negative)
     * @param gapPenalty penalty for insertion/deletion (negative)
     * @return the maximum local alignment score
     */
    public static int align(String s1, String s2, int matchScore, int mismatchPenalty, int gapPenalty) {
        if (s1 == null || s2 == null) {
            throw new IllegalArgumentException("Input strings must not be null.");
        }

        int n = s1.length();
        int m = s2.length();
        int maxScore = 0;

        int[][] dp = new int[n + 1][m + 1];

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                int matchOrMismatch = (s1.charAt(i - 1) == s2.charAt(j - 1)) ? matchScore : mismatchPenalty;

                dp[i][j] = Math.max(0,
                    Math.max(Math.max(dp[i - 1][j - 1] + matchOrMismatch, // match/mismatch
                                 dp[i - 1][j] + gapPenalty // deletion
                                 ),
                        dp[i][j - 1] + gapPenalty // insertion
                        ));

                if (dp[i][j] > maxScore) {
                    maxScore = dp[i][j];
                }
            }
        }

        return maxScore;
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Find the number of subsets present in the given array with a sum equal to target.
 * Based on Solution discussed on
 * <a href="https://stackoverflow.com/questions/22891076/count-number-of-subsets-with-sum-equal-to-k">StackOverflow</a>
 * @author <a href="https://github.com/samratpodder">Samrat Podder</a>
 */
public final class SubsetCount {
    private SubsetCount() {
    }

    /**
     * Dynamic Programming Implementation.
     * Method to find out the number of subsets present in the given array with a sum equal to
     * target. Time Complexity is O(n*target) and Space Complexity is O(n*target)
     * @param arr is the input array on which subsets are  to searched
     * @param target is the sum of each element of the subset taken together
     *
     */
    public static int getCount(int[] arr, int target) {
        /*
         * Base Cases - If target becomes zero, we have reached the required sum for the subset
         * If we reach the end of the array arr then, either if target==arr[end], then we add one to
         * the final count Otherwise we add 0 to the final count
         */
        int n = arr.length;
        int[][] dp = new int[n][target + 1];
        for (int i = 0; i < n; i++) {
            dp[i][0] = 1;
        }
        if (arr[0] <= target) {
            dp[0][arr[0]] = 1;
        }
        for (int t = 1; t <= target; t++) {
            for (int idx = 1; idx < n; idx++) {
                int notpick = dp[idx - 1][t];
                int pick = 0;
                if (arr[idx] <= t) {
                    pick += dp[idx - 1][target - t];
                }
                dp[idx][target] = pick + notpick;
            }
        }
        return dp[n - 1][target];
    }

    /**
     * This Method is a Space Optimized version of the getCount(int[], int) method and solves the
     * same problem This approach is a bit better in terms of Space Used Time Complexity is
     * O(n*target) and Space Complexity is O(target)
     * @param arr is the input array on which subsets are  to searched
     * @param target is the sum of each element of the subset taken together
     */
    public static int getCountSO(int[] arr, int target) {
        int n = arr.length;
        int[] prev = new int[target + 1];
        prev[0] = 1;
        if (arr[0] <= target) {
            prev[arr[0]] = 1;
        }
        for (int ind = 1; ind < n; ind++) {
            int[] cur = new int[target + 1];
            cur[0] = 1;
            for (int t = 1; t <= target; t++) {
                int notTaken = prev[t];
                int taken = 0;
                if (arr[ind] <= t) {
                    taken = prev[t - arr[ind]];
                }
                cur[t] = notTaken + taken;
            }
            prev = cur;
        }
        return prev[target];
    }
}

package com.thealgorithms.dynamicprogramming;

public final class SubsetSum {
    private SubsetSum() {
    }

    /**
     * Test if a set of integers contains a subset that sums to a given integer.
     *
     * @param arr the array containing integers.
     * @param sum the target sum of the subset.
     * @return {@code true} if a subset exists that sums to the given value,
     *         otherwise {@code false}.
     */
    public static boolean subsetSum(int[] arr, int sum) {
        int n = arr.length;

        // Initialize a single array to store the possible sums
        boolean[] isSum = new boolean[sum + 1];

        // Mark isSum[0] = true since a sum of 0 is always possible with 0 elements
        isSum[0] = true;

        // Iterate through each Element in the array
        for (int i = 0; i < n; i++) {
            // Traverse the isSum array backwards to prevent overwriting values
            for (int j = sum; j >= arr[i]; j--) {
                isSum[j] = isSum[j] || isSum[j - arr[i]];
            }
        }
        return isSum[sum];
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Utility class for solving the Subset Sum problem using a space-optimized dynamic programming approach.
 *
 * <p>This algorithm determines whether any subset of a given array sums up to a specific target value.</p>
 *
 * <p><b>Time Complexity:</b> O(n * sum)</p>
 * <p><b>Space Complexity:</b> O(sum)</p>
 */
public final class SubsetSumSpaceOptimized {
    private SubsetSumSpaceOptimized() {
    }

    /**
     * Determines whether there exists a subset of the given array that adds up to the specified sum.
     * This method uses a space-optimized dynamic programming approach with a 1D boolean array.
     *
     * @param nums The array of non-negative integers
     * @param targetSum The desired subset sum
     * @return {@code true} if such a subset exists, {@code false} otherwise
     */
    public static boolean isSubsetSum(int[] nums, int targetSum) {
        if (targetSum < 0) {
            return false; // Subset sum can't be negative
        }

        boolean[] dp = new boolean[targetSum + 1];
        dp[0] = true; // Empty subset always sums to 0

        for (int number : nums) {
            for (int j = targetSum; j >= number; j--) {
                dp[j] = dp[j] || dp[j - number];
            }
        }

        return dp[targetSum];
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * A utility class that contains the Sum of Subset problem solution using
 * recursion.
 *
 * The Sum of Subset problem determines whether a subset of elements from a
 * given array sums up to a specific target value.
 *
 * Wikipedia: https://en.wikipedia.org/wiki/Subset_sum_problem
 */
public final class SumOfSubset {

    private SumOfSubset() {
    }

    /**
     * Determines if there exists a subset of elements in the array `arr` that
     * adds up to the given `key` value using recursion.
     *
     * @param arr The array of integers.
     * @param num The index of the current element being considered.
     * @param key The target sum we are trying to achieve.
     * @return true if a subset of `arr` adds up to `key`, false otherwise.
     *
     *         This is a recursive solution that checks for two possibilities at
     *         each step:
     *         1. Include the current element in the subset and check if the
     *         remaining elements can sum up to the remaining target.
     *         2. Exclude the current element and check if the remaining elements
     *         can sum up to the target without this element.
     */
    public static boolean subsetSum(int[] arr, int num, int key) {
        if (key == 0) {
            return true;
        }
        if (num < 0 || key < 0) {
            return false;
        }

        boolean include = subsetSum(arr, num - 1, key - arr[num]);
        boolean exclude = subsetSum(arr, num - 1, key);
        return include || exclude;
    }
}

package com.thealgorithms.dynamicprogramming;

import com.thealgorithms.datastructures.graphs.UndirectedAdjacencyListGraph;

/**
 * This class implements the algorithm for calculating the maximum weighted matching in a tree.
 * The tree is represented as an undirected graph with weighted edges.
 *
 * Problem Description:
 *  Given an undirected tree G = (V, E) with edge weights γ: E → N and a root r ∈ V,
 *  the goal is to find a maximum weight matching M ⊆ E such that no two edges in M
 *  share a common vertex. The sum of the weights of the edges in M, ∑ e∈M γ(e), should be maximized.
 *  For more Information: <a href="https://en.wikipedia.org/wiki/Matching_(graph_theory)">Matching (graph theory)</a>
 *
 * @author  <a href="https://github.com/DenizAltunkapan">Deniz Altunkapan</a>
 */
public class TreeMatching {

    private UndirectedAdjacencyListGraph graph;
    private int[][] dp;

    /**
     * Constructor that initializes the graph and the DP table.
     *
     * @param graph The graph that represents the tree and is used for the matching algorithm.
     */
    public TreeMatching(UndirectedAdjacencyListGraph graph) {
        this.graph = graph;
        this.dp = new int[graph.size()][2];
    }

    /**
     * Calculates the maximum weighted matching for the tree, starting from the given root node.
     *
     * @param root The index of the root node of the tree.
     * @param parent The index of the parent node (used for recursion).
     * @return The maximum weighted matching for the tree, starting from the root node.
     *
     */
    public int getMaxMatching(int root, int parent) {
        if (root < 0 || root >= graph.size()) {
            throw new IllegalArgumentException("Invalid root: " + root);
        }
        maxMatching(root, parent);
        return Math.max(dp[root][0], dp[root][1]);
    }

    /**
     * Recursively computes the maximum weighted matching for a node, assuming that the node
     * can either be included or excluded from the matching.
     *
     * @param node The index of the current node for which the matching is calculated.
     * @param parent The index of the parent node (to avoid revisiting the parent node during recursion).
     */
    private void maxMatching(int node, int parent) {
        dp[node][0] = 0;
        dp[node][1] = 0;

        int sumWithoutEdge = 0;
        for (int adjNode : graph.getNeighbors(node)) {
            if (adjNode == parent) {
                continue;
            }
            maxMatching(adjNode, node);
            sumWithoutEdge += Math.max(dp[adjNode][0], dp[adjNode][1]);
        }

        dp[node][0] = sumWithoutEdge;

        for (int adjNode : graph.getNeighbors(node)) {
            if (adjNode == parent) {
                continue;
            }
            int weight = graph.getEdgeWeight(node, adjNode);
            dp[node][1] = Math.max(dp[node][1], sumWithoutEdge - Math.max(dp[adjNode][0], dp[adjNode][1]) + dp[adjNode][0] + weight);
        }
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * The {@code Tribonacci} class provides a method to compute the n-th number in the Tribonacci sequence.
 * N-th Tribonacci Number - https://leetcode.com/problems/n-th-tribonacci-number/description/
 */
public final class Tribonacci {
    private Tribonacci() {
    }

    /**
     * Computes the n-th Tribonacci number.
     *
     * @param n the index of the Tribonacci number to compute
     * @return the n-th Tribonacci number
     */
    public static int compute(int n) {
        if (n == 0) {
            return 0;
        }
        if (n == 1 || n == 2) {
            return 1;
        }

        int first = 0;
        int second = 1;
        int third = 1;

        for (int i = 3; i <= n; i++) {
            int next = first + second + third;
            first = second;
            second = third;
            third = next;
        }

        return third;
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.Arrays;

/**
 * Author: Siddhant Swarup Mallick
 * Github: https://github.com/siddhant2002
 * <p>
 * Problem Description:
 * A robot is located at the top-left corner of a m x n grid (marked 'Start' in the diagram below).
 * The robot can only move either down or right at any point in time.
 * The robot is trying to reach the bottom-right corner of the grid (marked 'Finish' in the diagram below).
 * How many possible unique paths are there?
 * <p>
 * Program Description:
 * This program calculates the number of unique paths possible for a robot to reach the bottom-right corner
 * of an m x n grid using dynamic programming.
 */
public final class UniquePaths {

    private UniquePaths() {
    }

    /**
     * Calculates the number of unique paths using a 1D dynamic programming array.
     * Time complexity O(n*m)
     * Space complexity O(min(n,m))
     *
     * @param m The number of rows in the grid.
     * @param n The number of columns in the grid.
     * @return The number of unique paths.
     */
    public static int uniquePaths(final int m, final int n) {
        if (m > n) {
            return uniquePaths(n, m); // Recursive call to handle n > m cases
        }
        int[] dp = new int[n]; // Create a 1D array to store unique paths for each column
        Arrays.fill(dp, 1); // Initialize all values to 1 (one way to reach each cell)
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[j] = Math.addExact(dp[j], dp[j - 1]); // Update the number of unique paths for each cell
            }
        }
        return dp[n - 1]; // The result is stored in the last column of the array
    }

    /**
     * Calculates the number of unique paths using a 2D dynamic programming array.
     * Time complexity O(n*m)
     * Space complexity O(n*m)
     *
     * @param m The number of rows in the grid.
     * @param n The number of columns in the grid.
     * @return The number of unique paths.
     */
    public static int uniquePaths2(final int m, final int n) {
        int[][] dp = new int[m][n]; // Create a 2D array to store unique paths for each cell
        for (int i = 0; i < m; i++) {
            dp[i][0] = 1; // Initialize the first column to 1 (one way to reach each cell)
        }
        for (int j = 0; j < n; j++) {
            dp[0][j] = 1; // Initialize the first row to 1 (one way to reach each cell)
        }
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.addExact(dp[i - 1][j], dp[i][j - 1]); // Update the number of unique paths for each cell
            }
        }
        return dp[m - 1][n - 1]; // The result is stored in the bottom-right cell of the array
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/**
 * Utility class to find the number of unique subsequences that can be
 * produced from a given string.
 *
 * <p> This class contains static methods to compute the unique subsequence count
 * using dynamic programming and recursion. It ensures that duplicate characters
 * are not counted multiple times in the subsequences.</p>
 *
 * <p> Author: https://github.com/Tuhinm2002 </p>
 */
public final class UniqueSubsequencesCount {

    /**
     * Private constructor to prevent instantiation of this utility class.
     * This class should only be used in a static context.
     *
     * @throws UnsupportedOperationException if attempted to instantiate.
     */
    private UniqueSubsequencesCount() {
        throw new UnsupportedOperationException("Utility class");
    }

    /**
     * Finds the number of unique subsequences that can be generated from
     * the given string.
     *
     * <p> This method initializes a dynamic programming (DP) array and invokes
     * the recursive helper function to compute the subsequence count.</p>
     *
     * @param str the input string from which subsequences are generated
     * @return the total count of unique subsequences
     */
    public static int countSubseq(String str) {

        // DP array initialized to store intermediate results
        int[] dp = new int[str.length() + 1];
        Arrays.fill(dp, -1);

        // Calls the recursive function to compute the result
        return countSubsequences(str, 0, dp);
    }

    /**
     * Recursive helper function to count the number of unique subsequences
     * starting from the given index.
     *
     * <p> Uses a HashSet to avoid counting duplicate characters within
     * a single subsequence.</p>
     *
     * @param st the input string
     * @param idx the current index from which to calculate subsequences
     * @param dp dynamic programming array used to memoize results
     * @return the total number of unique subsequences starting from the
     *         current index
     */
    public static int countSubsequences(String st, int idx, int[] dp) {

        // Base case: when index exceeds the string length
        if (idx >= st.length()) {
            return 0;
        }

        // If result is already calculated, return the memoized value
        if (dp[idx] != -1) {
            return dp[idx];
        }

        // Set to store characters to avoid duplicates
        Set<Character> set = new HashSet<>();

        int res = 0;

        // Iterate over the string starting from current index
        for (int j = idx; j < st.length(); j++) {

            // If character is already in the set, skip it
            if (set.contains(st.charAt(j))) {
                continue;
            }

            // Add character to set and recursively calculate subsequences
            set.add(st.charAt(j));

            // 1 for the current subsequence + recursive call for the rest of the string
            res = 1 + countSubsequences(st, j + 1, dp) + res;
        }

        // Memoize the result
        dp[idx] = res;
        return dp[idx];
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 *
 * Author: Janmesh Singh
 * Github: https://github.com/janmeshjs

 * Problem Statement: To determine if the pattern matches the text.
 * The pattern can include two special wildcard characters:
 *       ' ? ': Matches any single character.
 *       ' * ': Matches zero or more of any character sequence.
 *
 * Use DP to return True if the pattern matches the entire text and False otherwise
 *
 */
public final class WildcardMatching {
    private WildcardMatching() {
    }

    public static boolean isMatch(String text, String pattern) {
        int m = text.length();
        int n = pattern.length();

        // Create a DP table to store intermediate results
        boolean[][] dp = new boolean[m + 1][n + 1];

        // Base case: an empty pattern matches an empty text
        dp[0][0] = true;

        // Handle patterns starting with '*'
        for (int j = 1; j <= n; j++) {
            if (pattern.charAt(j - 1) == '*') {
                dp[0][j] = dp[0][j - 1];
            }
        }

        // Fill the DP table
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                char textChar = text.charAt(i - 1);
                char patternChar = pattern.charAt(j - 1);

                if (patternChar == textChar || patternChar == '?') {
                    dp[i][j] = dp[i - 1][j - 1];
                } else if (patternChar == '*') {
                    // '*' can match zero or more characters
                    dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
                } else {
                    dp[i][j] = false;
                }
            }
        }
        // The result is in the bottom-right cell of the DP table
        return dp[m][n];
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * The WineProblem class provides a solution to the wine selling problem.
 * Given a collection of N wines with different prices, the objective is to maximize profit by selling
 * one wine each year, considering the constraint that only the leftmost or rightmost wine can be sold
 * at any given time.
 *
 * The price of the ith wine is pi, and the selling price increases by a factor of the year in which
 * it is sold. This class implements three approaches to solve the problem:
 *
 * 1. **Recursion**: A straightforward recursive method that computes the maximum profit.
 *    - Time Complexity: O(2^N)
 *    - Space Complexity: O(N) due to recursive calls.
 *
 * 2. **Top-Down Dynamic Programming (Memoization)**: This approach caches the results of subproblems
 *    to avoid redundant computations.
 *    - Time Complexity: O(N^2)
 *    - Space Complexity: O(N^2) for the storage of results and O(N) for recursion stack.
 *
 * 3. **Bottom-Up Dynamic Programming (Tabulation)**: This method builds a table iteratively to
 *    compute the maximum profit for all possible subproblems.
 *    - Time Complexity: O(N^2)
 *    - Space Complexity: O(N^2) for the table.
 */
public final class WineProblem {
    private WineProblem() {
    }

    /**
     * Calculate maximum profit using recursion.
     *
     * @param arr Array of wine prices.
     * @param si  Start index of the wine to consider.
     * @param ei  End index of the wine to consider.
     * @return Maximum profit obtainable by selling the wines.
     */
    public static int wpRecursion(int[] arr, int si, int ei) {
        int n = arr.length;
        int year = (n - (ei - si + 1)) + 1;
        if (si == ei) {
            return arr[si] * year;
        }

        int start = wpRecursion(arr, si + 1, ei) + arr[si] * year;
        int end = wpRecursion(arr, si, ei - 1) + arr[ei] * year;

        return Math.max(start, end);
    }

    /**
     * Calculate maximum profit using top-down dynamic programming with memoization.
     *
     * @param arr  Array of wine prices.
     * @param si   Start index of the wine to consider.
     * @param ei   End index of the wine to consider.
     * @param strg 2D array to store results of subproblems.
     * @return Maximum profit obtainable by selling the wines.
     */
    public static int wptd(int[] arr, int si, int ei, int[][] strg) {
        int n = arr.length;
        int year = (n - (ei - si + 1)) + 1;
        if (si == ei) {
            return arr[si] * year;
        }

        if (strg[si][ei] != 0) {
            return strg[si][ei];
        }
        int start = wptd(arr, si + 1, ei, strg) + arr[si] * year;
        int end = wptd(arr, si, ei - 1, strg) + arr[ei] * year;

        int ans = Math.max(start, end);
        strg[si][ei] = ans;

        return ans;
    }

    /**
     * Calculate maximum profit using bottom-up dynamic programming with tabulation.
     *
     * @param arr Array of wine prices.
     * @throws IllegalArgumentException if the input array is null or empty.
     * @return Maximum profit obtainable by selling the wines.
     */
    public static int wpbu(int[] arr) {
        if (arr == null || arr.length == 0) {
            throw new IllegalArgumentException("Input array cannot be null or empty.");
        }
        int n = arr.length;
        int[][] strg = new int[n][n];

        for (int slide = 0; slide <= n - 1; slide++) {
            for (int si = 0; si <= n - slide - 1; si++) {
                int ei = si + slide;
                int year = (n - (ei - si + 1)) + 1;
                if (si == ei) {
                    strg[si][ei] = arr[si] * year;
                } else {
                    int start = strg[si + 1][ei] + arr[si] * year;
                    int end = strg[si][ei - 1] + arr[ei] * year;

                    strg[si][ei] = Math.max(start, end);
                }
            }
        }
        return strg[0][n - 1];
    }
}

package com.thealgorithms.geometry;

import java.awt.geom.Point2D;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.NavigableSet;
import java.util.Objects;
import java.util.PriorityQueue;
import java.util.Set;
import java.util.SortedSet;
import java.util.TreeSet;

/**
 * Implementation of the Bentley–Ottmann algorithm for finding all intersection
 * points among a set of line segments in O((n + k) log n) time.
 *
 * <p>Uses a sweep-line approach with an event queue and status structure to
 * efficiently detect intersections in 2D plane geometry.</p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Bentley%E2%80%93Ottmann_algorithm">
 *      Bentley–Ottmann algorithm</a>
 */
public final class BentleyOttmann {

    private BentleyOttmann() {
    }

    private static final double EPS = 1e-9;
    private static double currentSweepX;

    /**
     * Represents a line segment with two endpoints.
     */
    public static class Segment {
        final Point2D.Double p1;
        final Point2D.Double p2;
        final int id; // Unique identifier for each segment

        Segment(Point2D.Double p1, Point2D.Double p2) {
            this.p1 = p1;
            this.p2 = p2;
            this.id = segmentCounter++;
        }

        private static int segmentCounter = 0;

        /**
         * Computes the y-coordinate of this segment at a given x value.
         */
        double getY(double x) {
            if (Math.abs(p2.x - p1.x) < EPS) {
                // Vertical segment: return midpoint y
                return (p1.y + p2.y) / 2.0;
            }
            double t = (x - p1.x) / (p2.x - p1.x);
            return p1.y + t * (p2.y - p1.y);
        }

        Point2D.Double leftPoint() {
            return p1.x < p2.x ? p1 : p1.x > p2.x ? p2 : p1.y < p2.y ? p1 : p2;
        }

        Point2D.Double rightPoint() {
            return p1.x > p2.x ? p1 : p1.x < p2.x ? p2 : p1.y > p2.y ? p1 : p2;
        }

        @Override
        public String toString() {
            return String.format("S%d[(%.2f, %.2f), (%.2f, %.2f)]", id, p1.x, p1.y, p2.x, p2.y);
        }
    }

    /**
     * Event types for the sweep line algorithm.
     */
    private enum EventType { START, END, INTERSECTION }

    /**
     * Represents an event in the event queue.
     */
    private static class Event implements Comparable<Event> {
        final Point2D.Double point;
        final EventType type;
        final Set<Segment> segments; // Segments involved in this event

        Event(Point2D.Double point, EventType type) {
            this.point = point;
            this.type = type;
            this.segments = new HashSet<>();
        }

        void addSegment(Segment s) {
            segments.add(s);
        }

        @Override
        public int compareTo(Event other) {
            // Sort by x-coordinate, then by y-coordinate
            int cmp = Double.compare(this.point.x, other.point.x);
            if (cmp == 0) {
                cmp = Double.compare(this.point.y, other.point.y);
            }
            if (cmp == 0) {
                // Process END events before START events at same point
                cmp = this.type.compareTo(other.type);
            }
            return cmp;
        }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Event e)) {
                return false;
            }
            return pointsEqual(this.point, e.point);
        }

        @Override
        public int hashCode() {
            return Objects.hash(Math.round(point.x * 1e6), Math.round(point.y * 1e6));
        }
    }

    /**
     * Comparator for segments in the status structure (sweep line).
     * Orders segments by their y-coordinate at the current sweep line position.
     */
    private static final class StatusComparator implements Comparator<Segment> {
        @Override
        public int compare(Segment s1, Segment s2) {
            if (s1.id == s2.id) {
                return 0;
            }

            double y1 = s1.getY(currentSweepX);
            double y2 = s2.getY(currentSweepX);

            int cmp = Double.compare(y1, y2);
            if (Math.abs(y1 - y2) < EPS) {
                // If y-coordinates are equal, use segment id for consistency
                return Integer.compare(s1.id, s2.id);
            }
            return cmp;
        }
    }

    /**
     * Finds all intersection points among a set of line segments.
     *
     * <p>An intersection point is reported when two or more segments cross or touch.
     * For overlapping segments, only actual crossing/touching points are reported,
     * not all points along the overlap.</p>
     *
     * @param segments list of line segments represented as pairs of points
     * @return a set of intersection points where segments meet or cross
     * @throws IllegalArgumentException if the list is null or contains null points
     */
    public static Set<Point2D.Double> findIntersections(List<Segment> segments) {
        if (segments == null) {
            throw new IllegalArgumentException("Segment list must not be null");
        }

        Segment.segmentCounter = 0; // Reset counter
        Set<Point2D.Double> intersections = new HashSet<>();
        PriorityQueue<Event> eventQueue = new PriorityQueue<>();
        TreeSet<Segment> status = new TreeSet<>(new StatusComparator());
        Map<Point2D.Double, Event> eventMap = new HashMap<>();

        // Initialize event queue with segment start and end points
        for (Segment s : segments) {
            Point2D.Double left = s.leftPoint();
            Point2D.Double right = s.rightPoint();

            Event startEvent = getOrCreateEvent(eventMap, left, EventType.START);
            startEvent.addSegment(s);

            Event endEvent = getOrCreateEvent(eventMap, right, EventType.END);
            endEvent.addSegment(s);
        }

        // Add all unique events to the queue
        for (Event e : eventMap.values()) {
            if (!e.segments.isEmpty()) {
                eventQueue.add(e);
            }
        }

        // Process events
        while (!eventQueue.isEmpty()) {
            Event event = eventQueue.poll();
            currentSweepX = event.point.x;

            handleEvent(event, status, eventQueue, eventMap, intersections);
        }

        return intersections;
    }

    private static Event getOrCreateEvent(Map<Point2D.Double, Event> eventMap, Point2D.Double point, EventType type) {
        // Find existing event at this point
        for (Map.Entry<Point2D.Double, Event> entry : eventMap.entrySet()) {
            if (pointsEqual(entry.getKey(), point)) {
                return entry.getValue();
            }
        }
        // Create new event
        Event event = new Event(point, type);
        eventMap.put(point, event);
        return event;
    }

    private static void handleEvent(Event event, TreeSet<Segment> status, PriorityQueue<Event> eventQueue, Map<Point2D.Double, Event> eventMap, Set<Point2D.Double> intersections) {
        Point2D.Double p = event.point;
        Set<Segment> segmentsAtPoint = new HashSet<>(event.segments);

        // Check segments in status structure (much smaller than allSegments)
        for (Segment s : status) {
            if (pointsEqual(s.p1, p) || pointsEqual(s.p2, p) || (onSegment(s, p) && !pointsEqual(s.p1, p) && !pointsEqual(s.p2, p))) {
                segmentsAtPoint.add(s);
            }
        }

        // If 2 or more segments meet at this point, it's an intersection
        if (segmentsAtPoint.size() >= 2) {
            intersections.add(p);
        }

        // Categorize segments
        Set<Segment> upperSegs = new HashSet<>(); // Segments starting at p
        Set<Segment> lowerSegs = new HashSet<>(); // Segments ending at p
        Set<Segment> containingSegs = new HashSet<>(); // Segments containing p in interior

        for (Segment s : segmentsAtPoint) {
            if (pointsEqual(s.leftPoint(), p)) {
                upperSegs.add(s);
            } else if (pointsEqual(s.rightPoint(), p)) {
                lowerSegs.add(s);
            } else {
                containingSegs.add(s);
            }
        }

        // Remove ending segments and segments containing p from status
        status.removeAll(lowerSegs);
        status.removeAll(containingSegs);

        // Update sweep line position slightly past the event
        currentSweepX = p.x + EPS;

        // Add starting segments and re-add containing segments
        status.addAll(upperSegs);
        status.addAll(containingSegs);

        if (upperSegs.isEmpty() && containingSegs.isEmpty()) {
            // Find neighbors and check for new intersections
            Segment sl = getNeighbor(status, lowerSegs, true);
            Segment sr = getNeighbor(status, lowerSegs, false);
            if (sl != null && sr != null) {
                findNewEvent(sl, sr, p, eventQueue, eventMap);
            }
        } else {
            Set<Segment> unionSegs = new HashSet<>(upperSegs);
            unionSegs.addAll(containingSegs);

            Segment leftmost = getLeftmost(unionSegs, status);
            Segment rightmost = getRightmost(unionSegs, status);

            if (leftmost != null) {
                Segment sl = status.lower(leftmost);
                if (sl != null) {
                    findNewEvent(sl, leftmost, p, eventQueue, eventMap);
                }
            }

            if (rightmost != null) {
                Segment sr = status.higher(rightmost);
                if (sr != null) {
                    findNewEvent(rightmost, sr, p, eventQueue, eventMap);
                }
            }
        }
    }

    private static Segment getNeighbor(NavigableSet<Segment> status, Set<Segment> removed, boolean lower) {
        if (removed.isEmpty()) {
            return null;
        }
        Segment ref = removed.iterator().next();
        return lower ? status.lower(ref) : status.higher(ref);
    }

    private static Segment getLeftmost(Set<Segment> segments, SortedSet<Segment> status) {
        Segment leftmost = null;
        for (Segment s : segments) {
            if (leftmost == null || Objects.requireNonNull(status.comparator()).compare(s, leftmost) < 0) {
                leftmost = s;
            }
        }
        return leftmost;
    }

    private static Segment getRightmost(Set<Segment> segments, SortedSet<Segment> status) {
        Segment rightmost = null;
        for (Segment s : segments) {
            if (status.comparator() != null && (rightmost == null || status.comparator().compare(s, rightmost) > 0)) {
                rightmost = s;
            }
        }
        return rightmost;
    }

    private static void findNewEvent(Segment s1, Segment s2, Point2D.Double currentPoint, PriorityQueue<Event> eventQueue, Map<Point2D.Double, Event> eventMap) {
        Point2D.Double intersection = getIntersection(s1, s2);

        if (intersection != null && intersection.x > currentPoint.x - EPS && !pointsEqual(intersection, currentPoint)) {

            // Check if event already exists
            boolean exists = false;
            for (Map.Entry<Point2D.Double, Event> entry : eventMap.entrySet()) {
                if (pointsEqual(entry.getKey(), intersection)) {
                    exists = true;
                    Event existingEvent = entry.getValue();
                    existingEvent.addSegment(s1);
                    existingEvent.addSegment(s2);
                    break;
                }
            }

            if (!exists) {
                Event newEvent = new Event(intersection, EventType.INTERSECTION);
                newEvent.addSegment(s1);
                newEvent.addSegment(s2);
                eventMap.put(intersection, newEvent);
                eventQueue.add(newEvent);
            }
        }
    }

    private static Point2D.Double getIntersection(Segment s1, Segment s2) {
        double x1 = s1.p1.x;
        double y1 = s1.p1.y;
        double x2 = s1.p2.x;
        double y2 = s1.p2.y;
        double x3 = s2.p1.x;
        double y3 = s2.p1.y;
        double x4 = s2.p2.x;
        double y4 = s2.p2.y;

        double denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);

        if (Math.abs(denom) < EPS) {
            // Parallel or collinear
            if (areCollinear(s1, s2)) {
                // For collinear segments, check if they overlap
                // Return any overlapping point
                List<Point2D.Double> overlapPoints = new ArrayList<>();

                if (onSegment(s1, s2.p1)) {
                    overlapPoints.add(s2.p1);
                }
                if (onSegment(s1, s2.p2)) {
                    overlapPoints.add(s2.p2);
                }
                if (onSegment(s2, s1.p1)) {
                    overlapPoints.add(s1.p1);
                }
                if (onSegment(s2, s1.p2)) {
                    overlapPoints.add(s1.p2);
                }

                // Remove duplicates and return the first point
                if (!overlapPoints.isEmpty()) {
                    // Find the point that's not an endpoint of both segments
                    for (Point2D.Double pt : overlapPoints) {
                        boolean isS1Endpoint = pointsEqual(pt, s1.p1) || pointsEqual(pt, s1.p2);
                        boolean isS2Endpoint = pointsEqual(pt, s2.p1) || pointsEqual(pt, s2.p2);

                        // If it's an endpoint of both, it's a touching point
                        if (isS1Endpoint && isS2Endpoint) {
                            return pt;
                        }
                    }
                    // Return the first overlap point
                    return overlapPoints.getFirst();
                }
            }
            return null;
        }

        double t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom;
        double u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / denom;

        if (t >= -EPS && t <= 1 + EPS && u >= -EPS && u <= 1 + EPS) {
            double px = x1 + t * (x2 - x1);
            double py = y1 + t * (y2 - y1);
            return new Point2D.Double(px, py);
        }

        return null;
    }

    private static boolean areCollinear(Segment s1, Segment s2) {
        double cross1 = crossProduct(s1.p1, s1.p2, s2.p1);
        double cross2 = crossProduct(s1.p1, s1.p2, s2.p2);
        return Math.abs(cross1) < EPS && Math.abs(cross2) < EPS;
    }

    private static double crossProduct(Point2D.Double a, Point2D.Double b, Point2D.Double c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    private static boolean onSegment(Segment s, Point2D.Double p) {
        return p.x >= Math.min(s.p1.x, s.p2.x) - EPS && p.x <= Math.max(s.p1.x, s.p2.x) + EPS && p.y >= Math.min(s.p1.y, s.p2.y) - EPS && p.y <= Math.max(s.p1.y, s.p2.y) + EPS && Math.abs(crossProduct(s.p1, s.p2, p)) < EPS;
    }

    private static boolean pointsEqual(Point2D.Double p1, Point2D.Double p2) {
        return Math.abs(p1.x - p2.x) < EPS && Math.abs(p1.y - p2.y) < EPS;
    }
}

package com.thealgorithms.geometry;

import java.awt.Point;
import java.util.ArrayList;
import java.util.List;

/**
 * The {@code BresenhamLine} class implements the Bresenham's line algorithm,
 * which is an efficient way to determine the points of a straight line
 * between two given points in a 2D space.
 *
 * <p>This algorithm uses integer arithmetic to calculate the points,
 * making it suitable for rasterization in computer graphics.</p>
 *
 * For more information, please visit {@link https://en.wikipedia.org/wiki/Bresenham%27s_line_algorithm}
 */
public final class BresenhamLine {

    private BresenhamLine() {
        // Private constructor to prevent instantiation.
    }

    /**
     * Finds the list of points that form a straight line between two endpoints.
     *
     * @param x0 the x-coordinate of the starting point
     * @param y0 the y-coordinate of the starting point
     * @param x1 the x-coordinate of the ending point
     * @param y1 the y-coordinate of the ending point
     * @return a {@code List<Point>} containing all points on the line
     */
    public static List<Point> findLine(int x0, int y0, int x1, int y1) {
        List<Point> line = new ArrayList<>();

        // Calculate differences and steps for each axis
        int dx = Math.abs(x1 - x0); // Change in x
        int dy = Math.abs(y1 - y0); // Change in y
        int sx = (x0 < x1) ? 1 : -1; // Step in x direction
        int sy = (y0 < y1) ? 1 : -1; // Step in y direction
        int err = dx - dy; // Initial error term

        // Loop until we reach the endpoint
        while (true) {
            line.add(new Point(x0, y0)); // Add current point to the line

            // Check if we've reached the endpoint
            if (x0 == x1 && y0 == y1) {
                break; // Exit loop if endpoint is reached
            }

            // Calculate error term doubled for decision making
            final int e2 = err * 2;

            // Adjust x coordinate if necessary
            if (e2 > -dy) {
                err -= dy; // Update error term
                x0 += sx; // Move to next point in x direction
            }

            // Adjust y coordinate if necessary
            if (e2 < dx) {
                err += dx; // Update error term
                y0 += sy; // Move to next point in y direction
            }
        }

        return line; // Return the list of points forming the line
    }
}

package com.thealgorithms.geometry;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

/**
 * A class providing algorithms to compute the convex hull of a set of points
 * using brute-force and recursive methods.
 *
 * Convex hull: The smallest convex polygon that contains all the given points.
 *
 * Algorithms provided:
 * 1. Brute-Force Method
 * 2. Recursive (Divide-and-Conquer) Method
 *
 * @author Hardvan
 */
public final class ConvexHull {
    private ConvexHull() {
    }

    private static boolean checkPointOrientation(Point i, Point j, Point k) {
        int detK = Point.orientation(i, j, k);
        if (detK > 0) {
            return true; // pointsLeftOfIJ
        } else if (detK < 0) {
            return false; // pointsRightOfIJ
        } else {
            return k.compareTo(i) >= 0 && k.compareTo(j) <= 0;
        }
    }

    public static List<Point> convexHullBruteForce(List<Point> points) {
        Set<Point> convexSet = new TreeSet<>(Comparator.naturalOrder());

        for (int i = 0; i < points.size() - 1; i++) {
            for (int j = i + 1; j < points.size(); j++) {
                boolean allPointsOnOneSide = true;
                boolean leftSide = checkPointOrientation(points.get(i), points.get(j), points.get((i + 1) % points.size()));

                for (int k = 0; k < points.size(); k++) {
                    if (k != i && k != j && checkPointOrientation(points.get(i), points.get(j), points.get(k)) != leftSide) {
                        allPointsOnOneSide = false;
                        break;
                    }
                }

                if (allPointsOnOneSide) {
                    convexSet.add(points.get(i));
                    convexSet.add(points.get(j));
                }
            }
        }

        return new ArrayList<>(convexSet);
    }

    /**
     * Computes the convex hull using a recursive divide-and-conquer approach.
     * Returns points in counter-clockwise order starting from the bottom-most, left-most point.
     *
     * @param points the input points
     * @return the convex hull points in counter-clockwise order
     */
    public static List<Point> convexHullRecursive(List<Point> points) {
        if (points.size() < 3) {
            List<Point> result = new ArrayList<>(points);
            Collections.sort(result);
            return result;
        }

        Collections.sort(points);
        Set<Point> convexSet = new HashSet<>();
        Point leftMostPoint = points.getFirst();
        Point rightMostPoint = points.getLast();

        convexSet.add(leftMostPoint);
        convexSet.add(rightMostPoint);

        List<Point> upperHull = new ArrayList<>();
        List<Point> lowerHull = new ArrayList<>();

        for (int i = 1; i < points.size() - 1; i++) {
            int det = Point.orientation(leftMostPoint, rightMostPoint, points.get(i));
            if (det > 0) {
                upperHull.add(points.get(i));
            } else if (det < 0) {
                lowerHull.add(points.get(i));
            }
        }

        constructHull(upperHull, leftMostPoint, rightMostPoint, convexSet);
        constructHull(lowerHull, rightMostPoint, leftMostPoint, convexSet);

        // Convert to list and sort in counter-clockwise order
        return sortCounterClockwise(new ArrayList<>(convexSet));
    }

    private static void constructHull(Collection<Point> points, Point left, Point right, Set<Point> convexSet) {
        if (!points.isEmpty()) {
            Point extremePoint = null;
            int extremePointDistance = Integer.MIN_VALUE;
            List<Point> candidatePoints = new ArrayList<>();

            for (Point p : points) {
                int det = Point.orientation(left, right, p);
                if (det > 0) {
                    candidatePoints.add(p);
                    if (det > extremePointDistance) {
                        extremePointDistance = det;
                        extremePoint = p;
                    }
                }
            }

            if (extremePoint != null) {
                constructHull(candidatePoints, left, extremePoint, convexSet);
                convexSet.add(extremePoint);
                constructHull(candidatePoints, extremePoint, right, convexSet);
            }
        }
    }

    /**
     * Sorts convex hull points in counter-clockwise order starting from
     * the bottom-most, left-most point.
     *
     * @param hullPoints the unsorted convex hull points
     * @return the points sorted in counter-clockwise order
     */
    private static List<Point> sortCounterClockwise(List<Point> hullPoints) {
        if (hullPoints.size() <= 2) {
            Collections.sort(hullPoints);
            return hullPoints;
        }

        // Find the bottom-most, left-most point (pivot)
        Point pivot = hullPoints.getFirst();
        for (Point p : hullPoints) {
            if (p.y() < pivot.y() || (p.y() == pivot.y() && p.x() < pivot.x())) {
                pivot = p;
            }
        }

        // Sort other points by polar angle with respect to pivot
        final Point finalPivot = pivot;
        List<Point> sorted = new ArrayList<>(hullPoints);
        sorted.remove(finalPivot);

        sorted.sort((p1, p2) -> {
            int crossProduct = Point.orientation(finalPivot, p1, p2);

            if (crossProduct == 0) {
                // Collinear points: sort by distance from pivot (closer first for convex hull)
                long dist1 = distanceSquared(finalPivot, p1);
                long dist2 = distanceSquared(finalPivot, p2);
                return Long.compare(dist1, dist2);
            }

            // Positive cross product means p2 is counter-clockwise from p1
            // We want counter-clockwise order, so if p2 is CCW from p1, p1 should come first
            return -crossProduct;
        });

        // Build result with pivot first, filtering out intermediate collinear points
        List<Point> result = new ArrayList<>();
        result.add(finalPivot);

        if (!sorted.isEmpty()) {
            // This loop iterates through the points sorted by angle.
            // For points that are collinear with the pivot, we only want the one that is farthest away.
            // The sort places closer points first.
            for (int i = 0; i < sorted.size() - 1; i++) {
                // Check the orientation of the pivot, the current point, and the next point.
                int orientation = Point.orientation(finalPivot, sorted.get(i), sorted.get(i + 1));

                // If the orientation is not 0, it means the next point (i+1) is at a new angle.
                // Therefore, the current point (i) must be the farthest point at its angle. We keep it.
                if (orientation != 0) {
                    result.add(sorted.get(i));
                }
                // If the orientation is 0, the points are collinear. We discard the current point (i)
                // because it is closer to the pivot than the next point (i+1).
            }
            // Always add the very last point from the sorted list. It is either the only point
            // at its angle, or it's the farthest among a set of collinear points.
            result.add(sorted.getLast());
        }

        return result;
    }

    /**
     * Computes the squared distance between two points to avoid floating point operations.
     */
    private static long distanceSquared(Point p1, Point p2) {
        long dx = (long) p1.x() - p2.x();
        long dy = (long) p1.y() - p2.y();
        return dx * dx + dy * dy;
    }
}

package com.thealgorithms.geometry;

import java.awt.Point;
import java.util.ArrayList;
import java.util.List;

/**
 * The {@code DDALine} class implements the Digital Differential Analyzer (DDA)
 * line drawing algorithm. It computes points along a line between two given
 * endpoints using floating-point arithmetic.
 *
 * The algorithm is straightforward but less efficient compared to
 * Bresenham’s line algorithm, since it relies on floating-point operations.
 *
 * For more information, please visit {@link https://en.wikipedia.org/wiki/Digital_differential_analyzer_(graphics_algorithm)}
 */
public final class DDALine {

    private DDALine() {
        // Prevent instantiation
    }

    /**
     * Finds the list of points forming a line between two endpoints using DDA.
     *
     * @param x0 the x-coordinate of the starting point
     * @param y0 the y-coordinate of the starting point
     * @param x1 the x-coordinate of the ending point
     * @param y1 the y-coordinate of the ending point
     * @return an unmodifiable {@code List<Point>} containing all points on the line
     */
    public static List<Point> findLine(int x0, int y0, int x1, int y1) {
        int dx = x1 - x0;
        int dy = y1 - y0;

        int steps = Math.max(Math.abs(dx), Math.abs(dy)); // number of steps

        double xIncrement = dx / (double) steps;
        double yIncrement = dy / (double) steps;

        double x = x0;
        double y = y0;

        List<Point> line = new ArrayList<>(steps + 1);

        for (int i = 0; i <= steps; i++) {
            line.add(new Point((int) Math.round(x), (int) Math.round(y)));
            x += xIncrement;
            y += yIncrement;
        }

        return line;
    }
}

package com.thealgorithms.geometry;
/**
 * This Class implements the Haversine formula to calculate the distance between two points on a sphere (like Earth) from their latitudes and longitudes.
 *
 * The Haversine formula is used in navigation and mapping to find the great-circle distance,
 * which is the shortest distance between two points along the surface of a sphere. It is often
 * used to calculate the "as the crow flies" distance between two geographical locations.
 *
 * The formula is reliable for all distances, including small ones, and avoids issues with
 * numerical instability that can affect other methods.
 *
 * @see "https://en.wikipedia.org/wiki/Haversine_formula" - Wikipedia
 */
public final class Haversine {

    // Average radius of Earth in kilometers
    private static final double EARTH_RADIUS_KM = 6371.0;

    /**
     * Private constructor to prevent instantiation of this utility class.
     */
    private Haversine() {
    }

    /**
     * Calculates the great-circle distance between two points on the earth
     * (specified in decimal degrees).
     *
     * @param lat1 Latitude of the first point in decimal degrees.
     * @param lon1 Longitude of the first point in decimal degrees.
     * @param lat2 Latitude of the second point in decimal degrees.
     * @param lon2 Longitude of the second point in decimal degrees.
     * @return The distance between the two points in kilometers.
     */
    public static double haversine(double lat1, double lon1, double lat2, double lon2) {
        // Convert latitude and longitude from degrees to radians
        double dLat = Math.toRadians(lat2 - lat1);
        double dLon = Math.toRadians(lon2 - lon1);

        double lat1Rad = Math.toRadians(lat1);
        double lat2Rad = Math.toRadians(lat2);

        // Apply the Haversine formula
        double a = Math.pow(Math.sin(dLat / 2), 2) + Math.pow(Math.sin(dLon / 2), 2) * Math.cos(lat1Rad) * Math.cos(lat2Rad);
        double c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

        return EARTH_RADIUS_KM * c;
    }
}

package com.thealgorithms.geometry;

import java.awt.geom.Point2D;
import java.util.Optional;

/**
 * Utility methods for checking and computing 2D line segment intersections.
 */
public final class LineIntersection {
    private LineIntersection() {
    }

    /**
     * Checks whether two line segments intersect.
     *
     * @param p1 first endpoint of segment 1
     * @param p2 second endpoint of segment 1
     * @param q1 first endpoint of segment 2
     * @param q2 second endpoint of segment 2
     * @return true when the segments intersect (including touching endpoints)
     */
    public static boolean intersects(Point p1, Point p2, Point q1, Point q2) {
        int o1 = orientation(p1, p2, q1);
        int o2 = orientation(p1, p2, q2);
        int o3 = orientation(q1, q2, p1);
        int o4 = orientation(q1, q2, p2);

        if (o1 != o2 && o3 != o4) {
            return true;
        }

        if (o1 == 0 && onSegment(p1, q1, p2)) {
            return true;
        }
        if (o2 == 0 && onSegment(p1, q2, p2)) {
            return true;
        }
        if (o3 == 0 && onSegment(q1, p1, q2)) {
            return true;
        }
        if (o4 == 0 && onSegment(q1, p2, q2)) {
            return true;
        }

        return false;
    }

    /**
     * Computes the single geometric intersection point between two non-parallel
     * segments when it exists.
     *
     * <p>For parallel/collinear overlap, this method returns {@code Optional.empty()}.
     *
     * @param p1 first endpoint of segment 1
     * @param p2 second endpoint of segment 1
     * @param q1 first endpoint of segment 2
     * @param q2 second endpoint of segment 2
     * @return the intersection point when uniquely defined and on both segments
     */
    public static Optional<Point2D.Double> intersectionPoint(Point p1, Point p2, Point q1, Point q2) {
        if (!intersects(p1, p2, q1, q2)) {
            return Optional.empty();
        }

        long x1 = p1.x();
        long y1 = p1.y();
        long x2 = p2.x();
        long y2 = p2.y();
        long x3 = q1.x();
        long y3 = q1.y();
        long x4 = q2.x();
        long y4 = q2.y();

        long denominator = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
        if (denominator == 0L) {
            return sharedEndpoint(p1, p2, q1, q2);
        }

        long determinant1 = x1 * y2 - y1 * x2;
        long determinant2 = x3 * y4 - y3 * x4;
        long numeratorX = determinant1 * (x3 - x4) - (x1 - x2) * determinant2;
        long numeratorY = determinant1 * (y3 - y4) - (y1 - y2) * determinant2;

        return Optional.of(new Point2D.Double(numeratorX / (double) denominator, numeratorY / (double) denominator));
    }

    private static int orientation(Point a, Point b, Point c) {
        long cross = ((long) b.x() - a.x()) * ((long) c.y() - a.y()) - ((long) b.y() - a.y()) * ((long) c.x() - a.x());
        return Long.compare(cross, 0L);
    }

    private static Optional<Point2D.Double> sharedEndpoint(Point p1, Point p2, Point q1, Point q2) {
        if (p1.equals(q1) || p1.equals(q2)) {
            return Optional.of(new Point2D.Double(p1.x(), p1.y()));
        }
        if (p2.equals(q1) || p2.equals(q2)) {
            return Optional.of(new Point2D.Double(p2.x(), p2.y()));
        }
        return Optional.empty();
    }

    private static boolean onSegment(Point a, Point b, Point c) {
        return b.x() >= Math.min(a.x(), c.x()) && b.x() <= Math.max(a.x(), c.x()) && b.y() >= Math.min(a.y(), c.y()) && b.y() <= Math.max(a.y(), c.y());
    }
}

package com.thealgorithms.geometry;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

/**
 * Class to represent the Midpoint Circle Algorithm.
 * This algorithm calculates points on the circumference of a circle
 * using integer arithmetic for efficient computation.
 */
public final class MidpointCircle {

    private MidpointCircle() {
        // Private Constructor to prevent instantiation.
    }

    /**
     * Generates points on the circumference of a circle using the midpoint circle algorithm.
     *
     * @param centerX The x-coordinate of the circle's center.
     * @param centerY The y-coordinate of the circle's center.
     * @param radius  The radius of the circle.
     * @return A list of points on the circle, each represented as an int[] with 2 elements [x, y].
     */
    public static List<int[]> generateCirclePoints(int centerX, int centerY, int radius) {
        List<int[]> points = new ArrayList<>();

        // Special case for radius 0, only the center point should be added.
        if (radius == 0) {
            points.add(new int[] {centerX, centerY});
            return points;
        }

        // Start at (radius, 0)
        int x = radius;
        int y = 0;

        // Decision parameter
        int p = 1 - radius;

        // Add the initial points in all octants
        addSymmetricPoints(points, centerX, centerY, x, y);

        // Iterate while x > y
        while (x > y) {
            y++;

            if (p <= 0) {
                // Midpoint is inside or on the circle
                p = p + 2 * y + 1;
            } else {
                // Midpoint is outside the circle
                x--;
                p = p + 2 * y - 2 * x + 1;
            }

            // Add points for this (x, y)
            addSymmetricPoints(points, centerX, centerY, x, y);
        }

        return points;
    }

    /**
     * Adds the symmetric points in all octants of the circle based on the current x and y values.
     *
     * @param points  The list to which symmetric points will be added.
     * @param centerX The x-coordinate of the circle's center.
     * @param centerY The y-coordinate of the circle's center.
     * @param x       The current x-coordinate on the circumference.
     * @param y       The current y-coordinate on the circumference.
     */
    private static void addSymmetricPoints(Collection<int[]> points, int centerX, int centerY, int x, int y) {
        // Octant symmetry points
        points.add(new int[] {centerX + x, centerY + y});
        points.add(new int[] {centerX - x, centerY + y});
        points.add(new int[] {centerX + x, centerY - y});
        points.add(new int[] {centerX - x, centerY - y});
        points.add(new int[] {centerX + y, centerY + x});
        points.add(new int[] {centerX - y, centerY + x});
        points.add(new int[] {centerX + y, centerY - x});
        points.add(new int[] {centerX - y, centerY - x});
    }
}

package com.thealgorithms.geometry;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

/**
 * The MidpointEllipse class implements the Midpoint Ellipse Drawing Algorithm.
 * This algorithm efficiently computes the points on an ellipse by dividing it into two regions
 * and using decision parameters to determine the next point to plot.
 */
public final class MidpointEllipse {

    private MidpointEllipse() {
        // Private constructor to prevent instantiation
    }

    /**
     * Draws an ellipse using the Midpoint Ellipse Algorithm.
     *
     * @param centerX the x-coordinate of the center of the ellipse
     * @param centerY the y-coordinate of the center of the ellipse
     * @param a the length of the semi-major axis (horizontal radius)
     * @param b the length of the semi-minor axis (vertical radius)
     * @return a list of points (represented as int arrays) that form the ellipse
     */
    public static List<int[]> drawEllipse(int centerX, int centerY, int a, int b) {
        List<int[]> points = new ArrayList<>();

        // Handle degenerate cases with early returns
        if (a == 0 && b == 0) {
            points.add(new int[] {centerX, centerY}); // Only the center point
            return points;
        }

        if (a == 0) {
            // Semi-major axis is zero, create a vertical line
            for (int y = centerY - b; y <= centerY + b; y++) {
                points.add(new int[] {centerX, y});
            }
            return points; // Early return
        }

        if (b == 0) {
            // Semi-minor axis is zero, create a horizontal line
            for (int x = centerX - a; x <= centerX + a; x++) {
                points.add(new int[] {x, centerY});
            }
            return points; // Early return
        }

        // Normal case: Non-degenerate ellipse
        computeEllipsePoints(points, centerX, centerY, a, b);

        return points; // Return all calculated points of the ellipse
    }

    /**
     * Computes points of a non-degenerate ellipse using the Midpoint Ellipse Algorithm.
     *
     * @param points    the list to which points will be added
     * @param centerX  the x-coordinate of the center of the ellipse
     * @param centerY  the y-coordinate of the center of the ellipse
     * @param a        the length of the semi-major axis (horizontal radius)
     * @param b        the length of the semi-minor axis (vertical radius)
     */
    private static void computeEllipsePoints(Collection<int[]> points, int centerX, int centerY, int a, int b) {
        int x = 0; // Initial x-coordinate
        int y = b; // Initial y-coordinate

        // Region 1: Initial decision parameter
        double d1 = (b * b) - (a * a * b) + (0.25 * a * a); // Decision variable for region 1
        double dx = 2.0 * b * b * x; // Change in x
        double dy = 2.0 * a * a * y; // Change in y

        // Region 1: When the slope is less than 1
        while (dx < dy) {
            addEllipsePoints(points, centerX, centerY, x, y);

            // Update decision parameter and variables
            if (d1 < 0) {
                x++;
                dx += (2 * b * b); // Update x change
                d1 += dx + (b * b); // Update decision parameter
            } else {
                x++;
                y--;
                dx += (2 * b * b); // Update x change
                dy -= (2 * a * a); // Update y change
                d1 += dx - dy + (b * b); // Update decision parameter
            }
        }

        // Region 2: Initial decision parameter for the second region
        double d2 = b * b * (x + 0.5) * (x + 0.5) + a * a * (y - 1) * (y - 1) - a * a * b * b;

        // Region 2: When the slope is greater than or equal to 1
        while (y >= 0) {
            addEllipsePoints(points, centerX, centerY, x, y);

            // Update decision parameter and variables
            if (d2 > 0) {
                y--;
                dy -= (2 * a * a); // Update y change
                d2 += (a * a) - dy; // Update decision parameter
            } else {
                y--;
                x++;
                dx += (2 * b * b); // Update x change
                dy -= (2 * a * a); // Update y change
                d2 += dx - dy + (a * a); // Update decision parameter
            }
        }
    }

    /**
     * Adds points for all four quadrants of the ellipse based on symmetry.
     *
     * @param points    the list to which points will be added
     * @param centerX  the x-coordinate of the center of the ellipse
     * @param centerY  the y-coordinate of the center of the ellipse
     * @param x        the x-coordinate relative to the center
     * @param y        the y-coordinate relative to the center
     */
    private static void addEllipsePoints(Collection<int[]> points, int centerX, int centerY, int x, int y) {
        points.add(new int[] {centerX + x, centerY + y});
        points.add(new int[] {centerX - x, centerY + y});
        points.add(new int[] {centerX + x, centerY - y});
        points.add(new int[] {centerX - x, centerY - y});
    }
}

package com.thealgorithms.geometry;

import java.util.Comparator;

public record Point(int x, int y) implements Comparable<Point> {

    @Override
    public int compareTo(Point other) {
        int cmpY = Integer.compare(this.y, other.y);
        return cmpY != 0 ? cmpY : Integer.compare(this.x, other.x);
    }

    @Override
    public String toString() {
        return String.format("(%d, %d)", x, y);
    }

    public Comparator<Point> polarOrder() {
        return new PolarOrder();
    }

    public static int orientation(Point a, Point b, Point c) {
        return Integer.compare((b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x), 0);
    }

    private final class PolarOrder implements Comparator<Point> {
        @Override
        public int compare(Point p1, Point p2) {
            int dx1 = p1.x - x;
            int dy1 = p1.y - y;
            int dx2 = p2.x - x;
            int dy2 = p2.y - y;

            if (dy1 >= 0 && dy2 < 0) {
                return -1; // p1 above p2
            } else if (dy2 >= 0 && dy1 < 0) {
                return 1; // p1 below p2
            } else if (dy1 == 0 && dy2 == 0) { // Collinear and horizontal
                return Integer.compare(dx2, dx1);
            } else {
                return -orientation(Point.this, p1, p2); // Compare orientation
            }
        }
    }
}

package com.thealgorithms.geometry;

import java.awt.Point;
import java.util.ArrayList;
import java.util.List;

/**
 * The {@code WusLine} class implements Xiaolin Wu's line drawing algorithm,
 * which produces anti-aliased lines by varying pixel brightness
 * according to the line's proximity to pixel centers.
 *
 * This implementation returns the pixel coordinates along with
 * their associated intensity values (in range [0.0, 1.0]), allowing
 * rendering systems to blend accordingly.
 *
 * The algorithm works by:
 * - Computing a line's intersection with pixel boundaries
 * - Assigning intensity values based on distance from pixel centers
 * - Drawing pairs of pixels perpendicular to the line's direction
 *
 * Reference: Xiaolin Wu, "An Efficient Antialiasing Technique",
 * Computer Graphics (SIGGRAPH '91 Proceedings).
 *
 */
public final class WusLine {

    private WusLine() {
        // Utility class; prevent instantiation.
    }

    /**
     * Represents a pixel and its intensity for anti-aliased rendering.
     *
     * The intensity value determines how bright the pixel should be drawn,
     * with 1.0 being fully opaque and 0.0 being fully transparent.
     */
    public static class Pixel {
        /** The pixel's coordinate on the screen. */
        public final Point point;

        /** The pixel's intensity value, clamped to the range [0.0, 1.0]. */
        public final double intensity;

        /**
         * Constructs a new Pixel with the given coordinates and intensity.
         *
         * @param x the x-coordinate of the pixel
         * @param y the y-coordinate of the pixel
         * @param intensity the brightness/opacity of the pixel, will be clamped to [0.0, 1.0]
         */
        public Pixel(int x, int y, double intensity) {
            this.point = new Point(x, y);
            this.intensity = Math.clamp(intensity, 0.0, 1.0);
        }
    }

    /**
     * Internal class to hold processed endpoint data.
     */
    private static class EndpointData {
        final int xPixel;
        final int yPixel;
        final double yEnd;
        final double xGap;

        EndpointData(int xPixel, int yPixel, double yEnd, double xGap) {
            this.xPixel = xPixel;
            this.yPixel = yPixel;
            this.yEnd = yEnd;
            this.xGap = xGap;
        }
    }

    /**
     * Draws an anti-aliased line using Wu's algorithm.
     *
     * The algorithm produces smooth lines by drawing pairs of pixels at each
     * x-coordinate (or y-coordinate for steep lines), with intensities based on
     * the line's distance from pixel centers.
     *
     * @param x0 the x-coordinate of the line's start point
     * @param y0 the y-coordinate of the line's start point
     * @param x1 the x-coordinate of the line's end point
     * @param y1 the y-coordinate of the line's end point
     * @return a list of {@link Pixel} objects representing the anti-aliased line,
     *         ordered from start to end
     */
    public static List<Pixel> drawLine(int x0, int y0, int x1, int y1) {
        List<Pixel> pixels = new ArrayList<>();

        // Determine if the line is steep (more vertical than horizontal)
        boolean steep = Math.abs(y1 - y0) > Math.abs(x1 - x0);

        if (steep) {
            // For steep lines, swap x and y coordinates to iterate along y-axis
            int temp = x0;
            x0 = y0;
            y0 = temp;

            temp = x1;
            x1 = y1;
            y1 = temp;
        }

        if (x0 > x1) {
            // Ensure we always draw from left to right
            int temp = x0;
            x0 = x1;
            x1 = temp;

            temp = y0;
            y0 = y1;
            y1 = temp;
        }

        // Calculate the line's slope
        double deltaX = x1 - (double) x0;
        double deltaY = y1 - (double) y0;
        double gradient = (deltaX == 0) ? 1.0 : deltaY / deltaX;

        // Process the first endpoint
        EndpointData firstEndpoint = processEndpoint(x0, y0, gradient, true);
        addEndpointPixels(pixels, firstEndpoint, steep);

        // Process the second endpoint
        EndpointData secondEndpoint = processEndpoint(x1, y1, gradient, false);
        addEndpointPixels(pixels, secondEndpoint, steep);

        // Draw the main line between endpoints
        drawMainLine(pixels, firstEndpoint, secondEndpoint, gradient, steep);

        return pixels;
    }

    /**
     * Processes a line endpoint to determine its pixel coordinates and intensities.
     *
     * @param x the x-coordinate of the endpoint
     * @param y the y-coordinate of the endpoint
     * @param gradient the slope of the line
     * @param isStart true if this is the start endpoint, false if it's the end
     * @return an {@link EndpointData} object containing processed endpoint information
     */
    private static EndpointData processEndpoint(double x, double y, double gradient, boolean isStart) {
        double xEnd = round(x);
        double yEnd = y + gradient * (xEnd - x);
        double xGap = isStart ? rfpart(x + 0.5) : fpart(x + 0.5);

        int xPixel = (int) xEnd;
        int yPixel = (int) Math.floor(yEnd);

        return new EndpointData(xPixel, yPixel, yEnd, xGap);
    }

    /**
     * Adds the two endpoint pixels (one above, one below the line) to the pixel list.
     *
     * @param pixels the list to add pixels to
     * @param endpoint the endpoint data containing coordinates and gaps
     * @param steep true if the line is steep (coordinates should be swapped)
     */
    private static void addEndpointPixels(List<Pixel> pixels, EndpointData endpoint, boolean steep) {
        double fractionalY = fpart(endpoint.yEnd);
        double complementFractionalY = rfpart(endpoint.yEnd);

        if (steep) {
            pixels.add(new Pixel(endpoint.yPixel, endpoint.xPixel, complementFractionalY * endpoint.xGap));
            pixels.add(new Pixel(endpoint.yPixel + 1, endpoint.xPixel, fractionalY * endpoint.xGap));
        } else {
            pixels.add(new Pixel(endpoint.xPixel, endpoint.yPixel, complementFractionalY * endpoint.xGap));
            pixels.add(new Pixel(endpoint.xPixel, endpoint.yPixel + 1, fractionalY * endpoint.xGap));
        }
    }

    /**
     * Draws the main portion of the line between the two endpoints.
     *
     * @param pixels the list to add pixels to
     * @param firstEndpoint the processed start endpoint
     * @param secondEndpoint the processed end endpoint
     * @param gradient the slope of the line
     * @param steep true if the line is steep (coordinates should be swapped)
     */
    private static void drawMainLine(List<Pixel> pixels, EndpointData firstEndpoint, EndpointData secondEndpoint, double gradient, boolean steep) {
        // Start y-intersection after the first endpoint
        double intersectionY = firstEndpoint.yEnd + gradient;

        // Iterate through x-coordinates between the endpoints
        for (int x = firstEndpoint.xPixel + 1; x < secondEndpoint.xPixel; x++) {
            int yFloor = (int) Math.floor(intersectionY);
            double fractionalPart = fpart(intersectionY);
            double complementFractionalPart = rfpart(intersectionY);

            if (steep) {
                pixels.add(new Pixel(yFloor, x, complementFractionalPart));
                pixels.add(new Pixel(yFloor + 1, x, fractionalPart));
            } else {
                pixels.add(new Pixel(x, yFloor, complementFractionalPart));
                pixels.add(new Pixel(x, yFloor + 1, fractionalPart));
            }

            intersectionY += gradient;
        }
    }

    /**
     * Returns the fractional part of a number.
     *
     * @param x the input number
     * @return the fractional part (always in range [0.0, 1.0))
     */
    private static double fpart(double x) {
        return x - Math.floor(x);
    }

    /**
     * Returns the reverse fractional part of a number (1 - fractional part).
     *
     * @param x the input number
     * @return 1.0 minus the fractional part (always in range (0.0, 1.0])
     */
    private static double rfpart(double x) {
        return 1.0 - fpart(x);
    }

    /**
     * Rounds a number to the nearest integer.
     *
     * @param x the input number
     * @return the nearest integer value as a double
     */
    private static double round(double x) {
        return Math.floor(x + 0.5);
    }
}

package com.thealgorithms.graph;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Merges account records using Disjoint Set Union (Union-Find) on shared emails.
 *
 * <p>Each account is expected to be a list where the first element is the user name and the
 * remaining elements are email addresses. Accounts that share at least one email are merged into a
 * single record.
 */
public final class AccountMerge {
    private AccountMerge() {
        // Utility class; do not instantiate.
    }

    /**
     * Merges accounts that share one or more email addresses.
     *
     * <p>The returned list is sorted by account owner name, then by the first email address when
     * multiple merged groups have the same owner name. Within each merged account, emails are
     * returned in lexicographic order.
     *
     * @param accounts a list of accounts where each entry contains a user name followed by emails
     * @return merged accounts, or an empty list when {@code accounts} is null or empty
     */
    public static List<List<String>> mergeAccounts(List<List<String>> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return List.of();
        }

        UnionFind dsu = new UnionFind(accounts.size());
        Map<String, Integer> emailToAccount = new HashMap<>();

        for (int i = 0; i < accounts.size(); i++) {
            List<String> account = accounts.get(i);
            for (int j = 1; j < account.size(); j++) {
                String email = account.get(j);
                Integer previous = emailToAccount.putIfAbsent(email, i);
                if (previous != null) {
                    dsu.union(i, previous);
                }
            }
        }

        Map<Integer, List<String>> rootToEmails = new LinkedHashMap<>();
        for (Map.Entry<String, Integer> entry : emailToAccount.entrySet()) {
            int root = dsu.find(entry.getValue());
            rootToEmails.computeIfAbsent(root, ignored -> new ArrayList<>()).add(entry.getKey());
        }
        for (int i = 0; i < accounts.size(); i++) {
            if (accounts.get(i).size() <= 1) {
                int root = dsu.find(i);
                rootToEmails.computeIfAbsent(root, ignored -> new ArrayList<>());
            }
        }

        List<List<String>> merged = new ArrayList<>();
        for (Map.Entry<Integer, List<String>> entry : rootToEmails.entrySet()) {
            int root = entry.getKey();
            List<String> emails = entry.getValue();
            Collections.sort(emails);

            List<String> mergedAccount = new ArrayList<>();
            mergedAccount.add(accounts.get(root).getFirst());
            mergedAccount.addAll(emails);
            merged.add(mergedAccount);
        }

        merged.sort((a, b) -> {
            int cmp = a.getFirst().compareTo(b.getFirst());
            if (cmp != 0) {
                return cmp;
            }
            if (a.size() == 1 || b.size() == 1) {
                return Integer.compare(a.size(), b.size());
            }
            return a.get(1).compareTo(b.get(1));
        });
        return merged;
    }

    /**
     * Lightweight union-find structure with path compression and union by rank.
     */
    private static final class UnionFind {
        private final int[] parent;
        private final int[] rank;

        private UnionFind(int size) {
            this.parent = new int[size];
            this.rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        private int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        private void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) {
                return;
            }

            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }
}

package com.thealgorithms.graph;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Implementation of the Bron–Kerbosch algorithm with pivoting for enumerating all maximal cliques
 * in an undirected graph.
 *
 * <p>The input graph is represented as an adjacency list where {@code adjacency.get(u)} returns the
 * set of vertices adjacent to {@code u}. The algorithm runs in time proportional to the number of
 * maximal cliques produced and is widely used for clique enumeration problems.</p>
 *
 * @author <a href="https://en.wikipedia.org/wiki/Bron%E2%80%93Kerbosch_algorithm">Wikipedia: Bron–Kerbosch algorithm</a>
 */
public final class BronKerbosch {

    private BronKerbosch() {
    }

    /**
     * Finds all maximal cliques of the provided graph.
     *
     * @param adjacency adjacency list where {@code adjacency.size()} equals the number of vertices
     * @return a list containing every maximal clique, each represented as a {@link Set} of vertices
     * @throws IllegalArgumentException if the adjacency list is {@code null}, contains {@code null}
     *         entries, or references invalid vertices
     */
    public static List<Set<Integer>> findMaximalCliques(List<Set<Integer>> adjacency) {
        if (adjacency == null) {
            throw new IllegalArgumentException("Adjacency list must not be null");
        }

        int n = adjacency.size();
        List<Set<Integer>> graph = new ArrayList<>(n);
        for (int u = 0; u < n; u++) {
            Set<Integer> neighbors = adjacency.get(u);
            if (neighbors == null) {
                throw new IllegalArgumentException("Adjacency list must not contain null sets");
            }
            Set<Integer> copy = new HashSet<>();
            for (int v : neighbors) {
                if (v < 0 || v >= n) {
                    throw new IllegalArgumentException("Neighbor index out of bounds: " + v);
                }
                if (v != u) {
                    copy.add(v);
                }
            }
            graph.add(copy);
        }

        Set<Integer> r = new HashSet<>();
        Set<Integer> p = new HashSet<>();
        Set<Integer> x = new HashSet<>();
        for (int v = 0; v < n; v++) {
            p.add(v);
        }

        List<Set<Integer>> cliques = new ArrayList<>();
        bronKerboschPivot(r, p, x, graph, cliques);
        return cliques;
    }

    private static void bronKerboschPivot(Set<Integer> r, Set<Integer> p, Set<Integer> x, List<Set<Integer>> graph, List<Set<Integer>> cliques) {
        if (p.isEmpty() && x.isEmpty()) {
            cliques.add(new HashSet<>(r));
            return;
        }

        int pivot = choosePivot(p, x, graph);
        Set<Integer> candidates = new HashSet<>(p);
        if (pivot != -1) {
            candidates.removeAll(graph.get(pivot));
        }

        for (Integer v : candidates) {
            r.add(v);
            Set<Integer> newP = intersection(p, graph.get(v));
            Set<Integer> newX = intersection(x, graph.get(v));
            bronKerboschPivot(r, newP, newX, graph, cliques);
            r.remove(v);
            p.remove(v);
            x.add(v);
        }
    }

    private static int choosePivot(Set<Integer> p, Set<Integer> x, List<Set<Integer>> graph) {
        int pivot = -1;
        int maxDegree = -1;
        Set<Integer> union = new HashSet<>(p);
        union.addAll(x);
        for (Integer v : union) {
            int degree = graph.get(v).size();
            if (degree > maxDegree) {
                maxDegree = degree;
                pivot = v;
            }
        }
        return pivot;
    }

    private static Set<Integer> intersection(Set<Integer> base, Set<Integer> neighbors) {
        Set<Integer> result = new HashSet<>();
        for (Integer v : base) {
            if (neighbors.contains(v)) {
                result.add(v);
            }
        }
        return result;
    }
}

package com.thealgorithms.graph;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * This class implements a solution for the Constrained Shortest Path Problem (CSPP).
 * also known as Shortest Path Problem with Resource Constraints (SPPRC).
 * The goal is to find the shortest path between two nodes while ensuring that
 * the resource constraint is not exceeded.
 *
 * @author  <a href="https://github.com/DenizAltunkapan">Deniz Altunkapan</a>
 */
public class ConstrainedShortestPath {

    /**
     * Represents a graph using an adjacency list.
     * This graph is designed for the Constrained Shortest Path Problem (CSPP).
     */
    public static class Graph {

        private List<List<Edge>> adjacencyList;

        public Graph(int numNodes) {
            adjacencyList = new ArrayList<>();
            for (int i = 0; i < numNodes; i++) {
                adjacencyList.add(new ArrayList<>());
            }
        }

        /**
         * Adds an edge to the graph.
         * @param from the starting node
         * @param to the ending node
         * @param cost the cost of the edge
         * @param resource the resource required to traverse the edge
         */
        public void addEdge(int from, int to, int cost, int resource) {
            adjacencyList.get(from).add(new Edge(from, to, cost, resource));
        }

        /**
         * Gets the edges that are adjacent to a given node.
         * @param node the node to get the edges for
         * @return the list of edges adjacent to the node
         */
        public List<Edge> getEdges(int node) {
            return adjacencyList.get(node);
        }

        /**
         * Gets the number of nodes in the graph.
         * @return the number of nodes
         */
        public int getNumNodes() {
            return adjacencyList.size();
        }

        public record Edge(int from, int to, int cost, int resource) {
        }
    }

    private Graph graph;
    private int maxResource;

    /**
     * Constructs a CSPSolver with the given graph and maximum resource constraint.
     *
     * @param graph       the graph representing the problem
     * @param maxResource the maximum allowable resource
     */
    public ConstrainedShortestPath(Graph graph, int maxResource) {
        this.graph = graph;
        this.maxResource = maxResource;
    }

    /**
     * Solves the CSP to find the shortest path from the start node to the target node
     * without exceeding the resource constraint.
     *
     * @param start  the starting node
     * @param target the target node
     * @return the minimum cost to reach the target node within the resource constraint,
     *         or -1 if no valid path exists
     */
    public int solve(int start, int target) {
        int numNodes = graph.getNumNodes();
        int[][] dp = new int[maxResource + 1][numNodes];

        // Initialize dp table with maximum values
        for (int i = 0; i <= maxResource; i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }
        dp[0][start] = 0;

        // Dynamic Programming: Iterate over resources and nodes
        for (int r = 0; r <= maxResource; r++) {
            for (int u = 0; u < numNodes; u++) {
                if (dp[r][u] == Integer.MAX_VALUE) {
                    continue;
                }
                for (Graph.Edge edge : graph.getEdges(u)) {
                    int v = edge.to();
                    int cost = edge.cost();
                    int resource = edge.resource();

                    if (r + resource <= maxResource) {
                        dp[r + resource][v] = Math.min(dp[r + resource][v], dp[r][u] + cost);
                    }
                }
            }
        }

        // Find the minimum cost to reach the target node
        int minCost = Integer.MAX_VALUE;
        for (int r = 0; r <= maxResource; r++) {
            minCost = Math.min(minCost, dp[r][target]);
        }

        return minCost == Integer.MAX_VALUE ? -1 : minCost;
    }
}

package com.thealgorithms.graph;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

/**
 * Dinic's algorithm for computing maximum flow in a directed graph.
 *
 * <p>Time complexity: O(E * V^2) in the worst case, but typically faster in practice
 * and near O(E * sqrt(V)) for unit networks.</p>
 *
 * <p>The graph is represented using a capacity matrix where capacity[u][v] is the
 * capacity of the directed edge u -> v. Capacities must be non-negative.
 * The algorithm builds level graphs using BFS and finds blocking flows using DFS
 * with current-edge optimization.</p>
 *
 * <p>This implementation mirrors the API and validation style of
 * {@link EdmondsKarp#maxFlow(int[][], int, int)} for consistency.</p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Dinic%27s_algorithm">Wikipedia: Dinic's algorithm</a>
 */
public final class Dinic {
    private Dinic() {
    }

    /**
     * Computes the maximum flow from source to sink using Dinic's algorithm.
     *
     * @param capacity square capacity matrix (n x n); entries must be >= 0
     * @param source source vertex index in [0, n)
     * @param sink sink vertex index in [0, n)
     * @return the maximum flow value
     * @throws IllegalArgumentException if the input matrix is null/non-square/has negatives or
     *     indices invalid
     */
    public static int maxFlow(int[][] capacity, int source, int sink) {
        if (capacity == null || capacity.length == 0) {
            throw new IllegalArgumentException("Capacity matrix must not be null or empty");
        }
        final int n = capacity.length;
        for (int i = 0; i < n; i++) {
            if (capacity[i] == null || capacity[i].length != n) {
                throw new IllegalArgumentException("Capacity matrix must be square");
            }
            for (int j = 0; j < n; j++) {
                if (capacity[i][j] < 0) {
                    throw new IllegalArgumentException("Capacities must be non-negative");
                }
            }
        }
        if (source < 0 || sink < 0 || source >= n || sink >= n) {
            throw new IllegalArgumentException("Source and sink must be valid vertex indices");
        }
        if (source == sink) {
            return 0;
        }

        // residual capacities
        int[][] residual = new int[n][n];
        for (int i = 0; i < n; i++) {
            residual[i] = Arrays.copyOf(capacity[i], n);
        }

        int[] level = new int[n];
        int flow = 0;
        while (bfsBuildLevelGraph(residual, source, sink, level)) {
            int[] next = new int[n]; // current-edge optimization
            int pushed;
            do {
                pushed = dfsBlocking(residual, level, next, source, sink, Integer.MAX_VALUE);
                flow += pushed;
            } while (pushed > 0);
        }
        return flow;
    }

    private static boolean bfsBuildLevelGraph(int[][] residual, int source, int sink, int[] level) {
        Arrays.fill(level, -1);
        level[source] = 0;
        Queue<Integer> q = new ArrayDeque<>();
        q.add(source);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v = 0; v < residual.length; v++) {
                if (residual[u][v] > 0 && level[v] == -1) {
                    level[v] = level[u] + 1;
                    if (v == sink) {
                        return true;
                    }
                    q.add(v);
                }
            }
        }
        return level[sink] != -1;
    }

    private static int dfsBlocking(int[][] residual, int[] level, int[] next, int u, int sink, int f) {
        if (u == sink) {
            return f;
        }
        final int n = residual.length;
        for (int v = next[u]; v < n; v++, next[u] = v) {
            if (residual[u][v] <= 0) {
                continue;
            }
            if (level[v] != level[u] + 1) {
                continue;
            }
            int pushed = dfsBlocking(residual, level, next, v, sink, Math.min(f, residual[u][v]));
            if (pushed > 0) {
                residual[u][v] -= pushed;
                residual[v][u] += pushed;
                return pushed;
            }
        }
        return 0;
    }
}

package com.thealgorithms.graph;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * An implementation of Edmonds's algorithm (also known as the Chu–Liu/Edmonds algorithm)
 * for finding a Minimum Spanning Arborescence (MSA).
 *
 * <p>An MSA is a directed graph equivalent of a Minimum Spanning Tree. It is a tree rooted
 * at a specific vertex 'r' that reaches all other vertices, such that the sum of the
 * weights of its edges is minimized.
 *
 * <p>The algorithm works recursively:
 * <ol>
 * <li>For each vertex other than the root, select the incoming edge with the minimum weight.</li>
 * <li>If the selected edges form a spanning arborescence, it is the MSA.</li>
 * <li>If cycles are formed, contract each cycle into a new "supernode".</li>
 * <li>Modify the weights of edges entering the new supernode.</li>
 * <li>Recursively call the algorithm on the contracted graph.</li>
 * <li>The final cost is the sum of the initial edge selections and the result of the recursive call.</li>
 * </ol>
 *
 * <p>Time Complexity: O(E * V) where E is the number of edges and V is the number of vertices.
 *
 * <p>References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/Edmonds%27_algorithm">Wikipedia: Edmonds's algorithm</a></li>
 * </ul>
 */
public final class Edmonds {

    private Edmonds() {
    }

    /**
     * Represents a directed weighted edge in the graph.
     */
    public static class Edge {
        final int from;
        final int to;
        final long weight;

        /**
         * Constructs a directed edge.
         *
         * @param from source vertex
         * @param to destination vertex
         * @param weight edge weight
         */
        public Edge(int from, int to, long weight) {
            this.from = from;
            this.to = to;
            this.weight = weight;
        }
    }

    /**
     * Computes the total weight of the Minimum Spanning Arborescence of a directed,
     * weighted graph from a given root.
     *
     * @param numVertices the number of vertices, labeled {@code 0..numVertices-1}
     * @param edges list of directed edges in the graph
     * @param root the root vertex
     * @return the total weight of the MSA. Returns -1 if not all vertices are reachable
     *         from the root or if a valid arborescence cannot be formed.
     * @throws IllegalArgumentException if {@code numVertices <= 0} or {@code root} is out of range.
     */
    public static long findMinimumSpanningArborescence(int numVertices, List<Edge> edges, int root) {
        if (root < 0 || root >= numVertices) {
            throw new IllegalArgumentException("Invalid number of vertices or root");
        }
        if (numVertices == 1) {
            return 0;
        }

        return findMSARecursive(numVertices, edges, root);
    }

    /**
     * Recursive helper method for finding MSA.
     */
    private static long findMSARecursive(int n, List<Edge> edges, int root) {
        long[] minWeightEdge = new long[n];
        int[] predecessor = new int[n];
        Arrays.fill(minWeightEdge, Long.MAX_VALUE);
        Arrays.fill(predecessor, -1);

        for (Edge edge : edges) {
            if (edge.to != root && edge.weight < minWeightEdge[edge.to]) {
                minWeightEdge[edge.to] = edge.weight;
                predecessor[edge.to] = edge.from;
            }
        }
        // Check if all non-root nodes are reachable
        for (int i = 0; i < n; i++) {
            if (i != root && minWeightEdge[i] == Long.MAX_VALUE) {
                return -1; // No spanning arborescence exists
            }
        }
        int[] cycleId = new int[n];
        Arrays.fill(cycleId, -1);
        boolean[] visited = new boolean[n];
        int cycleCount = 0;

        for (int i = 0; i < n; i++) {
            if (visited[i]) {
                continue;
            }

            List<Integer> path = new ArrayList<>();
            int curr = i;

            // Follow predecessor chain
            while (curr != -1 && !visited[curr]) {
                visited[curr] = true;
                path.add(curr);
                curr = predecessor[curr];
            }

            // If we hit a visited node, check if it forms a cycle
            if (curr != -1) {
                boolean inCycle = false;
                for (int node : path) {
                    if (node == curr) {
                        inCycle = true;
                    }
                    if (inCycle) {
                        cycleId[node] = cycleCount;
                    }
                }
                if (inCycle) {
                    cycleCount++;
                }
            }
        }
        if (cycleCount == 0) {
            long totalWeight = 0;
            for (int i = 0; i < n; i++) {
                if (i != root) {
                    totalWeight += minWeightEdge[i];
                }
            }
            return totalWeight;
        }
        long cycleWeightSum = 0;
        for (int i = 0; i < n; i++) {
            if (cycleId[i] >= 0) {
                cycleWeightSum += minWeightEdge[i];
            }
        }

        // Map old nodes to new nodes (cycles become supernodes)
        int[] newNodeMap = new int[n];
        int[] cycleToNewNode = new int[cycleCount];
        int newN = 0;

        // Assign new node IDs to cycles first
        for (int i = 0; i < cycleCount; i++) {
            cycleToNewNode[i] = newN++;
        }

        // Assign new node IDs to non-cycle nodes
        for (int i = 0; i < n; i++) {
            if (cycleId[i] == -1) {
                newNodeMap[i] = newN++;
            } else {
                newNodeMap[i] = cycleToNewNode[cycleId[i]];
            }
        }

        int newRoot = newNodeMap[root];

        // Build contracted graph
        List<Edge> newEdges = new ArrayList<>();
        for (Edge edge : edges) {
            int uCycleId = cycleId[edge.from];
            int vCycleId = cycleId[edge.to];

            // Skip edges internal to a cycle
            if (uCycleId >= 0 && uCycleId == vCycleId) {
                continue;
            }

            int newU = newNodeMap[edge.from];
            int newV = newNodeMap[edge.to];

            long newWeight = edge.weight;
            // Adjust weight for edges entering a cycle
            if (vCycleId >= 0) {
                newWeight -= minWeightEdge[edge.to];
            }

            if (newU != newV) {
                newEdges.add(new Edge(newU, newV, newWeight));
            }
        }
        return cycleWeightSum + findMSARecursive(newN, newEdges, newRoot);
    }
}

package com.thealgorithms.graph;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

/**
 * Implementation of the Edmonds–Karp algorithm for computing the maximum flow of a directed graph.
 * <p>
 * The algorithm runs in O(V * E^2) time and is a specific implementation of the Ford–Fulkerson
 * method where the augmenting paths are found using breadth-first search (BFS) to ensure the
 * shortest augmenting paths (in terms of the number of edges) are used.
 * </p>
 *
 * <p>The graph is represented with a capacity matrix where {@code capacity[u][v]} denotes the
 * capacity of the edge from {@code u} to {@code v}. Negative capacities are not allowed.</p>
 *
 * @author <a href="https://en.wikipedia.org/wiki/Edmonds%E2%80%93Karp_algorithm">Wikipedia: EdmondsKarp algorithm</a>
 */
public final class EdmondsKarp {

    private EdmondsKarp() {
    }

    /**
     * Computes the maximum flow from {@code source} to {@code sink} in the provided capacity matrix.
     *
     * @param capacity the capacity matrix representing the directed graph; must be square and non-null
     * @param source the source vertex index
     * @param sink the sink vertex index
     * @return the value of the maximum flow between {@code source} and {@code sink}
     * @throws IllegalArgumentException if the matrix is {@code null}, not square, contains negative
     *         capacities, or if {@code source} / {@code sink} indices are invalid
     */
    public static int maxFlow(int[][] capacity, int source, int sink) {
        if (capacity == null || capacity.length == 0) {
            throw new IllegalArgumentException("Capacity matrix must not be null or empty");
        }

        final int n = capacity.length;
        for (int row = 0; row < n; row++) {
            if (capacity[row] == null || capacity[row].length != n) {
                throw new IllegalArgumentException("Capacity matrix must be square");
            }
            for (int col = 0; col < n; col++) {
                if (capacity[row][col] < 0) {
                    throw new IllegalArgumentException("Capacities must be non-negative");
                }
            }
        }

        if (source < 0 || source >= n || sink < 0 || sink >= n) {
            throw new IllegalArgumentException("Source and sink must be valid vertex indices");
        }
        if (source == sink) {
            return 0;
        }

        final int[][] residual = new int[n][n];
        for (int i = 0; i < n; i++) {
            residual[i] = Arrays.copyOf(capacity[i], n);
        }

        final int[] parent = new int[n];
        int maxFlow = 0;

        while (bfs(residual, source, sink, parent)) {
            int pathFlow = Integer.MAX_VALUE;
            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                pathFlow = Math.min(pathFlow, residual[u][v]);
            }

            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                residual[u][v] -= pathFlow;
                residual[v][u] += pathFlow;
            }

            maxFlow += pathFlow;
        }

        return maxFlow;
    }

    private static boolean bfs(int[][] residual, int source, int sink, int[] parent) {
        Arrays.fill(parent, -1);
        parent[source] = source;

        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(source);

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v = 0; v < residual.length; v++) {
                if (residual[u][v] > 0 && parent[v] == -1) {
                    parent[v] = u;
                    if (v == sink) {
                        return true;
                    }
                    queue.add(v);
                }
            }
        }
        return false;
    }
}

package com.thealgorithms.graph;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

/**
 * Gomory–Hu tree construction for undirected graphs via n−1 max-flow computations.
 *
 * <p>API: {@code buildTree(int[][])} returns {@code {parent, weight}} arrays for the tree.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Gomory%E2%80%93Hu_tree">Wikipedia: Gomory–Hu tree</a>
 */

public final class GomoryHuTree {
    private GomoryHuTree() {
    }

    public static int[][] buildTree(int[][] cap) {
        validateCapacityMatrix(cap);
        final int n = cap.length;
        if (n == 1) {
            return new int[][] {new int[] {-1}, new int[] {0}};
        }

        int[] parent = new int[n];
        int[] weight = new int[n];
        Arrays.fill(parent, 0);
        parent[0] = -1;
        weight[0] = 0;

        for (int s = 1; s < n; s++) {
            int t = parent[s];
            MaxFlowResult res = edmondsKarpWithMinCut(cap, s, t);
            int f = res.flow;
            weight[s] = f;

            for (int v = 0; v < n; v++) {
                if (v != s && parent[v] == t && res.reachable[v]) {
                    parent[v] = s;
                }
            }

            if (t != 0 && res.reachable[parent[t]]) {
                parent[s] = parent[t];
                parent[t] = s;
                weight[s] = weight[t];
                weight[t] = f;
            }
        }
        return new int[][] {parent, weight};
    }

    private static void validateCapacityMatrix(int[][] cap) {
        if (cap == null || cap.length == 0) {
            throw new IllegalArgumentException("Capacity matrix must not be null or empty");
        }
        final int n = cap.length;
        for (int i = 0; i < n; i++) {
            if (cap[i] == null || cap[i].length != n) {
                throw new IllegalArgumentException("Capacity matrix must be square");
            }
            for (int j = 0; j < n; j++) {
                if (cap[i][j] < 0) {
                    throw new IllegalArgumentException("Capacities must be non-negative");
                }
            }
        }
    }

    private static final class MaxFlowResult {
        final int flow;
        final boolean[] reachable;
        MaxFlowResult(int flow, boolean[] reachable) {
            this.flow = flow;
            this.reachable = reachable;
        }
    }

    private static MaxFlowResult edmondsKarpWithMinCut(int[][] capacity, int source, int sink) {
        final int n = capacity.length;
        int[][] residual = new int[n][n];
        for (int i = 0; i < n; i++) {
            residual[i] = Arrays.copyOf(capacity[i], n);
        }

        int[] parent = new int[n];
        int maxFlow = 0;

        while (bfs(residual, source, sink, parent)) {
            int pathFlow = Integer.MAX_VALUE;
            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                pathFlow = Math.min(pathFlow, residual[u][v]);
            }
            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                residual[u][v] -= pathFlow;
                residual[v][u] += pathFlow;
            }
            maxFlow += pathFlow;
        }

        boolean[] reachable = new boolean[n];
        markReachable(residual, source, reachable);
        return new MaxFlowResult(maxFlow, reachable);
    }

    private static boolean bfs(int[][] residual, int source, int sink, int[] parent) {
        Arrays.fill(parent, -1);
        parent[source] = source;
        Queue<Integer> q = new ArrayDeque<>();
        q.add(source);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v = 0; v < residual.length; v++) {
                if (residual[u][v] > 0 && parent[v] == -1) {
                    parent[v] = u;
                    if (v == sink) {
                        return true;
                    }
                    q.add(v);
                }
            }
        }
        return false;
    }

    private static void markReachable(int[][] residual, int source, boolean[] vis) {
        Arrays.fill(vis, false);
        Queue<Integer> q = new ArrayDeque<>();
        vis[source] = true;
        q.add(source);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v = 0; v < residual.length; v++) {
                if (!vis[v] && residual[u][v] > 0) {
                    vis[v] = true;
                    q.add(v);
                }
            }
        }
    }
}

package com.thealgorithms.graph;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.Stack;

/**
 * Implementation of Hierholzer's algorithm to find an Eulerian Circuit in an undirected graph.
 * <p>
 * An Eulerian circuit is a trail in a graph that visits every edge exactly once,
 * starting and ending at the same vertex. This algorithm finds such a circuit if one exists.
 * </p>
 * <p>
 * This implementation is designed for an <strong>undirected graph</strong>. For a valid Eulerian
 * circuit to exist, the graph must satisfy two conditions:
 * <ol>
 * <li>All vertices with a non-zero degree must be part of a single connected component.</li>
 * <li>Every vertex must have an even degree (an even number of edges connected to it).</li>
 * </ol>
 * </p>
 * <p>
 * The algorithm runs in O(E + V) time, where E is the number of edges and V is the number of vertices.
 * The graph is represented by a Map where keys are vertices and values are a LinkedList of adjacent vertices.
 * </p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Eulerian_path#Hierholzer's_algorithm">Wikipedia: Hierholzer's algorithm</a>
 */
public final class HierholzerAlgorithm {

    private final Map<Integer, LinkedList<Integer>> graph;

    public HierholzerAlgorithm(Map<Integer, LinkedList<Integer>> graph) {
        this.graph = (graph == null) ? new HashMap<>() : graph;
    }

    public boolean hasEulerianCircuit() {
        if (graph.isEmpty()) {
            return true;
        }

        for (List<Integer> neighbors : graph.values()) {
            if (neighbors.size() % 2 != 0) {
                return false;
            }
        }

        return isCoherentlyConnected();
    }

    public List<Integer> findEulerianCircuit() {
        if (!hasEulerianCircuit()) {
            return Collections.emptyList();
        }

        Map<Integer, LinkedList<Integer>> tempGraph = new HashMap<>();
        for (Map.Entry<Integer, LinkedList<Integer>> entry : graph.entrySet()) {
            tempGraph.put(entry.getKey(), new LinkedList<>(entry.getValue()));
        }

        Stack<Integer> currentPath = new Stack<>();
        LinkedList<Integer> circuit = new LinkedList<>();

        int startVertex = -1;
        for (Map.Entry<Integer, LinkedList<Integer>> entry : tempGraph.entrySet()) {
            if (!entry.getValue().isEmpty()) {
                startVertex = entry.getKey();
                break;
            }
        }

        if (startVertex == -1) {
            if (graph.isEmpty()) {
                return Collections.emptyList();
            }
            return Collections.singletonList(graph.keySet().iterator().next());
        }

        currentPath.push(startVertex);

        while (!currentPath.isEmpty()) {
            int currentVertex = currentPath.peek();

            if (tempGraph.containsKey(currentVertex) && !tempGraph.get(currentVertex).isEmpty()) {
                int nextVertex = tempGraph.get(currentVertex).pollFirst();
                tempGraph.get(nextVertex).remove(Integer.valueOf(currentVertex));
                currentPath.push(nextVertex);
            } else {
                circuit.addFirst(currentVertex);
                currentPath.pop();
            }
        }

        return circuit;
    }

    private boolean isCoherentlyConnected() {
        if (graph.isEmpty()) {
            return true;
        }

        Set<Integer> visited = new HashSet<>();
        int startNode = -1;

        for (Map.Entry<Integer, LinkedList<Integer>> entry : graph.entrySet()) {
            if (!entry.getValue().isEmpty()) {
                startNode = entry.getKey();
                break;
            }
        }

        if (startNode == -1) {
            return true;
        }

        dfs(startNode, visited);

        for (Map.Entry<Integer, LinkedList<Integer>> entry : graph.entrySet()) {
            if (!entry.getValue().isEmpty() && !visited.contains(entry.getKey())) {
                return false;
            }
        }
        return true;
    }

    private void dfs(int u, Set<Integer> visited) {
        visited.add(u);
        if (graph.containsKey(u)) {
            for (int v : graph.get(u)) {
                if (!visited.contains(v)) {
                    dfs(v, visited);
                }
            }
        }
    }
}

package com.thealgorithms.graph;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;

/**
 * Implementation of Hierholzer's Algorithm for finding an Eulerian Path or Circuit
 * in a directed graph.
 *
 * <p>
 * An <b>Eulerian Circuit</b> is a path that starts and ends at the same vertex
 * and visits every edge exactly once.
 * </p>
 *
 * <p>
 * An <b>Eulerian Path</b> visits every edge exactly once but may start and end
 * at different vertices.
 * </p>
 *
 * <p>
 * <b>Algorithm Summary:</b><br>
 * 1. Compute indegree and outdegree for all vertices.<br>
 * 2. Check if the graph satisfies Eulerian path or circuit conditions.<br>
 * 3. Verify that all vertices with non-zero degree are weakly connected (undirected connectivity).<br>
 * 4. Use Hierholzer’s algorithm to build the path by exploring unused edges iteratively.
 * </p>
 *
 * <p>
 * <b>Time Complexity:</b> O(E + V).<br>
 * <b>Space Complexity:</b> O(V + E).
 * </p>
 *
 * @author <a href="https://en.wikipedia.org/wiki/Eulerian_path#Hierholzer's_algorithm">Wikipedia: Hierholzer algorithm</a>
 */
public class HierholzerEulerianPath {

    /**
     * Simple directed graph represented by adjacency lists.
     */
    public static class Graph {
        private final List<List<Integer>> adjacencyList;

        /**
         * Constructs a graph with a given number of vertices.
         *
         * @param numNodes number of vertices
         */
        public Graph(int numNodes) {
            adjacencyList = new ArrayList<>();
            for (int i = 0; i < numNodes; i++) {
                adjacencyList.add(new ArrayList<>());
            }
        }

        /**
         * Adds a directed edge from vertex {@code from} to vertex {@code to}.
         *
         * @param from source vertex
         * @param to   destination vertex
         */
        public void addEdge(int from, int to) {
            adjacencyList.get(from).add(to);
        }

        /**
         * Returns a list of outgoing edges from the given vertex.
         *
         * @param node vertex index
         * @return list of destination vertices
         */
        public List<Integer> getEdges(int node) {
            return adjacencyList.get(node);
        }

        /**
         * Returns the number of vertices in the graph.
         *
         * @return number of vertices
         */
        public int getNumNodes() {
            return adjacencyList.size();
        }
    }

    private final Graph graph;

    /**
     * Creates a Hierholzer solver for the given graph.
     *
     * @param graph directed graph
     */
    public HierholzerEulerianPath(Graph graph) {
        this.graph = graph;
    }

    /**
     * Finds an Eulerian Path or Circuit using Hierholzer’s Algorithm.
     *
     * @return list of vertices representing the Eulerian Path/Circuit,
     *         or an empty list if none exists
     */
    public List<Integer> findEulerianPath() {
        int n = graph.getNumNodes();

        // empty graph -> no path
        if (n == 0) {
            return new ArrayList<>();
        }

        int[] inDegree = new int[n];
        int[] outDegree = new int[n];
        int edgeCount = computeDegrees(inDegree, outDegree);

        // no edges -> single vertex response requested by tests: [0]
        if (edgeCount == 0) {
            return Collections.singletonList(0);
        }

        int startNode = determineStartNode(inDegree, outDegree);
        if (startNode == -1) {
            return new ArrayList<>();
        }

        if (!allNonZeroDegreeVerticesWeaklyConnected(startNode, n, outDegree, inDegree)) {
            return new ArrayList<>();
        }

        List<Integer> path = buildHierholzerPath(startNode, n);
        if (path.size() != edgeCount + 1) {
            return new ArrayList<>();
        }

        return rotateEulerianCircuitIfNeeded(path, outDegree, inDegree);
    }

    private int computeDegrees(int[] inDegree, int[] outDegree) {
        int edgeCount = 0;
        for (int u = 0; u < graph.getNumNodes(); u++) {
            for (int v : graph.getEdges(u)) {
                outDegree[u]++;
                inDegree[v]++;
                edgeCount++;
            }
        }
        return edgeCount;
    }

    private int determineStartNode(int[] inDegree, int[] outDegree) {
        int n = graph.getNumNodes();
        int startNode = -1;
        int startCount = 0;
        int endCount = 0;

        for (int i = 0; i < n; i++) {
            int diff = outDegree[i] - inDegree[i];
            if (diff == 1) {
                startNode = i;
                startCount++;
            } else if (diff == -1) {
                endCount++;
            } else if (Math.abs(diff) > 1) {
                return -1;
            }
        }

        if (!((startCount == 1 && endCount == 1) || (startCount == 0 && endCount == 0))) {
            return -1;
        }

        if (startNode == -1) {
            for (int i = 0; i < n; i++) {
                if (outDegree[i] > 0) {
                    startNode = i;
                    break;
                }
            }
        }
        return startNode;
    }

    private List<Integer> buildHierholzerPath(int startNode, int n) {
        List<Deque<Integer>> tempAdj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            tempAdj.add(new ArrayDeque<>(graph.getEdges(i)));
        }

        Deque<Integer> stack = new ArrayDeque<>();
        List<Integer> path = new ArrayList<>();
        stack.push(startNode);

        while (!stack.isEmpty()) {
            int u = stack.peek();
            if (!tempAdj.get(u).isEmpty()) {
                stack.push(tempAdj.get(u).pollFirst());
            } else {
                path.add(stack.pop());
            }
        }

        Collections.reverse(path);
        return path;
    }

    private List<Integer> rotateEulerianCircuitIfNeeded(List<Integer> path, int[] outDegree, int[] inDegree) {
        int startCount = 0;
        int endCount = 0;
        for (int i = 0; i < outDegree.length; i++) {
            int diff = outDegree[i] - inDegree[i];
            if (diff == 1) {
                startCount++;
            } else if (diff == -1) {
                endCount++;
            }
        }

        if (startCount == 0 && endCount == 0 && !path.isEmpty()) {
            int preferredStart = -1;
            for (int i = 0; i < outDegree.length; i++) {
                if (outDegree[i] > 0) {
                    preferredStart = i;
                    break;
                }
            }

            if (preferredStart != -1 && path.get(0) != preferredStart) {
                int idx = 0;
                for (Integer node : path) { // replaced indexed loop
                    if (node == preferredStart) {
                        break;
                    }
                    idx++;
                }

                if (idx > 0) {
                    List<Integer> rotated = new ArrayList<>();
                    int currentIndex = 0;
                    for (Integer node : path) { // replaced indexed loop
                        if (currentIndex >= idx) {
                            rotated.add(node);
                        }
                        currentIndex++;
                    }
                    currentIndex = 0;
                    for (Integer node : path) { // replaced indexed loop
                        if (currentIndex < idx) {
                            rotated.add(node);
                        }
                        currentIndex++;
                    }
                    path = rotated;
                }
            }
        }
        return path;
    }

    /**
     * Checks weak connectivity (undirected) among vertices that have non-zero degree.
     *
     * @param startNode node to start DFS from (must be a vertex with non-zero degree)
     * @param n number of vertices
     * @param outDegree out-degree array
     * @param inDegree in-degree array
     * @return true if all vertices having non-zero degree belong to a single weak component
     */
    private boolean allNonZeroDegreeVerticesWeaklyConnected(int startNode, int n, int[] outDegree, int[] inDegree) {
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(startNode);
        visited[startNode] = true;

        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int v : graph.getEdges(u)) {
                if (!visited[v]) {
                    visited[v] = true;
                    stack.push(v);
                }
            }
            for (int x = 0; x < n; x++) {
                if (!visited[x]) {
                    for (int y : graph.getEdges(x)) {
                        if (y == u) {
                            visited[x] = true;
                            stack.push(x);
                            break;
                        }
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (outDegree[i] + inDegree[i] > 0 && !visited[i]) {
                return false;
            }
        }
        return true;
    }
}

package com.thealgorithms.graph;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.List;
import java.util.Queue;

/**
 * Hopcroft–Karp algorithm for maximum bipartite matching.
 *
 * Left part: vertices [0,nLeft-1], Right part: [0,nRight-1].
 * Adjacency list: for each left vertex u, list right vertices v it connects to.
 *
 * Time complexity: O(E * sqrt(V)).
 *
 * @see <a href="https://en.wikipedia.org/wiki/Hopcroft%E2%80%93Karp_algorithm">
 *      Wikipedia: Hopcroft–Karp algorithm</a>
 * @author ptzecher
 */
public class HopcroftKarp {

    private final int nLeft;
    private final List<List<Integer>> adj;

    private final int[] pairU;
    private final int[] pairV;
    private final int[] dist;

    public HopcroftKarp(int nLeft, int nRight, List<List<Integer>> adj) {
        this.nLeft = nLeft;
        this.adj = adj;

        this.pairU = new int[nLeft];
        this.pairV = new int[nRight];
        this.dist = new int[nLeft];

        Arrays.fill(pairU, -1);
        Arrays.fill(pairV, -1);
    }

    /** Returns the size of the maximum matching. */
    public int maxMatching() {
        int matching = 0;
        while (bfs()) {
            for (int u = 0; u < nLeft; u++) {
                if (pairU[u] == -1 && dfs(u)) {
                    matching++;
                }
            }
        }
        return matching;
    }

    // BFS to build layers
    private boolean bfs() {
        Queue<Integer> queue = new ArrayDeque<>();
        Arrays.fill(dist, -1);

        for (int u = 0; u < nLeft; u++) {
            if (pairU[u] == -1) {
                dist[u] = 0;
                queue.add(u);
            }
        }

        boolean foundAugPath = false;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj.get(u)) {
                int matchedLeft = pairV[v];
                if (matchedLeft == -1) {
                    foundAugPath = true;
                } else if (dist[matchedLeft] == -1) {
                    dist[matchedLeft] = dist[u] + 1;
                    queue.add(matchedLeft);
                }
            }
        }
        return foundAugPath;
    }

    // DFS to find augmenting paths within the BFS layering
    private boolean dfs(int u) {
        for (int v : adj.get(u)) {
            int matchedLeft = pairV[v];
            if (matchedLeft == -1 || (dist[matchedLeft] == dist[u] + 1 && dfs(matchedLeft))) {
                pairU[u] = v;
                pairV[v] = u;
                return true;
            }
        }
        dist[u] = -1;
        return false;
    }

    public int[] getLeftMatches() {
        return pairU.clone();
    }

    public int[] getRightMatches() {
        return pairV.clone();
    }
}

package com.thealgorithms.graph;

import java.util.Arrays;

/**
 * Hungarian algorithm (a.k.a. Kuhn–Munkres) for the Assignment Problem.
 *
 * <p>Given an n x m cost matrix (n tasks, m workers), finds a minimum-cost
 * one-to-one assignment. If the matrix is rectangular, the algorithm pads to a
 * square internally. Costs must be finite non-negative integers.
 *
 * <p>Time complexity: O(n^3) with n = max(rows, cols).
 *
 * <p>API returns the assignment as an array where {@code assignment[i]} is the
 * column chosen for row i (or -1 if unassigned when rows != cols), and a total
 * minimal cost.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Hungarian_algorithm">Wikipedia: Hungarian algorithm</a>
 */
public final class HungarianAlgorithm {

    private HungarianAlgorithm() {
    }

    /** Result holder for the Hungarian algorithm. */
    public static final class Result {
        public final int[] assignment; // assignment[row] = col or -1
        public final int minCost;

        public Result(int[] assignment, int minCost) {
            this.assignment = assignment;
            this.minCost = minCost;
        }
    }

    /**
     * Solves the assignment problem for a non-negative cost matrix.
     *
     * @param cost an r x c matrix of non-negative costs
     * @return Result with row-to-column assignment and minimal total cost
     * @throws IllegalArgumentException for null/empty or negative costs
     */
    public static Result solve(int[][] cost) {
        validate(cost);
        int rows = cost.length;
        int cols = cost[0].length;
        int n = Math.max(rows, cols);

        // Build square matrix with padding 0 for missing cells
        int[][] a = new int[n][n];
        for (int i = 0; i < n; i++) {
            if (i < rows) {
                for (int j = 0; j < n; j++) {
                    a[i][j] = (j < cols) ? cost[i][j] : 0;
                }
            } else {
                Arrays.fill(a[i], 0);
            }
        }

        // Potentials and matching arrays
        int[] u = new int[n + 1];
        int[] v = new int[n + 1];
        int[] p = new int[n + 1];
        int[] way = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            p[0] = i;
            int j0 = 0;
            int[] minv = new int[n + 1];
            boolean[] used = new boolean[n + 1];
            Arrays.fill(minv, Integer.MAX_VALUE);
            Arrays.fill(used, false);
            do {
                used[j0] = true;
                int i0 = p[j0];
                int delta = Integer.MAX_VALUE;
                int j1 = 0;
                for (int j = 1; j <= n; j++) {
                    if (!used[j]) {
                        int cur = a[i0 - 1][j - 1] - u[i0] - v[j];
                        if (cur < minv[j]) {
                            minv[j] = cur;
                            way[j] = j0;
                        }
                        if (minv[j] < delta) {
                            delta = minv[j];
                            j1 = j;
                        }
                    }
                }
                for (int j = 0; j <= n; j++) {
                    if (used[j]) {
                        u[p[j]] += delta;
                        v[j] -= delta;
                    } else {
                        minv[j] -= delta;
                    }
                }
                j0 = j1;
            } while (p[j0] != 0);
            do {
                int j1 = way[j0];
                p[j0] = p[j1];
                j0 = j1;
            } while (j0 != 0);
        }

        int[] matchColForRow = new int[n];
        Arrays.fill(matchColForRow, -1);
        for (int j = 1; j <= n; j++) {
            if (p[j] != 0) {
                matchColForRow[p[j] - 1] = j - 1;
            }
        }

        // Build assignment for original rows only, ignore padded rows
        int[] assignment = new int[rows];
        Arrays.fill(assignment, -1);
        int total = 0;
        for (int i = 0; i < rows; i++) {
            int j = matchColForRow[i];
            if (j >= 0 && j < cols) {
                assignment[i] = j;
                total += cost[i][j];
            }
        }
        return new Result(assignment, total);
    }

    private static void validate(int[][] cost) {
        if (cost == null || cost.length == 0) {
            throw new IllegalArgumentException("Cost matrix must not be null or empty");
        }
        int c = cost[0].length;
        if (c == 0) {
            throw new IllegalArgumentException("Cost matrix must have at least 1 column");
        }
        for (int i = 0; i < cost.length; i++) {
            if (cost[i] == null || cost[i].length != c) {
                throw new IllegalArgumentException("Cost matrix must be rectangular with equal row lengths");
            }
            for (int j = 0; j < c; j++) {
                if (cost[i][j] < 0) {
                    throw new IllegalArgumentException("Costs must be non-negative");
                }
            }
        }
    }
}

package com.thealgorithms.graph;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * DFS that visits a successor only when all its predecessors are already visited,
 * emitting VISIT and SKIP events.
 * <p>
 *     This class includes a DFS variant that visits a successor only when all of its
 *     predecessors have already been visited
 * </p>
 * <p>Related reading:
 * <ul>
 *   <li><a href="https://en.wikipedia.org/wiki/Topological_sorting">Topological sorting</a></li>
 *   <li><a href="https://en.wikipedia.org/wiki/Depth-first_search">Depth-first search</a></li>
 * </ul>
 * </p>
 */

public final class PredecessorConstrainedDfs {

    private PredecessorConstrainedDfs() {
        // utility class
    }

    /** An event emitted by the traversal: either a VISIT with an order, or a SKIP with a note. */
    public record TraversalEvent<T>(T node,
        Integer order, // non-null for visit, null for skip
        String note // non-null for skip, null for visit
    ) {
        public TraversalEvent {
            Objects.requireNonNull(node);
            // order and note can be null based on event type
        }

        /** A visit event with an increasing order (0,1,2,...) */
        public static <T> TraversalEvent<T> visit(T node, int order) {
            return new TraversalEvent<>(node, order, null);
        }

        /** A skip event with an explanatory note (e.g., not all parents visited yet). */
        public static <T> TraversalEvent<T> skip(T node, String note) {
            return new TraversalEvent<>(node, null, Objects.requireNonNull(note));
        }

        public boolean isVisit() {
            return order != null;
        }

        public boolean isSkip() {
            return order == null;
        }

        @Override
        public String toString() {
            return isVisit() ? "VISIT(" + node + ", order=" + order + ")" : "SKIP(" + node + ", " + note + ")";
        }
    }

    /**
     * DFS (recursive) that records the order of first visit starting at {@code start},
     * but only recurses to a child when <b>all</b> its predecessors have been visited.
     * If a child is encountered early (some parent unvisited), a SKIP event is recorded.
     *
     * <p>Equivalent idea to the Python pseudo in the user's description (with successors and predecessors),
     * but implemented in Java and returning a sequence of {@link TraversalEvent}s.</p>
     *
     * @param successors adjacency list: for each node, its outgoing neighbors
     * @param start start node
     * @return immutable list of traversal events (VISITs with monotonically increasing order and SKIPs with messages)
     * @throws IllegalArgumentException if {@code successors} is null
     */
    public static <T> List<TraversalEvent<T>> dfsRecursiveOrder(Map<T, List<T>> successors, T start) {
        if (successors == null) {
            throw new IllegalArgumentException("successors must not be null");
        }
        // derive predecessors once
        Map<T, List<T>> predecessors = derivePredecessors(successors);
        return dfsRecursiveOrder(successors, predecessors, start);
    }

    /**
     * Same as {@link #dfsRecursiveOrder(Map, Object)} but with an explicit predecessors map.
     */
    public static <T> List<TraversalEvent<T>> dfsRecursiveOrder(Map<T, List<T>> successors, Map<T, List<T>> predecessors, T start) {

        if (successors == null || predecessors == null) {
            throw new IllegalArgumentException("successors and predecessors must not be null");
        }
        if (start == null) {
            return List.of();
        }
        if (!successors.containsKey(start) && !appearsAnywhere(successors, start)) {
            return List.of(); // start not present in graph
        }

        List<TraversalEvent<T>> events = new ArrayList<>();
        Set<T> visited = new HashSet<>();
        int[] order = {0};
        dfs(start, successors, predecessors, visited, order, events);
        return Collections.unmodifiableList(events);
    }

    private static <T> void dfs(T currentNode, Map<T, List<T>> successors, Map<T, List<T>> predecessors, Set<T> visited, int[] order, List<TraversalEvent<T>> result) {

        if (!visited.add(currentNode)) {
            return; // already visited
        }
        result.add(TraversalEvent.visit(currentNode, order[0]++)); // record visit and increment

        for (T childNode : successors.getOrDefault(currentNode, List.of())) {
            if (visited.contains(childNode)) {
                continue;
            }
            if (allParentsVisited(childNode, visited, predecessors)) {
                dfs(childNode, successors, predecessors, visited, order, result);
            } else {
                result.add(TraversalEvent.skip(childNode, "⛔ Skipping " + childNode + ": not all parents are visited yet."));
                // do not mark visited; it may be visited later from another parent
            }
        }
    }

    private static <T> boolean allParentsVisited(T node, Set<T> visited, Map<T, List<T>> predecessors) {
        for (T parent : predecessors.getOrDefault(node, List.of())) {
            if (!visited.contains(parent)) {
                return false;
            }
        }
        return true;
    }

    private static <T> boolean appearsAnywhere(Map<T, List<T>> successors, T node) {
        if (successors.containsKey(node)) {
            return true;
        }
        for (List<T> neighbours : successors.values()) {
            if (neighbours != null && neighbours.contains(node)) {
                return true;
            }
        }
        return false;
    }

    private static <T> Map<T, List<T>> derivePredecessors(Map<T, List<T>> successors) {
        Map<T, List<T>> predecessors = new HashMap<>();
        // ensure keys exist for all nodes appearing anywhere
        for (Map.Entry<T, List<T>> entry : successors.entrySet()) {
            predecessors.computeIfAbsent(entry.getKey(), key -> new ArrayList<>());
            for (T childNode : entry.getValue()) {
                predecessors.computeIfAbsent(childNode, key -> new ArrayList<>()).add(entry.getKey());
            }
        }
        return predecessors;
    }
}

package com.thealgorithms.graph;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

/**
 * Push–Relabel (Relabel-to-Front variant simplified to array scanning) for maximum flow.
 *
 * <p>Input graph is a capacity matrix where {@code capacity[u][v]} is the capacity of the edge
 * {@code u -> v}. Capacities must be non-negative. Vertices are indexed in {@code [0, n)}.
 *
 * <p>Time complexity: O(V^3) in the worst case for the array-based variant; typically fast in
 * practice. This implementation uses a residual network over an adjacency-matrix representation.
 *
 * <p>The API mirrors {@link EdmondsKarp#maxFlow(int[][], int, int)} and {@link Dinic#maxFlow(int[][], int, int)}.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Push%E2%80%93relabel_maximum_flow_algorithm">Wikipedia: Push–Relabel maximum flow algorithm</a>
 */
public final class PushRelabel {

    private PushRelabel() {
    }

    /**
     * Computes the maximum flow from {@code source} to {@code sink} using Push–Relabel.
     *
     * @param capacity square capacity matrix (n x n); entries must be >= 0
     * @param source source vertex index in [0, n)
     * @param sink sink vertex index in [0, n)
     * @return the maximum flow value
     * @throws IllegalArgumentException if inputs are invalid
     */
    public static int maxFlow(int[][] capacity, int source, int sink) {
        validate(capacity, source, sink);
        final int n = capacity.length;
        if (source == sink) {
            return 0;
        }

        int[][] residual = new int[n][n];
        for (int i = 0; i < n; i++) {
            residual[i] = Arrays.copyOf(capacity[i], n);
        }

        int[] height = new int[n];
        int[] excess = new int[n];
        int[] nextNeighbor = new int[n];

        // Preflow initialization
        height[source] = n;
        for (int v = 0; v < n; v++) {
            int cap = residual[source][v];
            if (cap > 0) {
                residual[source][v] -= cap;
                residual[v][source] += cap;
                excess[v] += cap;
                excess[source] -= cap;
            }
        }

        // Active queue contains vertices (except source/sink) with positive excess
        Queue<Integer> active = new ArrayDeque<>();
        for (int v = 0; v < n; v++) {
            if (v != source && v != sink && excess[v] > 0) {
                active.add(v);
            }
        }

        State state = new State(residual, height, excess, nextNeighbor, source, sink, active);

        while (!active.isEmpty()) {
            int u = active.poll();
            discharge(u, state);
            if (excess[u] > 0) {
                // still active after discharge; push to back
                active.add(u);
            }
        }

        // Total flow equals excess at sink
        return excess[sink];
    }

    private static void discharge(int u, State s) {
        final int n = s.residual.length;
        while (s.excess[u] > 0) {
            if (s.nextNeighbor[u] >= n) {
                relabel(u, s.residual, s.height);
                s.nextNeighbor[u] = 0;
                continue;
            }
            int v = s.nextNeighbor[u];
            if (s.residual[u][v] > 0 && s.height[u] == s.height[v] + 1) {
                int delta = Math.min(s.excess[u], s.residual[u][v]);
                s.residual[u][v] -= delta;
                s.residual[v][u] += delta;
                s.excess[u] -= delta;
                int prevExcessV = s.excess[v];
                s.excess[v] += delta;
                if (v != s.source && v != s.sink && prevExcessV == 0) {
                    s.active.add(v);
                }
            } else {
                s.nextNeighbor[u]++;
            }
        }
    }

    private static final class State {
        final int[][] residual;
        final int[] height;
        final int[] excess;
        final int[] nextNeighbor;
        final int source;
        final int sink;
        final Queue<Integer> active;

        State(int[][] residual, int[] height, int[] excess, int[] nextNeighbor, int source, int sink, Queue<Integer> active) {
            this.residual = residual;
            this.height = height;
            this.excess = excess;
            this.nextNeighbor = nextNeighbor;
            this.source = source;
            this.sink = sink;
            this.active = active;
        }
    }

    private static void relabel(int u, int[][] residual, int[] height) {
        final int n = residual.length;
        int minHeight = Integer.MAX_VALUE;
        for (int v = 0; v < n; v++) {
            if (residual[u][v] > 0) {
                minHeight = Math.min(minHeight, height[v]);
            }
        }
        if (minHeight < Integer.MAX_VALUE) {
            height[u] = minHeight + 1;
        }
    }

    private static void validate(int[][] capacity, int source, int sink) {
        if (capacity == null || capacity.length == 0) {
            throw new IllegalArgumentException("Capacity matrix must not be null or empty");
        }
        int n = capacity.length;
        for (int i = 0; i < n; i++) {
            if (capacity[i] == null || capacity[i].length != n) {
                throw new IllegalArgumentException("Capacity matrix must be square");
            }
            for (int j = 0; j < n; j++) {
                if (capacity[i][j] < 0) {
                    throw new IllegalArgumentException("Capacities must be non-negative");
                }
            }
        }
        if (source < 0 || sink < 0 || source >= n || sink >= n) {
            throw new IllegalArgumentException("Source and sink must be valid vertex indices");
        }
    }
}

package com.thealgorithms.graph;

/**
 * An implementation of the Stoer-Wagner algorithm to find the global minimum cut of an undirected, weighted graph.
 * A minimum cut is a partition of the graph's vertices into two disjoint sets with the minimum possible edge weight
 * sum connecting the two sets.
 *
 * Wikipedia: https://en.wikipedia.org/wiki/Stoer%E2%80%93Wagner_algorithm
 * Time Complexity: O(V^3) where V is the number of vertices.
 */
public class StoerWagner {

    /**
     * Finds the minimum cut in the given undirected, weighted graph.
     *
     * @param graph An adjacency matrix representing the graph. graph[i][j] is the weight of the edge between i and j.
     * @return The weight of the minimum cut.
     */
    public int findMinCut(int[][] graph) {
        int n = graph.length;
        if (n < 2) {
            return 0;
        }

        int[][] currentGraph = new int[n][n];
        for (int i = 0; i < n; i++) {
            System.arraycopy(graph[i], 0, currentGraph[i], 0, n);
        }

        int minCut = Integer.MAX_VALUE;
        boolean[] merged = new boolean[n];

        for (int phase = 0; phase < n - 1; phase++) {
            boolean[] inSetA = new boolean[n];
            int[] weights = new int[n];
            int prev = -1;
            int last = -1;

            for (int i = 0; i < n - phase; i++) {
                int maxWeight = -1;
                int currentVertex = -1;

                for (int j = 0; j < n; j++) {
                    if (!merged[j] && !inSetA[j] && weights[j] > maxWeight) {
                        maxWeight = weights[j];
                        currentVertex = j;
                    }
                }

                if (currentVertex == -1) {
                    // This can happen if the graph is disconnected.
                    return 0;
                }

                prev = last;
                last = currentVertex;
                inSetA[last] = true;

                for (int j = 0; j < n; j++) {
                    if (!merged[j] && !inSetA[j]) {
                        weights[j] += currentGraph[last][j];
                    }
                }
            }

            minCut = Math.min(minCut, weights[last]);

            // Merge 'last' vertex into 'prev' vertex
            for (int i = 0; i < n; i++) {
                currentGraph[prev][i] += currentGraph[last][i];
                currentGraph[i][prev] = currentGraph[prev][i];
            }
            merged[last] = true;
        }

        return minCut;
    }
}

package com.thealgorithms.graph;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Stack;

/**
 * Finds the strongly connected components in a directed graph.
 *
 * @param adjList The adjacency list representation of the graph.
 * @param n The number of nodes in the graph.
 * @return The number of strongly connected components.
 */
public class StronglyConnectedComponentOptimized {

    public void btrack(HashMap<Integer, List<Integer>> adjList, int[] visited, Stack<Integer> dfsCallsNodes, int currentNode) {
        visited[currentNode] = 1;
        List<Integer> neighbors = adjList.get(currentNode);
        // Check for null before iterating
        if (neighbors != null) {
            for (int neighbor : neighbors) {
                if (visited[neighbor] == -1) {
                    btrack(adjList, visited, dfsCallsNodes, neighbor);
                }
            }
        }
        dfsCallsNodes.add(currentNode);
    }

    public void btrack2(HashMap<Integer, List<Integer>> adjRevList, int[] visited, int currentNode, List<Integer> newScc) {
        visited[currentNode] = 1;
        newScc.add(currentNode);
        List<Integer> neighbors = adjRevList.get(currentNode);
        // Check for null before iterating
        if (neighbors != null) {
            for (int neighbor : neighbors) {
                if (visited[neighbor] == -1) {
                    btrack2(adjRevList, visited, neighbor, newScc);
                }
            }
        }
    }

    public int getOutput(HashMap<Integer, List<Integer>> adjList, int n) {
        int[] visited = new int[n];
        Arrays.fill(visited, -1);
        Stack<Integer> dfsCallsNodes = new Stack<>();

        for (int i = 0; i < n; i++) {
            if (visited[i] == -1) {
                btrack(adjList, visited, dfsCallsNodes, i);
            }
        }

        HashMap<Integer, List<Integer>> adjRevList = new HashMap<>();
        for (int i = 0; i < n; i++) {
            adjRevList.put(i, new ArrayList<>());
        }

        for (int i = 0; i < n; i++) {
            List<Integer> neighbors = adjList.get(i);
            // Check for null before iterating
            if (neighbors != null) {
                for (int neighbor : neighbors) {
                    adjRevList.get(neighbor).add(i);
                }
            }
        }

        Arrays.fill(visited, -1);
        int stronglyConnectedComponents = 0;

        while (!dfsCallsNodes.isEmpty()) {
            int node = dfsCallsNodes.pop();
            if (visited[node] == -1) {
                List<Integer> newScc = new ArrayList<>();
                btrack2(adjRevList, visited, node, newScc);
                stronglyConnectedComponents++;
            }
        }

        return stronglyConnectedComponents;
    }
}

package com.thealgorithms.graph;

import java.util.ArrayList;
import java.util.List;

/**
 * Implementation of Tarjan's Bridge-Finding Algorithm for undirected graphs.
 *
 * <p>A <b>bridge</b> (also called a cut-edge) is an edge in an undirected graph whose removal
 * increases the number of connected components. Bridges represent critical links
 * in a network — if any bridge is removed, part of the network becomes unreachable.</p>
 *
 * <p>The algorithm performs a single Depth-First Search (DFS) traversal, tracking two
 * values for each vertex:</p>
 * <ul>
 *   <li><b>discoveryTime</b> — the time step at which the vertex was first visited.</li>
 *   <li><b>lowLink</b> — the smallest discovery time reachable from the subtree rooted
 *       at that vertex (via back edges).</li>
 * </ul>
 *
 * <p>An edge (u, v) is a bridge if and only if {@code lowLink[v] > discoveryTime[u]},
 * meaning there is no back edge from the subtree of v that can reach u or any ancestor of u.</p>
 *
 * <p>Time Complexity: O(V + E), where V is the number of vertices and E is the number of edges.</p>
 * <p>Space Complexity: O(V + E) for the adjacency list, discovery/low arrays, and recursion stack.</p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Bridge_(graph_theory)">Wikipedia: Bridge (graph theory)</a>
 */
public final class TarjanBridges {

    private TarjanBridges() {
        throw new UnsupportedOperationException("Utility class");
    }

    /**
     * Finds all bridge edges in an undirected graph.
     *
     * <p>The graph is represented as an adjacency list where each vertex is identified by
     * an integer in the range {@code [0, vertexCount)}. For each undirected edge (u, v),
     * v must appear in {@code adjacencyList.get(u)} and u must appear in
     * {@code adjacencyList.get(v)}.</p>
     *
     * @param vertexCount   the total number of vertices in the graph (must be non-negative)
     * @param adjacencyList the adjacency list representation of the graph; must contain
     *                      exactly {@code vertexCount} entries (one per vertex)
     * @return a list of bridge edges, where each bridge is represented as an {@code int[]}
     *         of length 2 with {@code edge[0] < edge[1]}; returns an empty list if no bridges exist
     * @throws IllegalArgumentException if {@code vertexCount} is negative, or if
     *                                  {@code adjacencyList} is null or its size does not match
     *                                  {@code vertexCount}
     */
    public static List<int[]> findBridges(int vertexCount, List<List<Integer>> adjacencyList) {
        if (vertexCount < 0) {
            throw new IllegalArgumentException("vertexCount must be non-negative");
        }
        if (adjacencyList == null || adjacencyList.size() != vertexCount) {
            throw new IllegalArgumentException("adjacencyList size must equal vertexCount");
        }

        List<int[]> bridges = new ArrayList<>();

        if (vertexCount == 0) {
            return bridges;
        }

        BridgeFinder finder = new BridgeFinder(vertexCount, adjacencyList, bridges);

        // Run DFS from every unvisited vertex to handle disconnected graphs
        for (int i = 0; i < vertexCount; i++) {
            if (!finder.visited[i]) {
                finder.dfs(i, -1);
            }
        }

        return bridges;
    }

    private static class BridgeFinder {
        private final List<List<Integer>> adjacencyList;
        private final List<int[]> bridges;
        private final int[] discoveryTime;
        private final int[] lowLink;
        boolean[] visited;
        private int timer;

        BridgeFinder(int vertexCount, List<List<Integer>> adjacencyList, List<int[]> bridges) {
            this.adjacencyList = adjacencyList;
            this.bridges = bridges;
            this.discoveryTime = new int[vertexCount];
            this.lowLink = new int[vertexCount];
            this.visited = new boolean[vertexCount];
            this.timer = 0;
        }

        /**
         * Performs DFS from the given vertex, computing discovery times and low-link values,
         * and collects any bridge edges found.
         *
         * @param u      the current vertex being explored
         * @param parent the parent of u in the DFS tree (-1 if u is a root)
         */
        void dfs(int u, int parent) {
            visited[u] = true;
            discoveryTime[u] = timer;
            lowLink[u] = timer;
            timer++;

            for (int v : adjacencyList.get(u)) {
                if (!visited[v]) {
                    dfs(v, u);
                    lowLink[u] = Math.min(lowLink[u], lowLink[v]);

                    if (lowLink[v] > discoveryTime[u]) {
                        bridges.add(new int[] {Math.min(u, v), Math.max(u, v)});
                    }
                } else if (v != parent) {
                    lowLink[u] = Math.min(lowLink[u], discoveryTime[v]);
                }
            }
        }
    }
}

package com.thealgorithms.graph;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * This class provides solutions to the Traveling Salesman Problem (TSP) using both brute-force and dynamic programming approaches.
 * For more information, see <a href="https://en.wikipedia.org/wiki/Travelling_salesman_problem">Wikipedia</a>.
 * @author  <a href="https://github.com/DenizAltunkapan">Deniz Altunkapan</a>
 */

public final class TravelingSalesman {

    // Private constructor to prevent instantiation
    private TravelingSalesman() {
    }

    /**
     * Solves the Traveling Salesman Problem (TSP) using brute-force approach.
     * This method generates all possible permutations of cities, calculates the total distance for each route, and returns the shortest distance found.
     *
     * @param distanceMatrix A square matrix where element [i][j] represents the distance from city i to city j.
     * @return The shortest possible route distance visiting all cities exactly once and returning to the starting city.
     */
    public static int bruteForce(int[][] distanceMatrix) {
        if (distanceMatrix.length <= 1) {
            return 0;
        }

        List<Integer> cities = new ArrayList<>();
        for (int i = 1; i < distanceMatrix.length; i++) {
            cities.add(i);
        }

        List<List<Integer>> permutations = generatePermutations(cities);
        int minDistance = Integer.MAX_VALUE;

        for (List<Integer> permutation : permutations) {
            List<Integer> route = new ArrayList<>();
            route.add(0);
            route.addAll(permutation);
            int currentDistance = calculateDistance(distanceMatrix, route);
            if (currentDistance < minDistance) {
                minDistance = currentDistance;
            }
        }

        return minDistance;
    }

    /**
     * Computes the total distance of a given route.
     *
     * @param distanceMatrix A square matrix where element [i][j] represents the
     *                       distance from city i to city j.
     * @param route          A list representing the order in which the cities are visited.
     * @return The total distance of the route, or Integer.MAX_VALUE if the route is invalid.
     */
    public static int calculateDistance(int[][] distanceMatrix, List<Integer> route) {
        int distance = 0;
        for (int i = 0; i < route.size() - 1; i++) {
            int d = distanceMatrix[route.get(i)][route.get(i + 1)];
            if (d == Integer.MAX_VALUE) {
                return Integer.MAX_VALUE;
            }
            distance += d;
        }
        int returnDist = distanceMatrix[route.get(route.size() - 1)][route.get(0)];
        return (returnDist == Integer.MAX_VALUE) ? Integer.MAX_VALUE : distance + returnDist;
    }

    /**
     * Generates all permutations of a given list of cities.
     *
     * @param cities A list of cities to permute.
     * @return A list of all possible permutations.
     */
    private static List<List<Integer>> generatePermutations(List<Integer> cities) {
        List<List<Integer>> permutations = new ArrayList<>();
        permute(cities, 0, permutations);
        return permutations;
    }

    /**
     * Recursively generates permutations using backtracking.
     *
     * @param arr     The list of cities.
     * @param k       The current index in the permutation process.
     * @param output  The list to store generated permutations.
     */
    private static void permute(List<Integer> arr, int k, List<List<Integer>> output) {
        if (k == arr.size()) {
            output.add(new ArrayList<>(arr));
            return;
        }
        for (int i = k; i < arr.size(); i++) {
            Collections.swap(arr, i, k);
            permute(arr, k + 1, output);
            Collections.swap(arr, i, k);
        }
    }

    /**
     * Solves the Traveling Salesman Problem (TSP) using dynamic programming with the Held-Karp algorithm.
     *
     * @param distanceMatrix A square matrix where element [i][j] represents the distance from city i to city j.
     * @return The shortest possible route distance visiting all cities exactly once and returning to the starting city.
     * @throws IllegalArgumentException if the input matrix is not square.
     */
    public static int dynamicProgramming(int[][] distanceMatrix) {
        if (distanceMatrix.length == 0) {
            return 0;
        }
        int n = distanceMatrix.length;

        for (int[] row : distanceMatrix) {
            if (row.length != n) {
                throw new IllegalArgumentException("Matrix must be square");
            }
        }

        int[][] dp = new int[n][1 << n];
        for (int[] row : dp) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        dp[0][1] = 0;

        for (int mask = 1; mask < (1 << n); mask++) {
            for (int u = 0; u < n; u++) {
                if ((mask & (1 << u)) == 0 || dp[u][mask] == Integer.MAX_VALUE) {
                    continue;
                }
                for (int v = 0; v < n; v++) {
                    if ((mask & (1 << v)) != 0 || distanceMatrix[u][v] == Integer.MAX_VALUE) {
                        continue;
                    }
                    int newMask = mask | (1 << v);
                    dp[v][newMask] = Math.min(dp[v][newMask], dp[u][mask] + distanceMatrix[u][v]);
                }
            }
        }

        int minDistance = Integer.MAX_VALUE;
        int fullMask = (1 << n) - 1;
        for (int i = 1; i < n; i++) {
            if (dp[i][fullMask] != Integer.MAX_VALUE && distanceMatrix[i][0] != Integer.MAX_VALUE) {
                minDistance = Math.min(minDistance, dp[i][fullMask] + distanceMatrix[i][0]);
            }
        }

        return minDistance == Integer.MAX_VALUE ? 0 : minDistance;
    }
}

package com.thealgorithms.graph;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.PriorityQueue;
import java.util.Set;

/**
 * Yen's algorithm for finding K loopless shortest paths in a directed graph with non-negative edge weights.
 *
 * <p>Input is an adjacency matrix of edge weights. A value of -1 indicates no edge.
 * All existing edge weights must be non-negative. Zero-weight edges are allowed.</p>
 *
 * <p>References:
 * - Wikipedia: Yen's algorithm (https://en.wikipedia.org/wiki/Yen%27s_algorithm)
 * - Dijkstra's algorithm for the base shortest path computation.</p>
 */
public final class YensKShortestPaths {

    private YensKShortestPaths() {
    }

    private static final int NO_EDGE = -1;
    private static final long INF_COST = Long.MAX_VALUE / 4;

    /**
     * Compute up to k loopless shortest paths from src to dst using Yen's algorithm.
     *
     * @param weights adjacency matrix; weights[u][v] = -1 means no edge; otherwise non-negative edge weight
     * @param src source vertex index
     * @param dst destination vertex index
     * @param k maximum number of paths to return (k >= 1)
     * @return list of paths, each path is a list of vertex indices in order from src to dst
     * @throws IllegalArgumentException on invalid inputs (null, non-square, negatives on existing edges, bad indices, k < 1)
     */
    public static List<List<Integer>> kShortestPaths(int[][] weights, int src, int dst, int k) {
        validate(weights, src, dst, k);
        final int n = weights.length;
        // Make a defensive copy to avoid mutating caller's matrix
        int[][] weightsCopy = new int[n][n];
        for (int i = 0; i < n; i++) {
            weightsCopy[i] = Arrays.copyOf(weights[i], n);
        }

        List<Path> shortestPaths = new ArrayList<>();
        PriorityQueue<Path> candidates = new PriorityQueue<>(); // min-heap by cost then lexicographic nodes
        Set<String> seen = new HashSet<>(); // deduplicate candidate paths by node sequence key

        Path first = dijkstra(weightsCopy, src, dst, new boolean[n]);
        if (first == null) {
            return List.of();
        }
        shortestPaths.add(first);

        for (int kIdx = 1; kIdx < k; kIdx++) {
            Path lastPath = shortestPaths.get(kIdx - 1);
            List<Integer> lastNodes = lastPath.nodes;
            for (int i = 0; i < lastNodes.size() - 1; i++) {
                int spurNode = lastNodes.get(i);
                List<Integer> rootPath = lastNodes.subList(0, i + 1);

                // Build modified graph: remove edges that would recreate same root + next edge as any A path
                int[][] modifiedWeights = cloneMatrix(weightsCopy);

                for (Path p : shortestPaths) {
                    if (startsWith(p.nodes, rootPath) && p.nodes.size() > i + 1) {
                        int u = p.nodes.get(i);
                        int v = p.nodes.get(i + 1);
                        modifiedWeights[u][v] = NO_EDGE; // remove edge
                    }
                }
                // Prevent revisiting nodes in rootPath (loopless constraint), except spurNode itself
                boolean[] blocked = new boolean[n];
                for (int j = 0; j < rootPath.size() - 1; j++) {
                    blocked[rootPath.get(j)] = true;
                }

                Path spurPath = dijkstra(modifiedWeights, spurNode, dst, blocked);
                if (spurPath != null) {
                    // concatenate rootPath (excluding spurNode at end) + spurPath
                    List<Integer> totalNodes = new ArrayList<>(rootPath);
                    // spurPath.nodes starts with spurNode; avoid duplication
                    for (int idx = 1; idx < spurPath.nodes.size(); idx++) {
                        totalNodes.add(spurPath.nodes.get(idx));
                    }
                    long rootCost = pathCost(weightsCopy, rootPath);
                    long totalCost = rootCost + spurPath.cost; // spurPath.cost covers from spurNode to dst
                    Path candidate = new Path(totalNodes, totalCost);
                    String key = candidate.key();
                    if (seen.add(key)) {
                        candidates.add(candidate);
                    }
                }
            }
            if (candidates.isEmpty()) {
                break;
            }
            shortestPaths.add(candidates.poll());
        }

        // Map to list of node indices for output
        List<List<Integer>> result = new ArrayList<>(shortestPaths.size());
        for (Path p : shortestPaths) {
            result.add(new ArrayList<>(p.nodes));
        }
        return result;
    }

    private static void validate(int[][] weights, int src, int dst, int k) {
        if (weights == null || weights.length == 0) {
            throw new IllegalArgumentException("Weights matrix must not be null or empty");
        }
        int n = weights.length;
        for (int i = 0; i < n; i++) {
            if (weights[i] == null || weights[i].length != n) {
                throw new IllegalArgumentException("Weights matrix must be square");
            }
            for (int j = 0; j < n; j++) {
                int val = weights[i][j];
                if (val < NO_EDGE) {
                    throw new IllegalArgumentException("Weights must be -1 (no edge) or >= 0");
                }
            }
        }
        if (src < 0 || dst < 0 || src >= n || dst >= n) {
            throw new IllegalArgumentException("Invalid src/dst indices");
        }
        if (k < 1) {
            throw new IllegalArgumentException("k must be >= 1");
        }
    }

    private static boolean startsWith(List<Integer> list, List<Integer> prefix) {
        if (prefix.size() > list.size()) {
            return false;
        }
        for (int i = 0; i < prefix.size(); i++) {
            if (!Objects.equals(list.get(i), prefix.get(i))) {
                return false;
            }
        }
        return true;
    }

    private static int[][] cloneMatrix(int[][] a) {
        int n = a.length;
        int[][] b = new int[n][n];
        for (int i = 0; i < n; i++) {
            b[i] = Arrays.copyOf(a[i], n);
        }
        return b;
    }

    private static long pathCost(int[][] weights, List<Integer> nodes) {
        long cost = 0;
        for (int i = 0; i + 1 < nodes.size(); i++) {
            int u = nodes.get(i);
            int v = nodes.get(i + 1);
            int edgeCost = weights[u][v];
            if (edgeCost < 0) {
                return INF_COST; // invalid
            }
            cost += edgeCost;
        }
        return cost;
    }

    private static Path dijkstra(int[][] weights, int src, int dst, boolean[] blocked) {
        int n = weights.length;
        final long inf = INF_COST;
        long[] dist = new long[n];
        int[] parent = new int[n];
        Arrays.fill(dist, inf);
        Arrays.fill(parent, -1);
        PriorityQueue<Node> queue = new PriorityQueue<>();
        if (blocked[src]) {
            return null;
        }
        dist[src] = 0;
        queue.add(new Node(src, 0));
        while (!queue.isEmpty()) {
            Node current = queue.poll();
            if (current.dist != dist[current.u]) {
                continue;
            }
            if (current.u == dst) {
                break;
            }
            for (int v = 0; v < n; v++) {
                int edgeWeight = weights[current.u][v];
                if (edgeWeight >= 0 && !blocked[v]) {
                    long newDist = current.dist + edgeWeight;
                    if (newDist < dist[v]) {
                        dist[v] = newDist;
                        parent[v] = current.u;
                        queue.add(new Node(v, newDist));
                    }
                }
            }
        }
        if (dist[dst] >= inf) {
            // If src==dst and not blocked, the path is trivial with cost 0
            if (src == dst) {
                List<Integer> nodes = new ArrayList<>();
                nodes.add(src);
                return new Path(nodes, 0);
            }
            return null;
        }
        // Reconstruct path
        List<Integer> nodes = new ArrayList<>();
        int cur = dst;
        while (cur != -1) {
            nodes.add(0, cur);
            cur = parent[cur];
        }
        return new Path(nodes, dist[dst]);
    }

    private static final class Node implements Comparable<Node> {
        final int u;
        final long dist;
        Node(int u, long dist) {
            this.u = u;
            this.dist = dist;
        }
        public int compareTo(Node o) {
            return Long.compare(this.dist, o.dist);
        }
    }

    private static final class Path implements Comparable<Path> {
        final List<Integer> nodes;
        final long cost;
        Path(List<Integer> nodes, long cost) {
            this.nodes = nodes;
            this.cost = cost;
        }
        String key() {
            return nodes.toString();
        }
        @Override
        public int compareTo(Path o) {
            int costCmp = Long.compare(this.cost, o.cost);
            if (costCmp != 0) {
                return costCmp;
            }
            // tie-break lexicographically on nodes
            int minLength = Math.min(this.nodes.size(), o.nodes.size());
            for (int i = 0; i < minLength; i++) {
                int aNode = this.nodes.get(i);
                int bNode = o.nodes.get(i);
                if (aNode != bNode) {
                    return Integer.compare(aNode, bNode);
                }
            }
            return Integer.compare(this.nodes.size(), o.nodes.size());
        }
    }
}

package com.thealgorithms.graph;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.List;

/**
 * 0-1 BFS for shortest paths on graphs with edges weighted 0 or 1.
 *
 * <p>Time Complexity: O(V + E). Space Complexity: O(V).
 *
 * <p>References:
 * <ul>
 *   <li>https://cp-algorithms.com/graph/01_bfs.html</li>
 * </ul>
 */
public final class ZeroOneBfs {

    private ZeroOneBfs() {
        // Utility class; do not instantiate.
    }

    /**
     * Computes shortest distances from {@code src} in a graph whose edges have weight 0 or 1.
     *
     * @param n the number of vertices, labeled {@code 0..n-1}
     * @param adj adjacency list; for each vertex u, {@code adj.get(u)} is a list of pairs
     *            {@code (v, w)} where {@code v} is a neighbor and {@code w} is 0 or 1
     * @param src the source vertex
     * @return an array of distances; {@code Integer.MAX_VALUE} denotes unreachable
     * @throws IllegalArgumentException if {@code n < 0}, {@code src} is out of range,
     *                                  or any edge has weight other than 0 or 1
     */
    public static int[] shortestPaths(int n, List<List<int[]>> adj, int src) {
        if (n < 0 || src < 0 || src >= n) {
            throw new IllegalArgumentException("Invalid n or src");
        }
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        Deque<Integer> dq = new ArrayDeque<>();

        dist[src] = 0;
        dq.addFirst(src);

        while (!dq.isEmpty()) {
            int u = dq.pollFirst();
            List<int[]> edges = adj.get(u);
            if (edges == null) {
                continue;
            }
            for (int[] e : edges) {
                if (e == null || e.length < 2) {
                    continue;
                }
                int v = e[0];
                int w = e[1];
                if (v < 0 || v >= n) {
                    continue; // ignore bad edges
                }
                if (w != 0 && w != 1) {
                    throw new IllegalArgumentException("Edge weight must be 0 or 1");
                }
                int nd = dist[u] + w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    if (w == 0) {
                        dq.addFirst(v);
                    } else {
                        dq.addLast(v);
                    }
                }
            }
        }
        return dist;
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;

// Problem Link: https://en.wikipedia.org/wiki/Activity_selection_problem

public final class ActivitySelection {

    // Private constructor to prevent instantiation of the utility class
    private ActivitySelection() {
    }

    /**
     * Function to perform activity selection using a greedy approach.
     *
     * The goal is to select the maximum number of activities that don't overlap
     * with each other, based on their start and end times. Activities are chosen
     * such that no two selected activities overlap.
     *
     * @param startTimes Array containing the start times of the activities.
     * @param endTimes   Array containing the end times of the activities.
     * @return A list of indices representing the selected activities that can be
     *         performed without overlap.
     */
    public static ArrayList<Integer> activitySelection(int[] startTimes, int[] endTimes) {
        int n = startTimes.length;

        // Create a 2D array to store activity indices along with their start and end
        // times.
        // Each row represents an activity in the format: [activity index, start time,
        // end time].
        int[][] activities = new int[n][3];

        // Populate the 2D array with the activity index, start time, and end time.
        for (int i = 0; i < n; i++) {
            activities[i][0] = i; // Assign the activity index
            activities[i][1] = startTimes[i]; // Assign the start time of the activity
            activities[i][2] = endTimes[i]; // Assign the end time of the activity
        }

        // Sort activities based on their end times in ascending order.
        // This ensures that we always try to finish earlier activities first.
        Arrays.sort(activities, Comparator.comparingDouble(activity -> activity[2]));
        int lastEndTime; // Variable to store the end time of the last selected activity
        // List to store the indices of selected activities
        ArrayList<Integer> selectedActivities = new ArrayList<>();

        // Select the first activity (as it has the earliest end time after sorting)
        selectedActivities.add(activities[0][0]); // Add the first activity index to the result
        lastEndTime = activities[0][2]; // Keep track of the end time of the last selected activity

        // Iterate over the sorted activities to select the maximum number of compatible
        // activities.
        for (int i = 1; i < n; i++) {
            // If the start time of the current activity is greater than or equal to the
            // end time of the last selected activity, it means there's no overlap.
            if (activities[i][1] >= lastEndTime) {
                selectedActivities.add(activities[i][0]); // Select this activity
                lastEndTime = activities[i][2]; // Update the end time of the last selected activity
            }
        }

        // Return the list of selected activity indices.
        return selectedActivities;
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.Arrays;

/**
 * Class to solve the Bandwidth Allocation Problem.
 * The goal is to maximize the value gained by allocating bandwidth to users.
 * Example:
 * Bandwidth = 10
 * Users = [3, 5, 7]
 * Values = [10, 20, 30]
 * The maximum value achievable is 40 by allocating 3 units to user 0 and 7 units to user 2.
 *
 * @author Hardvan
 */
public final class BandwidthAllocation {
    private BandwidthAllocation() {
    }

    /**
     * Allocates bandwidth to maximize value.
     * Steps:
     * 1. Calculate the ratio of value/demand for each user.
     * 2. Sort the users in descending order of the ratio.
     * 3. Allocate bandwidth to users in order of the sorted list.
     * 4. If the bandwidth is not enough to allocate the full demand of a user, allocate a fraction of the demand.
     * 5. Return the maximum value achievable.
     *
     * @param bandwidth total available bandwidth to allocate
     * @param users     array of user demands
     * @param values    array of values associated with each user's demand
     * @return the maximum value achievable
     */
    public static int maxValue(int bandwidth, int[] users, int[] values) {
        int n = users.length;
        double[][] ratio = new double[n][2]; // {index, ratio}

        for (int i = 0; i < n; i++) {
            ratio[i][0] = i;
            ratio[i][1] = (double) values[i] / users[i];
        }

        Arrays.sort(ratio, (a, b) -> Double.compare(b[1], a[1]));

        int maxValue = 0;
        for (int i = 0; i < n; i++) {
            int index = (int) ratio[i][0];
            if (bandwidth >= users[index]) {
                maxValue += values[index];
                bandwidth -= users[index];
            } else {
                maxValue += (int) (ratio[i][1] * bandwidth);
                break;
            }
        }
        return maxValue;
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.Collections;

/**
 * BinaryAddition class to perform binary addition of two binary strings.
 */
public class BinaryAddition {
    /**
     * Computes the sum of two binary characters and a carry.
     * @param a First binary character ('0' or '1').
     * @param b Second binary character ('0' or '1').
     * @param carry The carry from the previous operation ('0' or '1').
     * @return The sum as a binary character ('0' or '1').
     */
    public char sum(char a, char b, char carry) {
        int count = 0;
        if (a == '1') {
            count++;
        }
        if (b == '1') {
            count++;
        }
        if (carry == '1') {
            count++;
        }
        return count % 2 == 0 ? '0' : '1';
    }
    /**
     * Computes the carry for the next higher bit from two binary characters and a carry.
     * @param a First binary character ('0' or '1').
     * @param b Second binary character ('0' or '1').
     * @param carry The carry from the previous operation ('0' or '1').
     * @return The carry for the next bit ('0' or '1').
     */
    public char carry(char a, char b, char carry) {
        int count = 0;
        if (a == '1') {
            count++;
        }
        if (b == '1') {
            count++;
        }
        if (carry == '1') {
            count++;
        }
        return count >= 2 ? '1' : '0';
    }
    /**
     * Adds two binary strings and returns their sum as a binary string.
     * @param a First binary string.
     * @param b Second binary string.
     * @return Binary string representing the sum of the two binary inputs.
     */
    public String addBinary(String a, String b) {
        // Padding the shorter string with leading zeros
        int maxLength = Math.max(a.length(), b.length());
        a = String.join("", Collections.nCopies(maxLength - a.length(), "0")) + a;
        b = String.join("", Collections.nCopies(maxLength - b.length(), "0")) + b;
        StringBuilder result = new StringBuilder();
        char carry = '0';
        // Iterating over the binary strings from the least significant to the most significant bit
        for (int i = maxLength - 1; i >= 0; i--) {
            char sum = sum(a.charAt(i), b.charAt(i), carry);
            carry = carry(a.charAt(i), b.charAt(i), carry);
            result.append(sum);
        }
        // If there's a remaining carry, append it
        if (carry == '1') {
            result.append('1');
        }
        // Reverse the result as we constructed it from the least significant bit
        return result.reverse().toString();
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;

// Problem Link : https://en.wikipedia.org/wiki/Change-making_problem

/**
 * The Coin Change problem finds the minimum number of coins needed
 * to make a given amount using a greedy approach.
 *
 * <p>Note: This greedy approach works optimally for standard coin systems
 * (like Indian currency), but may not work for all arbitrary coin sets.
 * For arbitrary denominations, dynamic programming is preferred.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Change-making_problem">Change-making problem</a>
 */
public final class CoinChange {
    private CoinChange() {
    }

    /**
     * Returns the list of coins used to make the given amount
     * using a greedy algorithm with standard denominations.
     *
     * <p>Time Complexity: O(n log n) where n is the number of coin denominations
     * <p>Space Complexity: O(n)
     *
     * @param amount the total amount to make change for
     * @return list of coins used to make the amount
     */
    public static ArrayList<Integer> coinChangeProblem(int amount) {
        // Define an array of coin denominations in descending order
        Integer[] coins = {1, 2, 5, 10, 20, 50, 100, 500, 2000};

        // Sort the coin denominations in descending order
        Arrays.sort(coins, Comparator.reverseOrder());

        ArrayList<Integer> ans = new ArrayList<>(); // List to store selected coins

        // Iterate through the coin denominations
        for (int i = 0; i < coins.length; i++) {
            // Check if the current coin denomination can be used to reduce the remaining amount
            if (coins[i] <= amount) {
                // Repeatedly subtract the coin denomination from the remaining amount
                while (coins[i] <= amount) {
                    ans.add(coins[i]); // Add the coin to the list of selected coins
                    amount -= coins[i]; // Update the remaining amount
                }
            }
        }
        return ans;
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * This class provides methods to separate the digits of a large positive number into a list.
 */
public class DigitSeparation {
    public DigitSeparation() {
    }
    /**
     * Separates the digits of a large positive number into a list in reverse order.
     * @param largeNumber The large number to separate digits from.
     * @return A list of digits in reverse order.
     */
    public List<Long> digitSeparationReverseOrder(long largeNumber) {
        List<Long> result = new ArrayList<>();
        if (largeNumber != 0) {
            while (largeNumber != 0) {
                result.add(Math.abs(largeNumber % 10));
                largeNumber = largeNumber / 10;
            }
        } else {
            result.add(0L);
        }
        return result;
    }
    /**
     * Separates the digits of a large positive number into a list in forward order.
     * @param largeNumber The large number to separate digits from.
     * @return A list of digits in forward order.
     */
    public List<Long> digitSeparationForwardOrder(long largeNumber) {
        List<Long> result = this.digitSeparationReverseOrder(largeNumber);
        Collections.reverse(result);
        return result;
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.ArrayList;
import java.util.List;

/**
 * Class to represent a fraction as a sum of unique unit fractions.
 * Example:
 * 2/3 = 1/2 + 1/6
 * 3/10 = 1/4 + 1/20
 *
 * @author Hardvan
 */
public final class EgyptianFraction {
    private EgyptianFraction() {
    }

    /**
     * Calculates the Egyptian Fraction representation of a given fraction.
     *
     * @param numerator   the numerator of the fraction
     * @param denominator the denominator of the fraction
     * @return List of unit fractions represented as strings "1/x"
     */
    public static List<String> getEgyptianFraction(int numerator, int denominator) {
        List<String> result = new ArrayList<>();
        while (numerator != 0) {
            int x = (int) Math.ceil((double) denominator / numerator);
            result.add("1/" + x);
            numerator = numerator * x - denominator;
            denominator = denominator * x;
        }
        return result;
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.Arrays;
import java.util.Comparator;

/**
 * The FractionalKnapsack class provides a method to solve the fractional knapsack problem
 * using a greedy algorithm approach. It allows for selecting fractions of items to maximize
 * the total value in a knapsack with a given weight capacity.
 *
 * The problem consists of a set of items, each with a weight and a value, and a knapsack
 * that can carry a maximum weight. The goal is to maximize the value of items in the knapsack,
 * allowing for the inclusion of fractions of items.
 *
 * Problem Link: https://en.wikipedia.org/wiki/Continuous_knapsack_problem
 */
public final class FractionalKnapsack {
    private FractionalKnapsack() {
    }

    /**
     * Computes the maximum value that can be accommodated in a knapsack of a given capacity.
     *
     * @param weight an array of integers representing the weights of the items
     * @param value an array of integers representing the values of the items
     * @param capacity an integer representing the maximum weight capacity of the knapsack
     * @return the maximum value that can be obtained by including the items in the knapsack
     */
    public static int fractionalKnapsack(int[] weight, int[] value, int capacity) {
        double[][] ratio = new double[weight.length][2];

        for (int i = 0; i < weight.length; i++) {
            ratio[i][0] = i;
            ratio[i][1] = value[i] / (double) weight[i];
        }

        Arrays.sort(ratio, Comparator.comparingDouble(o -> o[1]));

        int finalValue = 0;
        double current = capacity;

        for (int i = ratio.length - 1; i >= 0; i--) {
            int index = (int) ratio[i][0];
            if (current >= weight[index]) {
                finalValue += value[index];
                current -= weight[index];
            } else {
                finalValue += (int) (ratio[i][1] * current);
                break;
            }
        }
        return finalValue;
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.HashMap;
import java.util.LinkedList;
import java.util.Map;

/**
 * Implementation of the Gale-Shapley Algorithm for Stable Matching.
 * Problem link: https://en.wikipedia.org/wiki/Stable_marriage_problem
 */
public final class GaleShapley {

    private GaleShapley() {
    }

    /**
     * Function to find stable matches between men and women.
     *
     * @param womenPrefs A map containing women's preferences where each key is a woman and the value is an array of men in order of preference.
     * @param menPrefs   A map containing men's preferences where each key is a man and the value is an array of women in order of preference.
     * @return A map containing stable matches where the key is a woman and the value is her matched man.
     */
    public static Map<String, String> stableMatch(Map<String, LinkedList<String>> womenPrefs, Map<String, LinkedList<String>> menPrefs) {
        // Initialize all men as free
        Map<String, String> engagements = new HashMap<>();
        LinkedList<String> freeMen = new LinkedList<>(menPrefs.keySet());

        // While there are free men
        while (!freeMen.isEmpty()) {
            String man = freeMen.poll(); // Get the first free man
            LinkedList<String> manPref = menPrefs.get(man); // Get the preferences of the man

            // Check if manPref is null or empty
            if (manPref == null || manPref.isEmpty()) {
                continue; // Skip if no preferences
            }

            // Propose to the first woman in the man's preference list
            String woman = manPref.poll();
            String fiance = engagements.get(woman);

            // If the woman is not engaged, engage her with the current man
            if (fiance == null) {
                engagements.put(woman, man);
            } else {
                // If the woman prefers the current man over her current fiance
                LinkedList<String> womanPrefList = womenPrefs.get(woman);

                // Check if womanPrefList is null
                if (womanPrefList == null) {
                    continue; // Skip if no preferences for the woman
                }

                if (womanPrefList.indexOf(man) < womanPrefList.indexOf(fiance)) {
                    engagements.put(woman, man);
                    freeMen.add(fiance); // Previous fiance becomes free
                } else {
                    // Woman rejects the new proposal, the man remains free
                    freeMen.add(man);
                }
            }
        }
        return engagements; // Return the stable matches
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.ArrayList;
import java.util.Arrays;

// Problem Link: https://en.wikipedia.org/wiki/Job-shop_scheduling

public final class JobSequencing {
    private JobSequencing() {
    }

    // Define a Job class that implements Comparable for sorting by profit in descending order
    static class Job implements Comparable<Job> {
        char id;
        int deadline;
        int profit;

        // Compare jobs by profit in descending order
        @Override
        public int compareTo(Job otherJob) {
            return otherJob.profit - this.profit;
        }

        Job(char id, int deadline, int profit) {
            this.id = id;
            this.deadline = deadline;
            this.profit = profit;
        }
    }

    // Function to print the job sequence
    public static String findJobSequence(ArrayList<Job> jobs, int size) {
        Boolean[] slots = new Boolean[size];
        Arrays.fill(slots, Boolean.FALSE);

        int[] result = new int[size];

        // Iterate through jobs to find the optimal job sequence
        for (int i = 0; i < size; i++) {
            for (int j = jobs.get(i).deadline - 1; j >= 0; j--) {
                if (!slots[j]) {
                    result[j] = i;
                    slots[j] = Boolean.TRUE;
                    break;
                }
            }
        }

        // Create a StringBuilder to build the job sequence string
        StringBuilder jobSequenceBuilder = new StringBuilder();
        jobSequenceBuilder.append("Job Sequence: ");
        for (int i = 0; i < jobs.size(); i++) {
            if (slots[i]) {
                jobSequenceBuilder.append(jobs.get(result[i]).id).append(" -> ");
            }
        }

        // Remove the trailing " -> " from the job sequence
        if (jobSequenceBuilder.length() >= 4) {
            jobSequenceBuilder.setLength(jobSequenceBuilder.length() - 4);
        }

        // Return the job sequence as a string
        return jobSequenceBuilder.toString();
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.Arrays;

/**
 * Given a set of points and a number k.
 * The goal is to minimize the maximum distance between any point and its nearest center.
 * Each point is assigned to the nearest center.
 * The distance between two points is the Euclidean distance.
 * The problem is NP-hard.
 *
 * @author Hardvan
 */
public final class KCenters {
    private KCenters() {
    }

    /**
     * Finds the maximum distance to the nearest center given k centers.
     * Steps:
     * 1. Initialize an array {@code selected} of size n and an array {@code maxDist} of size n.
     * 2. Set the first node as selected and update the maxDist array.
     * 3. For each center, find the farthest node from the selected centers.
     * 4. Update the maxDist array.
     * 5. Return the maximum distance to the nearest center.
     *
     * @param distances matrix representing distances between nodes
     * @param k         the number of centers
     * @return the maximum distance to the nearest center
     */
    public static int findKCenters(int[][] distances, int k) {
        int n = distances.length;
        boolean[] selected = new boolean[n];
        int[] maxDist = new int[n];

        Arrays.fill(maxDist, Integer.MAX_VALUE);

        selected[0] = true;
        for (int i = 1; i < n; i++) {
            maxDist[i] = Math.min(maxDist[i], distances[0][i]);
        }

        for (int centers = 1; centers < k; centers++) {
            int farthest = -1;
            for (int i = 0; i < n; i++) {
                if (!selected[i] && (farthest == -1 || maxDist[i] > maxDist[farthest])) {
                    farthest = i;
                }
            }
            selected[farthest] = true;
            for (int i = 0; i < n; i++) {
                maxDist[i] = Math.min(maxDist[i], distances[farthest][i]);
            }
        }

        int result = 0;
        for (int dist : maxDist) {
            result = Math.max(result, dist);
        }
        return result;
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Problem Statement:
 * Given an array of intervals where intervals[i] = [starti, endi].
 *
 * Merge all overlapping intervals and return an array of the non-overlapping
 * intervals
 * that cover all the intervals in the input.
 */
public final class MergeIntervals {

    /**
     * Private constructor to prevent instantiation of this utility class.
     */
    private MergeIntervals() {
    }

    /**
     * Merges overlapping intervals from the given array of intervals.
     *
     * The method sorts the intervals by their start time, then iterates through the
     * sorted intervals
     * and merges overlapping intervals. If an interval overlaps with the last
     * merged interval,
     * it updates the end time of the last merged interval. Otherwise, it adds the
     * interval as a new entry.
     *
     * @param intervals A 2D array representing intervals where each element is an
     *                  interval [starti, endi].
     * @return A 2D array of merged intervals where no intervals overlap.
     *
     *         Example:
     *         Input: {{1, 3}, {2, 6}, {8, 10}, {15, 18}}
     *         Output: {{1, 6}, {8, 10}, {15, 18}}
     */
    public static int[][] merge(int[][] intervals) {
        // Sort the intervals by their start time (ascending order)
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        // List to store merged intervals
        List<int[]> merged = new ArrayList<>();

        for (int[] interval : intervals) { // Each interval
            // If the merged list is empty or the current interval does not overlap with
            // the last merged interval, add it to the merged list.
            if (merged.isEmpty() || interval[0] > merged.get(merged.size() - 1)[1]) {
                merged.add(interval);
            } else {
                // If there is an overlap, merge the intervals by updating the end time
                // of the last merged interval to the maximum end time between the two
                // intervals.
                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], interval[1]);
            }
        }

        // Convert the list of merged intervals back to a 2D array and return it
        return merged.toArray(new int[merged.size()][]);
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.Arrays;

public final class MinimizingLateness {
    private MinimizingLateness() {
    }

    public static class Job {
        String jobName;
        int startTime = 0;
        int lateness = 0;
        int processingTime;
        int deadline;

        public Job(String jobName, int processingTime, int deadline) {
            this.jobName = jobName;
            this.processingTime = processingTime;
            this.deadline = deadline;
        }

        public static Job of(String jobName, int processingTime, int deadline) {
            return new Job(jobName, processingTime, deadline);
        }

        @Override
        public String toString() {
            return String.format("%s, startTime: %d, endTime: %d, lateness: %d", jobName, startTime, processingTime + startTime, lateness);
        }
    }

    static void calculateLateness(Job... jobs) {

        // sort the jobs based on their deadline
        Arrays.sort(jobs, (a, b) -> a.deadline - b.deadline);

        int startTime = 0;

        for (Job job : jobs) {
            job.startTime = startTime;
            startTime += job.processingTime;
            job.lateness = Math.max(0, startTime - job.deadline); // if the job finishes before deadline the lateness is 0
        }
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.Arrays;

/**
 * The MinimumWaitingTime class provides a method to calculate the minimum
 * waiting time for a list of queries using a greedy algorithm.
 *
 * @author Hardvan
 */
public final class MinimumWaitingTime {
    private MinimumWaitingTime() {
    }

    /**
     * Calculates the minimum waiting time for a list of queries.
     * The function sorts the queries in non-decreasing order and then calculates
     * the waiting time for each query based on its position in the sorted list.
     *
     * @param queries an array of integers representing the query times in picoseconds
     * @return the minimum waiting time in picoseconds
     */
    public static int minimumWaitingTime(int[] queries) {
        int n = queries.length;
        if (n <= 1) {
            return 0;
        }

        Arrays.sort(queries);

        int totalWaitingTime = 0;
        for (int i = 0; i < n; i++) {
            totalWaitingTime += queries[i] * (n - i - 1);
        }
        return totalWaitingTime;
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.PriorityQueue;

/**
 * Class to solve the Optimal File Merging Problem.
 * The goal is to minimize the cost of merging files, where the cost of merging two files is the sum of their sizes.
 * The cost of merging all files is the sum of the costs of merging each pair of files.
 * Example:
 * files = [4, 3, 2, 6]
 * The minimum cost to merge all files is 29.
 * Steps:
 * 1. Merge files 2 and 3 (cost = 2 + 3 = 5). New files = [4, 5, 6]
 * 2. Merge files 4 and 5 (cost = 4 + 5 = 9). New files = [6, 9]
 * 3. Merge files 6 and 9 (cost = 6 + 9 = 15). New files = [15]
 * Total cost = 5 + 9 + 15 = 29
 *
 * @author Hardvan
 */
public final class OptimalFileMerging {
    private OptimalFileMerging() {
    }

    /**
     * Calculates the minimum cost to merge all files.
     * Steps:
     * 1. Add all files to a min heap.
     * 2. Remove the two smallest files from the heap, merge them, and add the result back to the heap.
     * 3. Repeat step 2 until there is only one file left in the heap.
     * 4. The total cost is the sum of all the costs of merging the files.
     *
     * @param files array of file sizes
     * @return the minimum cost to merge the files
     */
    public static int minMergeCost(int[] files) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        for (int file : files) {
            minHeap.add(file);
        }

        int totalCost = 0;
        while (minHeap.size() > 1) {
            int first = minHeap.poll();
            int second = minHeap.poll();
            int cost = first + second;
            totalCost += cost;

            minHeap.add(cost);
        }
        return totalCost;
    }
}

package com.thealgorithms.greedyalgorithms;

/**
 * The StockProfitCalculator class provides a method to calculate the maximum profit
 * that can be made from a single buy and sell of one share of stock.
 * The approach uses a greedy algorithm to efficiently determine the maximum profit.
 *
 * @author Hardvan
 */
public final class StockProfitCalculator {
    private StockProfitCalculator() {
    }

    /**
     * Calculates the maximum profit from a list of stock prices.
     *
     * @param prices an array of integers representing the stock prices on different days
     * @return the maximum profit that can be achieved from a single buy and sell
     * transaction, or 0 if no profit can be made
     */
    public static int maxProfit(int[] prices) {
        if (prices == null || prices.length == 0) {
            return 0;
        }

        int minPrice = prices[0];
        int maxProfit = 0;
        for (int price : prices) {
            minPrice = Math.min(price, minPrice);
            maxProfit = Math.max(price - minPrice, maxProfit);
        }
        return maxProfit;
    }
}

package com.thealgorithms.io;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;

/**
 * Mimics the actions of the Original buffered reader
 * implements other actions, such as peek(n) to lookahead,
 * block() to read a chunk of size {BUFFER SIZE}
 * <p>
 * Author: Kumaraswamy B.G (Xoma Dev)
 */
public class BufferedReader {

    private static final int DEFAULT_BUFFER_SIZE = 5;

    /**
     * The maximum number of bytes the buffer can hold.
     * Value is changed when encountered Eof to not
     * cause overflow read of 0 bytes
     */

    private int bufferSize;
    private final byte[] buffer;

    /**
     * posRead -> indicates the next byte to read
     */
    private int posRead = 0;
    private int bufferPos = 0;

    private boolean foundEof = false;

    private InputStream input;

    public BufferedReader(byte[] input) throws IOException {
        this(new ByteArrayInputStream(input));
    }

    public BufferedReader(InputStream input) throws IOException {
        this(input, DEFAULT_BUFFER_SIZE);
    }

    public BufferedReader(InputStream input, int bufferSize) throws IOException {
        this.input = input;
        if (input.available() == -1) {
            throw new IOException("Empty or already closed stream provided");
        }

        this.bufferSize = bufferSize;
        buffer = new byte[bufferSize];
    }

    /**
     * Reads a single byte from the stream
     */
    public int read() throws IOException {
        if (needsRefill()) {
            if (foundEof) {
                return -1;
            }
            // the buffer is empty, or the buffer has
            // been completely read and needs to be refilled
            refill();
        }
        return buffer[posRead++] & 0xff; // read and un-sign it
    }

    /**
     * Number of bytes not yet been read
     */

    public int available() throws IOException {
        int available = input.available();
        if (needsRefill()) {
            // since the block is already empty,
            // we have no responsibility yet
            return available;
        }
        return bufferPos - posRead + available;
    }

    /**
     * Returns the next character
     */

    public int peek() throws IOException {
        return peek(1);
    }

    /**
     * Peeks and returns a value located at next {n}
     */

    public int peek(int n) throws IOException {
        int available = available();
        if (n >= available) {
            throw new IOException("Out of range, available %d, but trying with %d".formatted(available, n));
        }
        pushRefreshData();

        if (n >= bufferSize) {
            throw new IllegalAccessError("Cannot peek %s, maximum upto %s (Buffer Limit)".formatted(n, bufferSize));
        }
        return buffer[n];
    }

    /**
     * Removes the already read bytes from the buffer
     * in order to make space for new bytes to be filled up.
     * <p>
     * This may also do the job to read first time data (the whole buffer is empty)
     */

    private void pushRefreshData() throws IOException {
        for (int i = posRead, j = 0; i < bufferSize; i++, j++) {
            buffer[j] = buffer[i];
        }

        bufferPos -= posRead;
        posRead = 0;

        // fill out the spaces that we've
        // emptied
        justRefill();
    }

    /**
     * Reads one complete block of size {bufferSize}
     * if found eof, the total length of an array will
     * be that of what's available
     *
     * @return a completed block
     */
    public byte[] readBlock() throws IOException {
        pushRefreshData();

        byte[] cloned = new byte[bufferSize];
        // arraycopy() function is better than clone()
        if (bufferPos >= 0) {
            System.arraycopy(buffer, 0, cloned, 0,
                // important to note that, bufferSize does not stay constant
                // once the class is defined. See justRefill() function
                bufferSize);
        }
        // we assume that already a chunk
        // has been read
        refill();
        return cloned;
    }

    private boolean needsRefill() {
        return bufferPos == 0 || posRead == bufferSize;
    }

    private void refill() throws IOException {
        posRead = 0;
        bufferPos = 0;
        justRefill();
    }

    private void justRefill() throws IOException {
        assertStreamOpen();

        // try to fill in the maximum we can until
        // we reach EOF
        while (bufferPos < bufferSize) {
            int read = input.read();
            if (read == -1) {
                // reached end-of-file, no more data left
                // to be read
                foundEof = true;
                // rewrite the BUFFER_SIZE, to know that we've reached
                // EOF when requested refill
                bufferSize = bufferPos;
            }
            buffer[bufferPos++] = (byte) read;
        }
    }

    private void assertStreamOpen() {
        if (input == null) {
            throw new IllegalStateException("Input Stream already closed!");
        }
    }

    public void close() throws IOException {
        if (input != null) {
            try {
                input.close();
            } finally {
                input = null;
            }
        }
    }
}

package com.thealgorithms.lineclipping;

import com.thealgorithms.lineclipping.utils.Line;
import com.thealgorithms.lineclipping.utils.Point;

/**
 * @author shikarisohan
 * @since 10/4/24
 * Cohen-Sutherland Line Clipping Algorithm
 *
 * This algorithm is used to clip a line segment to a rectangular window.
 * It assigns a region code to each endpoint of the line segment, and
 * then efficiently determines whether the line segment is fully inside,
 * fully outside, or partially inside the window.
 *
 * Reference:
 * https://en.wikipedia.org/wiki/Cohen%E2%80%93Sutherland_algorithm
 *
 * Clipping window boundaries are defined as (xMin, yMin) and (xMax, yMax).
 * The algorithm computes the clipped line segment if it's partially or
 * fully inside the clipping window.
 */
public class CohenSutherland {

    // Region codes for the 9 regions
    private static final int INSIDE = 0; // 0000
    private static final int LEFT = 1; // 0001
    private static final int RIGHT = 2; // 0010
    private static final int BOTTOM = 4; // 0100
    private static final int TOP = 8; // 1000

    // Define the clipping window
    double xMin;
    double yMin;
    double xMax;
    double yMax;

    public CohenSutherland(double xMin, double yMin, double xMax, double yMax) {
        this.xMin = xMin;
        this.yMin = yMin;
        this.xMax = xMax;
        this.yMax = yMax;
    }

    // Compute the region code for a point (x, y)
    private int computeCode(double x, double y) {
        int code = INSIDE;

        if (x < xMin) // to the left of rectangle
        {
            code |= LEFT;
        } else if (x > xMax) // to the right of rectangle
        {
            code |= RIGHT;
        }
        if (y < yMin) // below the rectangle
        {
            code |= BOTTOM;
        } else if (y > yMax) // above the rectangle
        {
            code |= TOP;
        }

        return code;
    }

    // Cohen-Sutherland algorithm to return the clipped line
    public Line cohenSutherlandClip(Line line) {
        double x1 = line.start.x;
        double y1 = line.start.y;
        double x2 = line.end.x;
        double y2 = line.end.y;

        int code1 = computeCode(x1, y1);
        int code2 = computeCode(x2, y2);
        boolean accept = false;

        while (true) {
            if ((code1 == 0) && (code2 == 0)) {
                // Both points are inside the rectangle
                accept = true;
                break;
            } else if ((code1 & code2) != 0) {
                // Both points are outside the rectangle in the same region
                break;
            } else {
                // Some segment of the line is inside the rectangle
                double x = 0;
                double y = 0;

                // Pick an endpoint that is outside the rectangle
                int codeOut = (code1 != 0) ? code1 : code2;

                // Find the intersection point using the line equation
                if ((codeOut & TOP) != 0) {
                    // Point is above the rectangle
                    x = x1 + (x2 - x1) * (yMax - y1) / (y2 - y1);
                    y = yMax;
                } else if ((codeOut & BOTTOM) != 0) {
                    // Point is below the rectangle
                    x = x1 + (x2 - x1) * (yMin - y1) / (y2 - y1);
                    y = yMin;
                } else if ((codeOut & RIGHT) != 0) {
                    // Point is to the right of the rectangle
                    y = y1 + (y2 - y1) * (xMax - x1) / (x2 - x1);
                    x = xMax;
                } else if ((codeOut & LEFT) != 0) {
                    // Point is to the left of the rectangle
                    y = y1 + (y2 - y1) * (xMin - x1) / (x2 - x1);
                    x = xMin;
                }

                // Replace the point outside the rectangle with the intersection point
                if (codeOut == code1) {
                    x1 = x;
                    y1 = y;
                    code1 = computeCode(x1, y1);
                } else {
                    x2 = x;
                    y2 = y;
                    code2 = computeCode(x2, y2);
                }
            }
        }

        if (accept) {
            return new Line(new Point(x1, y1), new Point(x2, y2));
        } else {

            return null; // The line is fully rejected
        }
    }
}

package com.thealgorithms.lineclipping;

import com.thealgorithms.lineclipping.utils.Line;
import com.thealgorithms.lineclipping.utils.Point;

/**
 * @author shikarisohan
 * @since 10/5/24
 *
 *  * The Liang-Barsky line clipping algorithm is an efficient algorithm for
 *  * line clipping against a rectangular window. It is based on the parametric
 *  * equation of a line and checks the intersections of the line with the
 *  * window boundaries. This algorithm calculates the intersection points,
 *  * if any, and returns the clipped line that lies inside the window.
 *  *
 *  * Reference:
 *  * https://en.wikipedia.org/wiki/Liang%E2%80%93Barsky_algorithm
 *
 * Clipping window boundaries are defined as (xMin, yMin) and (xMax, yMax).
 * The algorithm computes the clipped line segment if it's partially or
 * fully inside the clipping window.
 */
public class LiangBarsky {

    // Define the clipping window
    double xMin;
    double xMax;
    double yMin;
    double yMax;

    public LiangBarsky(double xMin, double yMin, double xMax, double yMax) {
        this.xMin = xMin;
        this.yMin = yMin;
        this.xMax = xMax;
        this.yMax = yMax;
    }

    // Liang-Barsky algorithm to return the clipped line
    public Line liangBarskyClip(Line line) {
        double dx = line.end.x - line.start.x;
        double dy = line.end.y - line.start.y;

        double[] p = {-dx, dx, -dy, dy};
        double[] q = {line.start.x - xMin, xMax - line.start.x, line.start.y - yMin, yMax - line.start.y};

        double[] resultT = clipLine(p, q);

        if (resultT == null) {
            return null; // Line is outside the clipping window
        }

        return calculateClippedLine(line, resultT[0], resultT[1], dx, dy);
    }

    // clip the line by adjusting t0 and t1 for each edge
    private double[] clipLine(double[] p, double[] q) {
        double t0 = 0.0;
        double t1 = 1.0;

        for (int i = 0; i < 4; i++) {
            double t = q[i] / p[i];
            if (p[i] == 0 && q[i] < 0) {
                return null; // Line is outside the boundary
            } else if (p[i] < 0) {
                if (t > t1) {
                    return null;
                } // Line is outside
                if (t > t0) {
                    t0 = t;
                } // Update t0
            } else if (p[i] > 0) {
                if (t < t0) {
                    return null;
                } // Line is outside
                if (t < t1) {
                    t1 = t;
                } // Update t1
            }
        }

        return new double[] {t0, t1}; // Return valid t0 and t1
    }

    // calculate the clipped line based on t0 and t1
    private Line calculateClippedLine(Line line, double t0, double t1, double dx, double dy) {
        double clippedX1 = line.start.x + t0 * dx;
        double clippedY1 = line.start.y + t0 * dy;
        double clippedX2 = line.start.x + t1 * dx;
        double clippedY2 = line.start.y + t1 * dy;

        return new Line(new Point(clippedX1, clippedY1), new Point(clippedX2, clippedY2));
    }
}

