package com.thealgorithms.machinelearning;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * K-Nearest Neighbors (KNN) classifier.
 *
 * <p>
 * K-Nearest Neighbors is a supervised machine learning algorithm that
 * classifies a sample based on the majority class among its {@code k}
 * nearest training samples using the Euclidean distance metric.
 *
 * <p>
 * The classifier stores the training dataset during the fitting phase and
 * predicts class labels for new samples without building an explicit model.
 *
 * @see <a href="https://en.wikipedia.org/wiki/K-nearest_neighbors_algorithm">
 *      K-Nearest Neighbors</a>
 */
public final class KNearestNeighbors {
    private final int k;
    private double[][] trainingFeatures;
    private int[] trainingLabels;
    private int numFeatures;

    /**
     * Constructs a K-Nearest Neighbors classifier with the specified number
     * of neighbors.
     *
     * @param k the number of nearest neighbors to consider during prediction
     */
    public KNearestNeighbors(int k) {

        if (k <= 0) {
            throw new IllegalArgumentException("k must be greater than 0.");
        }

        this.k = k;
    }

    /**
     * Represents a neighboring training sample and its distance from the test
     * sample.
     */
    private record Neighbor(double distance, int label) {
    }

    /**
     * Fits the classifier using the provided training dataset.
     *
     * <p>
     * The training feature vectors and their corresponding class labels are
     * stored for use during prediction.
     *
     * @param features the training feature vectors
     * @param labels   the corresponding class labels
     */
    public void fit(double[][] features, int[] labels) {

        if (features == null || labels == null) {
            throw new IllegalArgumentException("Features and labels cannot be null.");
        }

        if (features.length == 0 || labels.length == 0) {
            throw new IllegalArgumentException("Features and labels cannot be empty.");
        }

        if (features.length != labels.length) {
            throw new IllegalArgumentException("Features and labels must have the same length.");
        }

        if (k > features.length) {
            throw new IllegalArgumentException("k cannot be greater than the number of training samples.");
        }

        if (features[0] == null) {
            throw new IllegalArgumentException("Feature vectors cannot be null.");
        }

        numFeatures = features[0].length;

        if (numFeatures == 0) {
            throw new IllegalArgumentException("Feature vectors cannot be empty.");
        }

        for (double[] sample : features) {
            if (sample == null) {
                throw new IllegalArgumentException("Feature vectors cannot be null.");
            }

            if (sample.length != numFeatures) {
                throw new IllegalArgumentException("All feature vectors must have the same dimension.");
            }
        }

        this.trainingFeatures = new double[features.length][];

        for (int i = 0; i < features.length; i++) {
            this.trainingFeatures[i] = features[i].clone();
        }
        this.trainingLabels = labels.clone();
    }

    /**
     * Computes the Euclidean distance between two feature vectors.
     *
     * @param first  the first feature vector
     * @param second the second feature vector
     * @return the Euclidean distance between the two vectors
     */
    private static double euclideanDistance(double[] first, double[] second) {
        double sum = 0.0;

        for (int i = 0; i < first.length; i++) {
            double difference = first[i] - second[i];
            sum += difference * difference;
        }

        return Math.sqrt(sum);
    }

    /**
     * Predicts the class label for a single sample.
     *
     * <p>
     * The prediction is made by finding the {@code k} nearest neighbors
     * among the training samples and selecting the class with the highest
     * number of votes. In the event of a tie, the smaller class label is
     * returned.
     *
     * @param testPoint the sample to classify
     * @return the predicted class label
     */
    public int predict(double[] testPoint) {
        if (trainingFeatures == null || trainingLabels == null) {
            throw new IllegalStateException("Classifier has not been fitted.");
        }

        if (testPoint == null) {
            throw new IllegalArgumentException("Sample cannot be null.");
        }

        if (testPoint.length != numFeatures) {
            throw new IllegalArgumentException("Sample length must match training feature count.");
        }

        List<Neighbor> neighbors = new ArrayList<>(trainingFeatures.length);

        for (int i = 0; i < trainingFeatures.length; i++) {
            double distance = euclideanDistance(trainingFeatures[i], testPoint);
            neighbors.add(new Neighbor(distance, trainingLabels[i]));
        }

        neighbors.sort(Comparator.comparingDouble(Neighbor::distance));

        Map<Integer, Integer> votes = new HashMap<>();

        for (int i = 0; i < k; i++) {
            int label = neighbors.get(i).label();
            votes.merge(label, 1, Integer::sum);
        }

        int predictedLabel = -1;
        int maxVotes = -1;

        for (Map.Entry<Integer, Integer> entry : votes.entrySet()) {
            int label = entry.getKey();
            int count = entry.getValue();

            if (count > maxVotes || (count == maxVotes && label < predictedLabel)) {
                maxVotes = count;
                predictedLabel = label;
            }
        }

        return predictedLabel;
    }

    /**
     * Predicts class labels for multiple samples.
     *
     * @param samples the samples to classify
     * @return an array containing the predicted class label for each sample
     */
    public int[] predict(double[][] samples) {

        if (samples == null) {
            throw new IllegalArgumentException("Samples cannot be null.");
        }

        int[] predictions = new int[samples.length];

        for (int i = 0; i < samples.length; i++) {
            predictions[i] = predict(samples[i]);
        }

        return predictions;
    }
}

package com.thealgorithms.machinelearning;

/**
 * A simple Linear Regression model implemented from scratch using Gradient Descent.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Linear_regression">Linear Regression (Wikipedia)</a>
 * @author Vraj Prajapati (Rosander0)
 */
public class LinearRegression {
    private double m; // Slope (weight)
    private double b; // Y-intercept (bias)
    private final double learningRate;
    private final int epochs;

    /**
     * Constructs a Linear Regression model with the given hyperparameters.
     *
     * @param learningRate controls the step size during gradient descent
     * @param epochs the number of iterations to train the model
     */
    public LinearRegression(double learningRate, int epochs) {
        this.learningRate = learningRate;
        this.epochs = epochs;
        this.m = 0.0;
        this.b = 0.0;
    }

    /**
     * Trains the model on the provided dataset using batch gradient descent.
     *
     * @param x the input feature values
     * @param y the corresponding target values
     * @throws IllegalArgumentException if the arrays are null, empty, or of differing lengths
     */
    public void fit(double[] x, double[] y) {
        if (x == null || y == null || x.length != y.length || x.length == 0) {
            throw new IllegalArgumentException("X and Y must be non-null, non-empty, and of the same length.");
        }

        int n = x.length;

        for (int epoch = 0; epoch < epochs; epoch++) {
            double mGradient = 0;
            double bGradient = 0;

            // Calculate gradients across the entire dataset
            for (int i = 0; i < n; i++) {
                double prediction = (m * x[i]) + b;
                double error = prediction - y[i];

                // Partial derivatives of the Mean Squared Error cost function
                mGradient += error * x[i];
                bGradient += error;
            }

            // Average the gradients and update the parameters
            m -= 2.0 / n * mGradient * learningRate;
            b -= 2.0 / n * bGradient * learningRate;
        }
    }

    /**
     * Predicts the output for a given input x.
     *
     * @param x the input value
     * @return the predicted output
     */
    public double predict(double x) {
        return (m * x) + b;
    }

    /**
     * Calculates the Mean Squared Error of the model against a dataset.
     *
     * @param x the input feature values
     * @param y the corresponding target values
     * @return the mean squared error
     */
    public double calculateMSE(double[] x, double[] y) {
        double totalSquaredError = 0;
        int n = x.length;
        for (int i = 0; i < n; i++) {
            double error = predict(x[i]) - y[i];
            totalSquaredError += error * error;
        }
        return totalSquaredError / n;
    }

    /**
     * @return the learned slope of the regression line
     */
    public double getSlope() {
        return m;
    }

    /**
     * @return the learned y-intercept of the regression line
     */
    public double getIntercept() {
        return b;
    }
}

package com.thealgorithms.machinelearning;

import java.util.HashMap;
import java.util.Map;

/**
 * Multinomial Naive Bayes classifier.
 *
 * <p>Suited to discrete, count-based features (e.g. word frequencies in text
 * classification). Class priors and feature likelihoods are estimated from
 * training data with Laplace (add-alpha) smoothing to avoid zero
 * probabilities for unseen feature/class combinations. Predictions are made
 * by comparing summed log-probabilities across classes, which avoids the
 * numerical underflow that repeated multiplication of small probabilities
 * would cause.
 *
 * <p>Reference: <a href="https://en.wikipedia.org/wiki/Naive_Bayes_classifier">
 * Naive Bayes classifier</a>
 *
 * @author Vraj Prajapati(Rosander0)
 */
public final class MultinomialNaiveBayesClassifier {

    private final double alpha;
    private final Map<Integer, Double> logPriors;
    private final Map<Integer, double[]> logLikelihoods;
    private int numFeatures;

    /**
     * Constructs a classifier with the given Laplace smoothing parameter.
     *
     * @param alpha smoothing constant; must be greater than 0. A value of 1.0
     *              corresponds to standard Laplace smoothing.
     */
    public MultinomialNaiveBayesClassifier(double alpha) {
        if (alpha <= 0) {
            throw new IllegalArgumentException("alpha must be greater than 0");
        }
        this.alpha = alpha;
        this.logPriors = new HashMap<>();
        this.logLikelihoods = new HashMap<>();
    }

    /** Constructs a classifier using the standard Laplace smoothing constant of 1.0. */
    public MultinomialNaiveBayesClassifier() {
        this(1.0);
    }

    /**
     * Fits the classifier on the given feature matrix and labels.
     *
     * @param features training samples, each row a vector of non-negative
     *                 feature counts
     * @param labels   class label for each row of {@code features}
     */
    public void fit(double[][] features, int[] labels) {
        if (features.length == 0 || features.length != labels.length) {
            throw new IllegalArgumentException("features and labels must be non-empty and of equal length");
        }
        logPriors.clear();
        logLikelihoods.clear();
        numFeatures = features[0].length;

        Map<Integer, Integer> classCounts = new HashMap<>();
        Map<Integer, double[]> featureSums = new HashMap<>();
        Map<Integer, Double> totalFeatureCount = new HashMap<>();

        for (int i = 0; i < features.length; i++) {
            int label = labels[i];
            classCounts.merge(label, 1, Integer::sum);
            double[] sums = featureSums.computeIfAbsent(label, k -> new double[numFeatures]);
            double total = totalFeatureCount.getOrDefault(label, 0.0);
            for (int j = 0; j < numFeatures; j++) {
                sums[j] += features[i][j];
                total += features[i][j];
            }
            totalFeatureCount.put(label, total);
        }

        int totalSamples = features.length;
        for (Map.Entry<Integer, double[]> entry : featureSums.entrySet()) {
            int label = entry.getKey();
            double[] sums = entry.getValue();
            int count = classCounts.getOrDefault(label, 0);
            double total = totalFeatureCount.getOrDefault(label, 0.0);

            logPriors.put(label, Math.log((double) count / totalSamples));

            double denom = total + alpha * numFeatures;
            double[] logLikelihood = new double[numFeatures];
            for (int j = 0; j < numFeatures; j++) {
                logLikelihood[j] = Math.log((sums[j] + alpha) / denom);
            }
            logLikelihoods.put(label, logLikelihood);
        }
    }

    /**
     * Predicts the most likely class for a single sample.
     *
     * @param sample feature vector of non-negative counts
     * @return the predicted class label
     */
    public int predict(double[] sample) {
        if (logPriors.isEmpty()) {
            throw new IllegalStateException("classifier has not been fitted");
        }
        if (sample.length != numFeatures) {
            throw new IllegalArgumentException("sample length must match training feature count");
        }

        int bestLabel = -1;
        double bestScore = Double.NEGATIVE_INFINITY;

        for (Map.Entry<Integer, double[]> entry : logLikelihoods.entrySet()) {
            int label = entry.getKey();
            double[] logLikelihood = entry.getValue();
            double score = logPriors.getOrDefault(label, Double.NEGATIVE_INFINITY);
            for (int j = 0; j < numFeatures; j++) {
                score += sample[j] * logLikelihood[j];
            }
            if (score > bestScore) {
                bestScore = score;
                bestLabel = label;
            }
        }
        return bestLabel;
    }

    /**
     * Predicts class labels for a batch of samples.
     *
     * @param samples feature vectors of non-negative counts
     * @return predicted class label for each row of {@code samples}
     */
    public int[] predict(double[][] samples) {
        int[] predictions = new int[samples.length];
        for (int i = 0; i < samples.length; i++) {
            predictions[i] = predict(samples[i]);
        }
        return predictions;
    }
}

package com.thealgorithms.machinelearning;

/**
 * A binary Perceptron classifier.
 *
 * <p>The Perceptron is a single-layer neural network that learns a linear
 * decision boundary. It updates its weights whenever a training sample is
 * misclassified. Convergence is guaranteed for linearly separable data, but
 * training stops after the configured epoch limit for non-separable data.
 * Labels must be either {@code 0} or {@code 1}.
 *
 * <p>The prediction rule is {@code 1} when the weighted sum plus bias is
 * greater than or equal to zero, and {@code 0} otherwise. For a
 * misclassified sample, the update is {@code weight += learningRate * error *
 * feature} and {@code bias += learningRate * error}, where {@code error} is
 * the true label minus the prediction. Samples are visited one at a time, so
 * each prediction uses the parameters produced by the preceding updates of
 * the same epoch.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Perceptron">Perceptron</a>
 */
public final class Perceptron {
    private final double learningRate;
    private final int maxEpochs;
    private double[] weights;
    private double bias;
    private int epochsRun;
    private boolean converged;

    /**
     * Constructs a Perceptron with the given training hyperparameters.
     *
     * @param learningRate positive step size used for each update
     * @param maxEpochs positive maximum number of passes over the training data
     * @throws IllegalArgumentException if a hyperparameter is invalid
     */
    public Perceptron(double learningRate, int maxEpochs) {
        if (!Double.isFinite(learningRate) || learningRate <= 0.0) {
            throw new IllegalArgumentException("learningRate must be finite and greater than 0");
        }
        if (maxEpochs <= 0) {
            throw new IllegalArgumentException("maxEpochs must be greater than 0");
        }
        this.learningRate = learningRate;
        this.maxEpochs = maxEpochs;
    }

    /**
     * Fits the classifier using binary training labels.
     *
     * <p>Fitting resets the weights and bias to zero before training. The
     * method records whether an entire epoch completed without an update. A
     * large {@code learningRate} combined with large feature values can push
     * the parameters past the range of {@code double}; the classifier then
     * returns to its unfitted state instead of reporting predictions derived
     * from non-finite parameters.
     *
     * @param features training feature vectors
     * @param labels corresponding binary labels, each either {@code 0} or
     *                {@code 1}
     * @throws IllegalArgumentException if the training data is invalid
     * @throws ArithmeticException if training diverges and the learned
     *                             parameters stop being finite
     */
    public void fit(double[][] features, int[] labels) {
        validateTrainingData(features, labels);

        weights = new double[features[0].length];
        bias = 0.0;
        epochsRun = 0;
        converged = false;

        for (int epoch = 0; epoch < maxEpochs; epoch++) {
            boolean updated = false;

            for (int sampleIndex = 0; sampleIndex < features.length; sampleIndex++) {
                int prediction = rawPredict(features[sampleIndex]);
                int error = labels[sampleIndex] - prediction;

                if (error != 0) {
                    update(features[sampleIndex], error);
                    updated = true;
                }
            }

            epochsRun = epoch + 1;
            if (!updated) {
                converged = true;
                break;
            }
        }

        ensureParametersAreFinite();
    }

    /**
     * Predicts the binary label for one sample.
     *
     * @param sample feature vector to classify
     * @return {@code 0} or {@code 1}
     * @throws IllegalStateException if the classifier has not been fitted
     * @throws IllegalArgumentException if the sample is invalid
     */
    public int predict(double[] sample) {
        ensureFitted();
        validateSample(sample);
        return rawPredict(sample);
    }

    /**
     * Predicts binary labels for a batch of samples.
     *
     * @param samples feature vectors to classify
     * @return one prediction for each sample
     * @throws IllegalStateException if the classifier has not been fitted
     * @throws IllegalArgumentException if the batch or one of its samples is
     *                                  invalid
     */
    public int[] predict(double[][] samples) {
        ensureFitted();
        if (samples == null) {
            throw new IllegalArgumentException("samples cannot be null");
        }

        int[] predictions = new int[samples.length];
        for (int sampleIndex = 0; sampleIndex < samples.length; sampleIndex++) {
            predictions[sampleIndex] = predict(samples[sampleIndex]);
        }
        return predictions;
    }

    /**
     * Returns a defensive copy of the learned feature weights.
     *
     * @return learned weights in feature order
     * @throws IllegalStateException if the classifier has not been fitted
     */
    public double[] getWeights() {
        ensureFitted();
        return weights.clone();
    }

    /**
     * Returns the learned bias term.
     *
     * @return learned bias
     * @throws IllegalStateException if the classifier has not been fitted
     */
    public double getBias() {
        ensureFitted();
        return bias;
    }

    /**
     * Reports whether training completed with an update-free epoch.
     *
     * @return {@code true} if an epoch completed without an update
     * @throws IllegalStateException if the classifier has not been fitted
     */
    public boolean hasConverged() {
        ensureFitted();
        return converged;
    }

    /**
     * Returns the number of epochs performed by the last fit.
     *
     * @return number of completed epochs
     * @throws IllegalStateException if the classifier has not been fitted
     */
    public int getEpochsRun() {
        ensureFitted();
        return epochsRun;
    }

    private int rawPredict(double[] sample) {
        double weightedSum = bias;
        for (int featureIndex = 0; featureIndex < weights.length; featureIndex++) {
            weightedSum += weights[featureIndex] * sample[featureIndex];
        }
        return weightedSum >= 0.0 ? 1 : 0;
    }

    private void update(double[] sample, int error) {
        for (int featureIndex = 0; featureIndex < weights.length; featureIndex++) {
            weights[featureIndex] += learningRate * error * sample[featureIndex];
        }
        bias += learningRate * error;
    }

    private void ensureParametersAreFinite() {
        if (!Double.isFinite(bias) || !isFinite(weights)) {
            weights = null;
            throw new ArithmeticException("training diverged; try a smaller learningRate or scaled features");
        }
    }

    private void ensureFitted() {
        if (weights == null) {
            throw new IllegalStateException("classifier has not been fitted");
        }
    }

    private void validateTrainingData(double[][] features, int[] labels) {
        if (features == null || labels == null) {
            throw new IllegalArgumentException("features and labels cannot be null");
        }
        if (features.length == 0 || labels.length == 0) {
            throw new IllegalArgumentException("features and labels cannot be empty");
        }
        if (features.length != labels.length) {
            throw new IllegalArgumentException("features and labels must have the same length");
        }
        if (features[0] == null || features[0].length == 0) {
            throw new IllegalArgumentException("feature vectors cannot be null or empty");
        }

        int featureCount = features[0].length;
        for (int sampleIndex = 0; sampleIndex < features.length; sampleIndex++) {
            double[] sample = features[sampleIndex];
            if (sample == null) {
                throw new IllegalArgumentException("feature vectors cannot be null or empty");
            }
            if (sample.length != featureCount) {
                throw new IllegalArgumentException("all feature vectors must have the same dimension");
            }
            validateFiniteValues(sample);
            if (labels[sampleIndex] != 0 && labels[sampleIndex] != 1) {
                throw new IllegalArgumentException("labels must be either 0 or 1");
            }
        }
    }

    private void validateSample(double[] sample) {
        if (sample == null || sample.length != weights.length) {
            throw new IllegalArgumentException("sample must match the training feature dimension");
        }
        validateFiniteValues(sample);
    }

    private static void validateFiniteValues(double[] values) {
        if (!isFinite(values)) {
            throw new IllegalArgumentException("feature values must be finite");
        }
    }

    private static boolean isFinite(double[] values) {
        for (double value : values) {
            if (!Double.isFinite(value)) {
                return false;
            }
        }
        return true;
    }
}

package com.thealgorithms.maths;

public record ADTFraction(int numerator, int denominator) {
    /**
     * Initializes a newly created {@code ADTFraction} object so that it represents
     * a fraction with the {@code numerator} and {@code denominator} provided as arguments.
     *
     * @param numerator   The fraction numerator
     * @param denominator The fraction denominator
     */
    public ADTFraction {
        if (denominator == 0) {
            throw new IllegalArgumentException("Denominator cannot be 0");
        }
    }

    /**
     * Add two fractions.
     *
     * @param fraction the {@code ADTFraction} to add
     * @return A new {@code ADTFraction} containing the result of the operation
     */
    public ADTFraction plus(ADTFraction fraction) {
        var numerator = this.denominator * fraction.numerator + this.numerator * fraction.denominator;
        var denominator = this.denominator * fraction.denominator;
        return new ADTFraction(numerator, denominator);
    }

    /**
     * Multiply fraction by a number.
     *
     * @param number the number to multiply
     * @return A new {@code ADTFraction} containing the result of the operation
     */
    public ADTFraction times(int number) {
        return times(new ADTFraction(number, 1));
    }

    /**
     * Multiply two fractions.
     *
     * @param fraction the {@code ADTFraction} to multiply
     * @return A new {@code ADTFraction} containing the result of the operation
     */
    public ADTFraction times(ADTFraction fraction) {
        var numerator = this.numerator * fraction.numerator;
        var denominator = this.denominator * fraction.denominator;
        return new ADTFraction(numerator, denominator);
    }

    /**
     * Generates the reciprocal of the fraction.
     *
     * @return A new {@code ADTFraction} with the {@code numerator} and {@code denominator} switched
     */
    public ADTFraction reciprocal() {
        return new ADTFraction(this.denominator, this.numerator);
    }

    /**
     * Calculates the result of the fraction.
     *
     * @return The numerical result of the division between {@code numerator} and {@code
     *     denominator}
     */
    public float value() {
        return (float) this.numerator / this.denominator;
    }

    /**
     * Returns a string representation of this {@code ADTFraction} in the format
     * {@code numerator}/{@code denominator}.
     *
     * @return A string representation of this {@code ADTFraction}
     */
    @Override
    public String toString() {
        return String.format("%d/%d", this.numerator, this.denominator);
    }
}

package com.thealgorithms.maths;

public final class AbsoluteMax {
    private AbsoluteMax() {
    }

    /**
     * Finds the absolute maximum value among the given numbers.
     *
     * @param numbers The numbers to compare.
     * @return The absolute maximum value.
     * @throws IllegalArgumentException If the input array is empty or null.
     */
    public static int getMaxValue(int... numbers) {
        if (numbers == null || numbers.length == 0) {
            throw new IllegalArgumentException("Numbers array cannot be empty or null");
        }
        int absMax = numbers[0];
        for (int i = 1; i < numbers.length; i++) {
            if (Math.abs(numbers[i]) > Math.abs(absMax) || (Math.abs(numbers[i]) == Math.abs(absMax) && numbers[i] > absMax)) {
                absMax = numbers[i];
            }
        }
        return absMax;
    }
}

package com.thealgorithms.maths;

public final class AbsoluteMin {
    private AbsoluteMin() {
    }

    /**
     * Compares the numbers given as arguments to get the absolute min value.
     *
     * @param numbers The numbers to compare
     * @return The absolute min value
     */
    public static int getMinValue(int... numbers) {
        if (numbers == null || numbers.length == 0) {
            throw new IllegalArgumentException("Numbers array cannot be empty or null");
        }

        long absMin = numbers[0];
        for (int i = 1; i < numbers.length; i++) {
            long current = numbers[i];
            if (Math.abs(current) < Math.abs(absMin) || (Math.abs(current) == Math.abs(absMin) && current < absMin)) {
                absMin = current;
            }
        }
        return (int) absMin;
    }
}

