package com.thealgorithms.maths;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Utility class to calculate the mode(s) of an array of integers.
 * <p>
 * The mode of an array is the integer value(s) that occur most frequently.
 * If multiple values have the same highest frequency, all such values are returned.
 * </p>
 */
public final class Mode {
    private Mode() {
    }

    /**
     * Computes the mode(s) of the specified array of integers.
     * <p>
     * If the input array is empty, this method returns {@code null}.
     * If multiple numbers share the highest frequency, all are returned in the result array.
     * </p>
     *
     * @param numbers an array of integers to analyze
     * @return an array containing the mode(s) of the input array, or {@code null} if the input is empty
     */
    public static int[] mode(final int[] numbers) {
        if (numbers.length == 0) {
            return null;
        }

        Map<Integer, Integer> count = new HashMap<>();

        for (int num : numbers) {
            count.put(num, count.getOrDefault(num, 0) + 1);
        }

        int max = Collections.max(count.values());
        List<Integer> modes = new ArrayList<>();

        for (final var entry : count.entrySet()) {
            if (entry.getValue() == max) {
                modes.add(entry.getKey());
            }
        }
        return modes.stream().mapToInt(Integer::intValue).toArray();
    }
}

package com.thealgorithms.maths;

import java.util.HashSet;
import java.util.Set;

/**
 * In numerical analysis, Neville's algorithm is an algorithm used for
 * polynomial interpolation. Given n+1 points, there is a unique polynomial of
 * degree at most n that passes through all the points. Neville's algorithm
 * computes the value of this polynomial at a given point.
 *
 * <p>
 * Wikipedia: https://en.wikipedia.org/wiki/Neville%27s_algorithm
 *
 * @author Mitrajit Ghorui(KeyKyrios)
 */
public final class Neville {

    private Neville() {
    }

    /**
     * Evaluates the polynomial that passes through the given points at a
     * specific x-coordinate.
     *
     * @param x The x-coordinates of the points. Must be the same length as y.
     * @param y The y-coordinates of the points. Must be the same length as x.
     * @param target The x-coordinate at which to evaluate the polynomial.
     * @return The interpolated y-value at the target x-coordinate.
     * @throws IllegalArgumentException if the lengths of x and y arrays are
     * different, if the arrays are empty, or if x-coordinates are not unique.
     */
    public static double interpolate(double[] x, double[] y, double target) {
        if (x.length != y.length) {
            throw new IllegalArgumentException("x and y arrays must have the same length.");
        }
        if (x.length == 0) {
            throw new IllegalArgumentException("Input arrays cannot be empty.");
        }

        // Check for duplicate x-coordinates to prevent division by zero
        Set<Double> seenX = new HashSet<>();
        for (double val : x) {
            if (!seenX.add(val)) {
                throw new IllegalArgumentException("Input x-coordinates must be unique.");
            }
        }

        int n = x.length;
        double[] p = new double[n];
        System.arraycopy(y, 0, p, 0, n); // Initialize p with y values

        for (int k = 1; k < n; k++) {
            for (int i = 0; i < n - k; i++) {
                p[i] = ((target - x[i + k]) * p[i] + (x[i] - target) * p[i + 1]) / (x[i] - x[i + k]);
            }
        }

        return p[0];
    }
}

package com.thealgorithms.maths;

/**
 * Find the 2 elements which are non-repeating in an array
 * Reason to use bitwise operator: It makes our program faster as we are operating on bits and not
 * on actual numbers.
 *
 * Explanation of the code:
 * Let us assume we have an array [1, 2, 1, 2, 3, 4]
 * Property of XOR: num ^ num = 0.
 * If we XOR all the elements of the array, we will be left with 3 ^ 4 as 1 ^ 1
 * and 2 ^ 2 would give 0. Our task is to find num1 and num2 from the result of 3 ^ 4 = 7.
 * We need to find the two's complement of 7 and find the rightmost set bit, i.e., (num & (-num)).
 * Two's complement of 7 is 001, and hence res = 1. There can be 2 options when we Bitwise AND this res
 * with all the elements in our array:
 * 1. The result will be a non-zero number.
 * 2. The result will be 0.
 * In the first case, we will XOR our element with the first number (which is initially 0).
 * In the second case, we will XOR our element with the second number (which is initially 0).
 * This is how we will get non-repeating elements with the help of bitwise operators.
 */
public final class NonRepeatingElement {
    private NonRepeatingElement() {
    }

    /**
     * Finds the two non-repeating elements in the array.
     *
     * @param arr The input array containing exactly two non-repeating elements and all other elements repeating.
     * @return An array containing the two non-repeating elements.
     * @throws IllegalArgumentException if the input array length is odd.
     */
    public static int[] findNonRepeatingElements(int[] arr) {
        if (arr.length % 2 != 0) {
            throw new IllegalArgumentException("Array should contain an even number of elements");
        }

        int xorResult = 0;

        // Find XOR of all elements
        for (int num : arr) {
            xorResult ^= num;
        }

        // Find the rightmost set bit
        int rightmostSetBit = xorResult & (-xorResult);
        int num1 = 0;
        int num2 = 0;

        // Divide the elements into two groups and XOR them
        for (int num : arr) {
            if ((num & rightmostSetBit) != 0) {
                num1 ^= num;
            } else {
                num2 ^= num;
            }
        }

        return new int[] {num1, num2};
    }
}

package com.thealgorithms.maths;

import static java.util.Collections.singletonList;

import java.util.ArrayList;
import java.util.Map;
import org.apache.commons.lang3.tuple.MutablePair;

/**
 * @brief class computing the n-th ugly number (when they are sorted)
 * @details the ugly numbers with base [2, 3, 5] are all numbers of the form 2^a*3^b^5^c,
 *   where the exponents a, b, c are non-negative integers.
 *   Some properties of ugly numbers:
 *     - base [2, 3, 5] ugly numbers are the 5-smooth numbers, cf. https://oeis.org/A051037
 *     - base [2, 3, 5, 7] ugly numbers are 7-smooth numbers, cf. https://oeis.org/A002473
 *     - base [2] ugly numbers are the non-negative powers of 2,
 *     - the base [2, 3, 5] ugly numbers are the same as base [5, 6, 2, 3, 5] ugly numbers
 */
public class NthUglyNumber {
    private ArrayList<Long> uglyNumbers = new ArrayList<>(singletonList(1L));
    private ArrayList<MutablePair<Integer, Integer>> positions = new ArrayList<>();

    /**
     * @brief initialized the object allowing to compute ugly numbers with given base
     * @param baseNumbers the given base of ugly numbers
     * @exception IllegalArgumentException baseNumber is empty
     */
    NthUglyNumber(final int[] baseNumbers) {
        if (baseNumbers.length == 0) {
            throw new IllegalArgumentException("baseNumbers must be non-empty.");
        }

        for (final var baseNumber : baseNumbers) {
            this.positions.add(MutablePair.of(baseNumber, 0));
        }
    }

    /**
     * @param n the zero-based-index of the queried ugly number
     * @exception IllegalArgumentException n is negative
     * @return the n-th ugly number (starting from index 0)
     */
    public Long get(final int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative.");
        }

        while (uglyNumbers.size() <= n) {
            addUglyNumber();
        }

        return uglyNumbers.get(n);
    }

    private void addUglyNumber() {
        uglyNumbers.add(computeMinimalCandidate());
        updatePositions();
    }

    private void updatePositions() {
        final var lastUglyNumber = uglyNumbers.get(uglyNumbers.size() - 1);
        for (var entry : positions) {
            if (computeCandidate(entry) == lastUglyNumber) {
                entry.setValue(entry.getValue() + 1);
            }
        }
    }

    private long computeCandidate(final Map.Entry<Integer, Integer> entry) {
        return entry.getKey() * uglyNumbers.get(entry.getValue());
    }

    private long computeMinimalCandidate() {
        long res = Long.MAX_VALUE;
        for (final var entry : positions) {
            res = Math.min(res, computeCandidate(entry));
        }
        return res;
    }
}

