/**
 * Find the number of digits in a number.
 */
public final class NumberOfDigits {
    private NumberOfDigits() {
    }
    /**
     * Find the number of digits in a number.
     *
     * @param number number to find
     * @return number of digits of given number
     */
    public static int numberOfDigits(int number) {
        int digits = 0;
        do {
            digits++;
            number /= 10;
        } while (number != 0);
        return digits;
    }

    /**
     * Find the number of digits in a number fast version.
     *
     * @param number number to find
     * @return number of digits of given number
     */
    public static int numberOfDigitsFast(int number) {
        return number == 0 ? 1 : (int) Math.floor(Math.log10(Math.abs(number)) + 1);
    }

    /**
     * Find the number of digits in a number faster version.
     *
     * @param number number to find
     * @return number of digits of given number
     */
    public static int numberOfDigitsFaster(int number) {
        return number < 0 ? (-number + "").length() : (number + "").length();
    }

    /**
     * Find the number of digits in a number using recursion.
     *
     * @param number number to find
     * @return number of digits of given number
     */
    public static int numberOfDigitsRecursion(int number) {
        return number / 10 == 0 ? 1 : 1 + numberOfDigitsRecursion(number / 10);
    }
}

package com.thealgorithms.maths;

/**
 * A utility class for calculating the persistence of a number.
 *
 * <p>This class provides methods to calculate:
 * <ul>
 *   <li>Multiplicative persistence: The number of steps required to reduce a number to a single digit by multiplying its digits.</li>
 *   <li>Additive persistence: The number of steps required to reduce a number to a single digit by summing its digits.</li>
 * </ul>
 *
 * <p>This class is final and cannot be instantiated.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Persistence_of_a_number">Wikipedia: Persistence of a number</a>
 */
public final class NumberPersistence {

    // Private constructor to prevent instantiation
    private NumberPersistence() {
    }

    /**
     * Calculates the multiplicative persistence of a given number.
     *
     * <p>Multiplicative persistence is the number of steps required to reduce a number to a single digit
     * by multiplying its digits repeatedly.
     *
     * @param num the number to calculate persistence for; must be non-negative
     * @return the multiplicative persistence of the number
     * @throws IllegalArgumentException if the input number is negative
     */
    public static int multiplicativePersistence(int num) {
        if (num < 0) {
            throw new IllegalArgumentException("multiplicativePersistence() does not accept negative values");
        }

        int steps = 0;
        while (num >= 10) {
            int product = 1;
            int temp = num;
            while (temp > 0) {
                product *= temp % 10;
                temp /= 10;
            }
            num = product;
            steps++;
        }
        return steps;
    }

    /**
     * Calculates the additive persistence of a given number.
     *
     * <p>Additive persistence is the number of steps required to reduce a number to a single digit
     * by summing its digits repeatedly.
     *
     * @param num the number to calculate persistence for; must be non-negative
     * @return the additive persistence of the number
     * @throws IllegalArgumentException if the input number is negative
     */
    public static int additivePersistence(int num) {
        if (num < 0) {
            throw new IllegalArgumentException("additivePersistence() does not accept negative values");
        }

        int steps = 0;
        while (num >= 10) {
            int sum = 0;
            int temp = num;
            while (temp > 0) {
                sum += temp % 10;
                temp /= 10;
            }
            num = sum;
            steps++;
        }
        return steps;
    }
}

package com.thealgorithms.maths;

/**
 * The Padovan Sequence is a sequence of integers defined by the recurrence relation:
 * P(n) = P(n-2) + P(n-3) with initial values P(0) = P(1) = P(2) = 1.
 * Example: 1, 1, 1, 2, 2, 3, 4, 5, 7, 9, 12, 16, 21, 28, 37...
 *
 * @see <a href="https://en.wikipedia.org/wiki/Padovan_sequence">
 *     Wikipedia: Padovan Sequence</a>
 * @author Vraj Prajapati (@Rosander0)
 */
public final class PadovanSequence {

    private PadovanSequence() {
        // Utility class
    }

    /**
     * Calculates the nth term of the Padovan Sequence.
     *
     * @param n the index of the sequence (must be non-negative)
     * @return the nth term of the Padovan Sequence
     */
    public static long padovan(final int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input must be non-negative. Received: " + n);
        }
        if (n <= 2) {
            return 1;
        }
        long a = 1;
        long b = 1;
        long c = 1;
        long result = 0;
        for (int i = 3; i <= n; i++) {
            result = a + b;
            a = b;
            b = c;
            c = result;
        }
        return result;
    }
}

