     *
     * @param number Integer value which is to be checked
     * @return false when number has repeated prime factors
     *         true when number has non repeated prime factors
     * @throws IllegalArgumentException when number is negative or zero
     */
    public static boolean isSquareFreeInteger(int number) {

        if (number <= 0) {
            // throw exception when number is less than or is zero
            throw new IllegalArgumentException("Number must be greater than zero.");
        }

        // Store prime factors of number which is passed as argument
        // in a list
        List<Integer> primeFactorsList = PrimeFactorization.pfactors(number);

        // Create set from list of prime factors of integer number
        // if size of list and set is equal then the argument passed to this method is square free
        // if size of list and set is not equal then the argument passed to this method is not
        // square free
        return primeFactorsList.size() == new HashSet<>(primeFactorsList).size();
    }
}

package com.thealgorithms.maths;

/*
 * Java program for Pronic Number
 * Pronic Number: A number n is a pronic number if
 * it is equal to product of two consecutive numbers m and m+1.
 * Wikipedia: https://en.wikipedia.org/wiki/Pronic_number
 *
 * Author: Akshay Dubey (https://github.com/itsAkshayDubey)
 *
 * */

public final class PronicNumber {
    private PronicNumber() {
    }

    /**
     * This method checks if the given number is pronic number or non-pronic number
     *
     * @param inputNumber Integer value which is to be checked if is a pronic number or not
     * @return true if input number is a pronic number, false otherwise
     */
    static boolean isPronic(int inputNumber) {
        if (inputNumber == 0) {
            return true;
        }
        // Iterating from 0 to input_number
        for (int i = 0; i <= inputNumber; i++) {
            // Checking if product of i and (i+1) is equals input_number
            if (i * (i + 1) == inputNumber && i != inputNumber) {
                // return true if product of i and (i+1) is equals input_number
                return true;
            }
        }

        // return false if product of i and (i+1) for all values from 0 to input_number is not
        // equals input_number
        return false;
    }

    /**
     * This method checks if the given number is pronic number or non-pronic number using square root of number for finding divisors
     *
     * @param number Integer value which is to be checked if is a pronic number or not
     * @return true if input number is a pronic number, false otherwise
     */
    public static boolean isPronicNumber(int number) {
        int squareRoot = (int) Math.sqrt(number); // finding just smaller divisor of the number than its square root.
        return squareRoot * (squareRoot + 1) == number;
    }
}

package com.thealgorithms.maths;

/**
 * Utility class to check if three integers form a Pythagorean triple.
 * A Pythagorean triple consists of three positive integers a, b, and c,
 * such that a² + b² = c².
 *
 * Common examples:
 * - (3, 4, 5)
 * - (5, 12, 13)
 *
 * Reference: https://en.wikipedia.org/wiki/Pythagorean_triple
 */
public final class PythagoreanTriple {

    private PythagoreanTriple() {
    }

    /**
     * Checks whether three integers form a Pythagorean triple.
     * The order of parameters does not matter.
     *
     * @param a one side length
     * @param b another side length
     * @param c another side length
     * @return {@code true} if (a, b, c) can form a Pythagorean triple, otherwise {@code false}
     */
    public static boolean isPythagTriple(int a, int b, int c) {
        if (a <= 0 || b <= 0 || c <= 0) {
            return false;
        }

        // Sort the sides so the largest is treated as hypotenuse
        int[] sides = {a, b, c};
        java.util.Arrays.sort(sides);

        int x = sides[0];
        int y = sides[1];
        int hypotenuse = sides[2];

        return x * x + y * y == hypotenuse * hypotenuse;
    }
}

