package com.thealgorithms.maths;

/**
 * Implementation of Lagrange's Four Square Theorem
 * Find minimum number of perfect squares that sum to given number
 *
 * @see <a href="https://en.wikipedia.org/wiki/Lagrange%27s_four-square_theorem">Lagrange's Four Square Theorem</a>
 */
public final class SumOfSquares {

    private SumOfSquares() {
        // Utility class
    }

    /**
     * Find minimum number of perfect squares that sum to n
     *
     * @param n the target number (must be non-negative)
     * @return minimum number of squares needed
     * @throws IllegalArgumentException if n is negative
     */
    public static int minSquares(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input must be non-negative");
        }

        if (isPerfectSquare(n)) {
            return 1;
        }

        for (int i = 1; i * i <= n; i++) {
            int remaining = n - i * i;
            if (isPerfectSquare(remaining)) {
                return 2;
            }
        }

        // Legendre's three-square theorem
        int temp = n;
        while (temp % 4 == 0) {
            temp /= 4;
        }
        if (temp % 8 == 7) {
            return 4;
        }

        return 3;
    }

    private static boolean isPerfectSquare(int n) {
        if (n < 0) {
            return false;
        }
        int root = (int) Math.sqrt(n);
        return root * root == n;
    }
}

package com.thealgorithms.maths;

public class SumWithoutArithmeticOperators {

    /**
     * Calculate the sum of two numbers a and b without using any arithmetic operators (+, -, *, /).
     * All the integers associated are unsigned 32-bit integers
     *https://stackoverflow.com/questions/365522/what-is-the-best-way-to-add-two-numbers-without-using-the-operator
     *@param a - It is the first number
     *@param b - It is the second number
     *@return returns an integer which is the sum of the first and second number
     */

    public int getSum(int a, int b) {
        if (b == 0) {
            return a;
        }
        int sum = a ^ b;
        int carry = (a & b) << 1;
        return getSum(sum, carry);
    }
}

package com.thealgorithms.maths;
/*
 * Java program to find 'twin prime' of a prime number
 * Twin Prime: Twin prime of a number n is (n+2)
 * if and only if n & (n+2) are prime.
 * Wikipedia: https://en.wikipedia.org/wiki/Twin_prime
 *
 * Author: Akshay Dubey (https://github.com/itsAkshayDubey)
 *
 * */

import com.thealgorithms.maths.Prime.PrimeCheck;

public final class TwinPrime {
    private TwinPrime() {
    }

    /**
     * This method returns twin prime of the integer value passed as argument
     *
     * @param inputNumber Integer value of which twin prime is to be found
     * @return (number + 2) if number and (number + 2) are prime, -1 otherwise
     */
    static int getTwinPrime(int inputNumber) {

        // if inputNumber and (inputNumber + 2) are both prime
        // then return (inputNumber + 2) as a result
        if (PrimeCheck.isPrime(inputNumber) && PrimeCheck.isPrime(inputNumber + 2)) {
            return inputNumber + 2;
        }
        // if any one from inputNumber and (inputNumber + 2) or if both of them are not prime
        // then return -1 as a result
        return -1;
    }
}

package com.thealgorithms.maths;

/**
 * A positive integer is considered uniform if all
 * of its digits are equal. For example, 222 is uniform,
 * while 223 is not.
 * Given two positive integers a and b, determine the
 * number of uniform integers between a and b.
 */
public final class UniformNumbers {
    // Private constructor to prevent instantiation of the utility class
    private UniformNumbers() {
        // Prevent instantiation
    }
    /**
     * This function will find the number of uniform numbers
     * from 1 to num
     * @param num upper limit to find the uniform numbers
     * @return the count of uniform numbers between 1 and num
     */
    public static int uniformNumbers(int num) {
        String numStr = Integer.toString(num);
        int uniformCount = (numStr.length() - 1) * 9;
        int finalUniform = Integer.parseInt(String.valueOf(numStr.charAt(0)).repeat(numStr.length()));

        if (finalUniform <= num) {
            uniformCount += Integer.parseInt(String.valueOf(numStr.charAt(0)));
        } else {
            uniformCount += Integer.parseInt(String.valueOf(numStr.charAt(0))) - 1;
        }

        return uniformCount;
    }
    /**
     * This function will calculate the number of uniform numbers
     * between a and b
     * @param a lower bound of range
     * @param b upper bound of range
     * @return  the count of uniform numbers between a and b
     */
    public static int countUniformIntegers(int a, int b) {
        if (b > a && b > 0 && a > 0) {
            return uniformNumbers(b) - uniformNumbers(a - 1);
        } else if (b == a) {
            return 1;
        } else {
            return 0;
        }
    }
}

package com.thealgorithms.maths;

import java.util.ArrayList;

/**
 * In number theory, a vampire number (or true vampire number) is a composite
 * natural number with an even number of digits, that can be factored into two
 * natural numbers each with half as many digits as the original number and not
 * both with trailing zeroes, where the two factors contain precisely all the
 * digits of the original number, in any order, counting multiplicity. The first
 * vampire number is 1260 = 21 × 60.
 *
 * @see <a href='https://en.wikipedia.org/wiki/Vampire_number'>Vampire number on Wikipedia</a>
 */
public final class VampireNumber {
    // Forbid instantiation.
    private VampireNumber() {
    }

    static boolean isVampireNumber(int a, int b, boolean ignorePseudoVampireNumbers) {
        // Pseudo vampire numbers don't have to be of n/2 digits. E.g., 126 = 6 x 21 is such a number.
        if (ignorePseudoVampireNumbers && String.valueOf(a).length() != String.valueOf(b).length()) {
            return false;
        }

        String mulDigits = splitIntoSortedDigits(a * b);
        String factorDigits = splitIntoSortedDigits(a, b);

        return mulDigits.equals(factorDigits);
    }

    // Method to split a pair of numbers to digits and sort them in the ascending order.
    static String splitIntoSortedDigits(int... nums) {
        // Collect all digits in a list.
        ArrayList<Integer> digits = new ArrayList<>();
        for (int num : nums) {
            while (num > 0) {
                digits.add(num % 10);
                num /= 10;
            }
        }

        // Sort all digits and convert to String.
        StringBuilder res = new StringBuilder();
        digits.stream().sorted().forEach(res::append);
        return res.toString();
    }
}

package com.thealgorithms.maths;

/**
 * @file
 *
 * @brief Calculates the [Cross
 * Product](https://en.wikipedia.org/wiki/Cross_product) and the magnitude of
 * two mathematical 3D vectors.
 *
 *
 * @details Cross Product of two vectors gives a vector. Direction Ratios of a
 * vector are the numeric parts of the given vector. They are the tree parts of
 * the vector which determine the magnitude (value) of the vector. The method of
 * finding a cross product is the same as finding the determinant of an order 3
 * matrix consisting of the first row with unit vectors of magnitude 1, the
 * second row with the direction ratios of the first vector and the third row
 * with the direction ratios of the second vector. The magnitude of a vector is
 * its value expressed as a number. Let the direction ratios of the first
 * vector, P be: a, b, c Let the direction ratios of the second vector, Q be: x,
 * y, z Therefore the calculation for the cross product can be arranged as:
 *
 * ``` P x Q: 1	1	1 a	b	c x	y	z ```
 *
 * The direction ratios (DR) are calculated as follows: 1st DR, J: (b * z) - (c
 * * y) 2nd DR, A: -((a * z) - (c * x)) 3rd DR, N: (a * y) - (b * x)
 *
 * Therefore, the direction ratios of the cross product are: J, A, N The
 * following Java Program calculates the direction ratios of the cross products
 * of two vector. The program uses a function, cross() for doing so. The
 * direction ratios for the first and the second vector has to be passed one by
 * one separated by a space character.
 *
 * Magnitude of a vector is the square root of the sum of the squares of the
 * direction ratios.
 *
 *
 * For maintaining filename consistency, Vector class has been termed as
 * VectorCrossProduct
 *
 * @author [Syed](https://github.com/roeticvampire)
 */
public class VectorCrossProduct {

    int x;
    int y;
    int z;

    // Default constructor, initialises all three Direction Ratios to 0
    VectorCrossProduct() {
        x = 0;
        y = 0;
        z = 0;
    }

    /**
     * constructor, initialises Vector with given Direction Ratios
     *
     * @param vectorX set to x
     * @param vectorY set to y
     * @param vectorZ set to z
     */
    VectorCrossProduct(int vectorX, int vectorY, int vectorZ) {
        x = vectorX;
        y = vectorY;
        z = vectorZ;
    }

    /**
     * Returns the magnitude of the vector
     *
     * @return double
     */
    double magnitude() {
        return Math.sqrt(x * x + y * y + z * z);
    }

    /**
     * Returns the dot product of the current vector with a given vector
     *
     * @param b: the second vector
     * @return int: the dot product
     */
    int dotProduct(VectorCrossProduct b) {
        return x * b.x + y * b.y + z * b.z;
    }

    /**
     * Returns the cross product of the current vector with a given vector
     *
     * @param b: the second vector
     * @return vectorCrossProduct: the cross product
     */
    VectorCrossProduct crossProduct(VectorCrossProduct b) {
        VectorCrossProduct product = new VectorCrossProduct();
        product.x = (y * b.z) - (z * b.y);
        product.y = -((x * b.z) - (z * b.x));
        product.z = (x * b.y) - (y * b.x);
        return product;
    }

    /**
     * Display the Vector
     */
    void displayVector() {
        System.out.println("x : " + x + "\ty : " + y + "\tz : " + z);
    }

    public static void main(String[] args) {
        test();
    }

    static void test() {
        // Create two vectors
        VectorCrossProduct a = new VectorCrossProduct(1, -2, 3);
        VectorCrossProduct b = new VectorCrossProduct(2, 0, 3);

        // Determine cross product
        VectorCrossProduct crossProd = a.crossProduct(b);
        crossProd.displayVector();

        // Determine dot product
        int dotProd = a.dotProduct(b);
        System.out.println("Dot Product of a and b: " + dotProd);
    }
}

package com.thealgorithms.maths;

/* Calculate the volume of various shapes.*/
public final class Volume {
    private Volume() {
    }

    /**
     * Calculate the volume of a cube.
     *
     * @param sideLength length of the given cube's sides
     * @return volume of the given cube
     */
    public static double volumeCube(double sideLength) {
        return sideLength * sideLength * sideLength;
    }

    /**
     * Calculate the volume of a cuboid.
     *
     * @param width  width of given cuboid
     * @param height height of given cuboid
     * @param length length of given cuboid
     * @return volume of given cuboid
     */
    public static double volumeCuboid(double width, double height, double length) {
        return width * height * length;
    }

    /**
     * Calculate the volume of a sphere.
     *
     * @param radius radius of given sphere
     * @return volume of given sphere
     */
    public static double volumeSphere(double radius) {
        return (4 * Math.PI * radius * radius * radius) / 3;
    }

    /**
     * Calculate volume of a cylinder
     *
     * @param radius radius of the given cylinder's floor
     * @param height height of the given cylinder
     * @return volume of given cylinder
     */
    public static double volumeCylinder(double radius, double height) {
        return Math.PI * radius * radius * height;
    }

    /**
     * Calculate the volume of a hemisphere.
     *
     * @param radius radius of given hemisphere
     * @return volume of given hemisphere
     */
    public static double volumeHemisphere(double radius) {
        return (2 * Math.PI * radius * radius * radius) / 3;
    }

    /**
     * Calculate the volume of a cone.
     *
     * @param radius radius of given cone
     * @param height of given cone
     * @return volume of given cone
     */
    public static double volumeCone(double radius, double height) {
        return (Math.PI * radius * radius * height) / 3;
    }

    /**
     * Calculate the volume of a prism.
     *
     * @param baseArea  area of the given prism's base
     * @param height of given prism
     * @return volume of given prism
     */
    public static double volumePrism(double baseArea, double height) {
        return baseArea * height;
    }

    /**
     * Calculate the volume of a pyramid.
     *
     * @param baseArea   of the given pyramid's base
     * @param height of given pyramid
     * @return volume of given pyramid
     */
    public static double volumePyramid(double baseArea, double height) {
        return (baseArea * height) / 3;
    }

    /**
     * Calculate the volume of a frustum of a cone.
     *
     * @param r1 radius of the top of the frustum
     * @param r2 radius of the bottom of the frustum
     * @param height height of the frustum
     * @return volume of the frustum
     */
    public static double volumeFrustumOfCone(double r1, double r2, double height) {
        return (Math.PI * height / 3) * (r1 * r1 + r2 * r2 + r1 * r2);
    }

    /**
     * Calculate the volume of a frustum of a pyramid.
     *
     * @param upperBaseArea area of the upper base
     * @param lowerBaseArea area of the lower base
     * @param height height of the frustum
     * @return volume of the frustum
     */
    public static double volumeFrustumOfPyramid(double upperBaseArea, double lowerBaseArea, double height) {
        return (upperBaseArea + lowerBaseArea + Math.sqrt(upperBaseArea * lowerBaseArea)) * height / 3;
    }

    /**
     * Calculate the volume of a torus.
     *
     * @param majorRadius major radius of a torus
     * @param minorRadius minor radius of a torus
     * @return volume of the torus
     */
    public static double volumeTorus(double majorRadius, double minorRadius) {
        return 2 * Math.PI * Math.PI * majorRadius * minorRadius * minorRadius;
    }

    /**
     * Calculate the volume of an ellipsoid.
     *
     * @param a first semi-axis of an ellipsoid
     * @param b second semi-axis of an ellipsoid
     * @param c third semi-axis of an ellipsoid
     * @return volume of the ellipsoid
     */
    public static double volumeEllipsoid(double a, double b, double c) {
        return (4 * Math.PI * a * b * c) / 3;
    }
}

package com.thealgorithms.maths;

import java.time.DateTimeException;
import java.time.LocalDate;
import java.util.Objects;

/**
 * A utility class for calculating the day of the week for a given date using Zeller's Congruence.
 *
 * <p>Zeller's Congruence is an algorithm devised by Christian Zeller in the 19th century to calculate
 * the day of the week for any Julian or Gregorian calendar date. The input date must be in the format
 * "MM-DD-YYYY" or "MM/DD/YYYY".
 *
 * <p>This class is final and cannot be instantiated.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Zeller%27s_congruence">Wikipedia: Zeller's Congruence</a>
 */
public final class ZellersCongruence {

    private static final String[] DAYS = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

    // Private constructor to prevent instantiation
    private ZellersCongruence() {
    }

    /**
     * Calculates the day of the week for a given date using Zeller's Congruence.
     *
     * <p>The algorithm works for both Julian and Gregorian calendar dates. The input date must be
     * in the format "MM-DD-YYYY" or "MM/DD/YYYY".
     *
     * @param input the date in the format "MM-DD-YYYY" or "MM/DD/YYYY"
     * @return a string indicating the day of the week for the given date
     * @throws IllegalArgumentException if the input format is invalid, the date is invalid,
     *                                  or the year is out of range
     */
    public static String calculateDay(String input) {
        if (input == null || input.length() != 10) {
            throw new IllegalArgumentException("Input date must be 10 characters long in the format MM-DD-YYYY or MM/DD/YYYY.");
        }

        int month = parsePart(input.substring(0, 2), 1, 12, "Month must be between 1 and 12.");
        char sep1 = input.charAt(2);
        validateSeparator(sep1);

        int day = parsePart(input.substring(3, 5), 1, 31, "Day must be between 1 and 31.");
        char sep2 = input.charAt(5);
        validateSeparator(sep2);

        int year = parsePart(input.substring(6, 10), 46, 8499, "Year must be between 46 and 8499.");

        try {
            Objects.requireNonNull(LocalDate.of(year, month, day));
        } catch (DateTimeException e) {
            throw new IllegalArgumentException("Invalid date.", e);
        }
        if (month <= 2) {
            year -= 1;
            month += 12;
        }

        int century = year / 100;
        int yearOfCentury = year % 100;
        int t = (int) (2.6 * month - 5.39);
        int u = century / 4;
        int v = yearOfCentury / 4;
        int f = (int) Math.round((day + yearOfCentury + t + u + v - 2 * century) % 7.0);

        int correctedDay = (f + 7) % 7;

        return "The date " + input + " falls on a " + DAYS[correctedDay] + ".";
    }

    /**
     * Parses a part of the date string and validates its range.
     *
     * @param part  the substring to parse
     * @param min   the minimum valid value
     * @param max   the maximum valid value
     * @param error the error message to throw if validation fails
     * @return the parsed integer value
     * @throws IllegalArgumentException if the part is not a valid number or is out of range
     */
    private static int parsePart(String part, int min, int max, String error) {
        try {
            int value = Integer.parseInt(part);
            if (value < min || value > max) {
                throw new IllegalArgumentException(error);
            }
            return value;
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Invalid numeric part: " + part, e);
        }
    }

    /**
     * Validates the separator character in the date string.
     *
     * @param sep the separator character
     * @throws IllegalArgumentException if the separator is not '-' or '/'
     */
    private static void validateSeparator(char sep) {
        if (sep != '-' && sep != '/') {
            throw new IllegalArgumentException("Date separator must be '-' or '/'.");
        }
    }
}

package com.thealgorithms.matrix;

/**
 * This class provides methods to compute the inverse of a square matrix
 * using Gaussian elimination. For more details, refer to:
 * https://en.wikipedia.org/wiki/Invertible_matrix
 */
public final class InverseOfMatrix {
    private InverseOfMatrix() {
    }

    public static double[][] invert(double[][] a) {
        int n = a.length;
        double[][] x = new double[n][n];
        double[][] b = new double[n][n];
        int[] index = new int[n];

        // Initialize the identity matrix
        for (int i = 0; i < n; ++i) {
            b[i][i] = 1;
        }

        // Perform Gaussian elimination
        gaussian(a, index);

        // Update matrix b with the ratios stored during elimination
        for (int i = 0; i < n - 1; ++i) {
            for (int j = i + 1; j < n; ++j) {
                for (int k = 0; k < n; ++k) {
                    b[index[j]][k] -= a[index[j]][i] * b[index[i]][k];
                }
            }
        }

        // Perform backward substitution to find the inverse
        for (int i = 0; i < n; ++i) {
            x[n - 1][i] = b[index[n - 1]][i] / a[index[n - 1]][n - 1];
            for (int j = n - 2; j >= 0; --j) {
                x[j][i] = b[index[j]][i];
                for (int k = j + 1; k < n; ++k) {
                    x[j][i] -= a[index[j]][k] * x[k][i];
                }
                x[j][i] /= a[index[j]][j];
            }
        }
        return x;
    }
    /**
     * Method to carry out the partial-pivoting Gaussian
     * elimination.  Here index[] stores pivoting order.
     **/
    private static void gaussian(double[][] a, int[] index) {
        int n = index.length;
        double[] c = new double[n];

        // Initialize the index array
        for (int i = 0; i < n; ++i) {
            index[i] = i;
        }

        // Find the rescaling factors for each row
        for (int i = 0; i < n; ++i) {
            double c1 = 0;
            for (int j = 0; j < n; ++j) {
                double c0 = Math.abs(a[i][j]);
                if (c0 > c1) {
                    c1 = c0;
                }
            }
            c[i] = c1;
        }

        // Perform pivoting
        for (int j = 0; j < n - 1; ++j) {
            double pi1 = 0;
            int k = j;
            for (int i = j; i < n; ++i) {
                double pi0 = Math.abs(a[index[i]][j]) / c[index[i]];
                if (pi0 > pi1) {
                    pi1 = pi0;
                    k = i;
                }
            }

            // Swap rows
            int temp = index[j];
            index[j] = index[k];
            index[k] = temp;

            for (int i = j + 1; i < n; ++i) {
                double pj = a[index[i]][j] / a[index[j]][j];

                // Record pivoting ratios below the diagonal
                a[index[i]][j] = pj;

                // Modify other elements accordingly
                for (int l = j + 1; l < n; ++l) {
                    a[index[i]][l] -= pj * a[index[j]][l];
                }
            }
        }
    }
}

package com.thealgorithms.matrix;

/**
 * LU Decomposition algorithm
 * --------------------------
 * Decomposes a square matrix a into a product of two matrices:
 * a = l * u
 * where:
 * - l is a lower triangular matrix with 1s on its diagonal
 * - u is an upper triangular matrix
 *
 * Reference:
 * https://en.wikipedia.org/wiki/lu_decomposition
 */
public final class LUDecomposition {

    private LUDecomposition() {
    }

    /**
     * A helper class to store both l and u matrices
     */
    public static class LU {
        double[][] l;
        double[][] u;

        LU(double[][] l, double[][] u) {
            this.l = l;
            this.u = u;
        }
    }

    /**
     * Performs LU Decomposition on a square matrix a
     *
     * @param a input square matrix
     * @return LU object containing l and u matrices
     */
    public static LU decompose(double[][] a) {
        int n = a.length;
        double[][] l = new double[n][n];
        double[][] u = new double[n][n];

        for (int i = 0; i < n; i++) {
            // upper triangular matrix
            for (int k = i; k < n; k++) {
                double sum = 0;
                for (int j = 0; j < i; j++) {
                    sum += l[i][j] * u[j][k];
                }
                u[i][k] = a[i][k] - sum;
            }

            // lower triangular matrix
            for (int k = i; k < n; k++) {
                if (i == k) {
                    l[i][i] = 1; // diagonal as 1
                } else {
                    double sum = 0;
                    for (int j = 0; j < i; j++) {
                        sum += l[k][j] * u[j][i];
                    }
                    l[k][i] = (a[k][i] - sum) / u[i][i];
                }
            }
        }

        return new LU(l, u);
    }

    /**
     * Utility function to print a matrix
     *
     * @param m matrix to print
     */
    public static void printMatrix(double[][] m) {
        for (double[] row : m) {
            System.out.print("[");
            for (int j = 0; j < row.length; j++) {
                System.out.printf("%7.3f", row[j]);
                if (j < row.length - 1) {
                    System.out.print(", ");
                }
            }
            System.out.println("]");
        }
    }
}

package com.thealgorithms.matrix;

/**
 * This class provides a method to perform matrix multiplication.
 *
 * <p>Matrix multiplication takes two 2D arrays (matrices) as input and
 * produces their product, following the mathematical definition of
 * matrix multiplication.
 *
 * <p>For more details:
 * https://www.geeksforgeeks.org/java/java-program-to-multiply-two-matrices-of-any-size/
 * https://en.wikipedia.org/wiki/Matrix_multiplication
 *
 * <p>Time Complexity: O(n^3) – where n is the dimension of the matrices
 * (assuming square matrices for simplicity).
 *
 * <p>Space Complexity: O(n^2) – for storing the result matrix.
 *
 *
 * @author Nishitha Wihala Pitigala
 *
 */

public final class MatrixMultiplication {
    private MatrixMultiplication() {
    }

    /**
     * Multiplies two matrices.
     *
     * @param matrixA the first matrix rowsA x colsA
     * @param matrixB the second matrix rowsB x colsB
     * @return the product of the two matrices rowsA x colsB
     * @throws IllegalArgumentException if the matrices cannot be multiplied
     */
    public static double[][] multiply(double[][] matrixA, double[][] matrixB) {
        // Check the input matrices are not null
        if (matrixA == null || matrixB == null) {
            throw new IllegalArgumentException("Input matrices cannot be null");
        }

        // Check for empty matrices
        if (matrixA.length == 0 || matrixB.length == 0 || matrixA[0].length == 0 || matrixB[0].length == 0) {
            throw new IllegalArgumentException("Input matrices must not be empty");
        }

        // Validate the matrix dimensions
        if (matrixA[0].length != matrixB.length) {
            throw new IllegalArgumentException("Matrices cannot be multiplied: incompatible dimensions.");
        }

        int rowsA = matrixA.length;
        int colsA = matrixA[0].length;
        int colsB = matrixB[0].length;

        // Initialize the result matrix with zeros
        double[][] result = new double[rowsA][colsB];

        // Perform matrix multiplication
        for (int i = 0; i < rowsA; i++) {
            for (int j = 0; j < colsB; j++) {
                for (int k = 0; k < colsA; k++) {
                    result[i][j] += matrixA[i][k] * matrixB[k][j];
                }
            }
        }
        return result;
    }
}

package com.thealgorithms.matrix;

import static com.thealgorithms.matrix.utils.MatrixUtil.validateInputMatrix;

/**
 * This class provides a method to compute the rank of a matrix.
 * In linear algebra, the rank of a matrix is the maximum number of linearly independent rows or columns in the matrix.
 * For example, consider the following 3x3 matrix:
 * 1 2 3
 * 2 4 6
 * 3 6 9
 * Despite having 3 rows and 3 columns, this matrix only has a rank of 1 because all rows (and columns) are multiples of each other.
 * It's a fundamental concept that gives key insights into the structure of the matrix.
 * It's important to note that the rank is not only defined for square matrices but for any m x n matrix.
 *
 * @author Anup Omkar
 */
public final class MatrixRank {

    private MatrixRank() {
    }

    private static final double EPSILON = 1e-10;

    /**
     * @brief Computes the rank of the input matrix
     *
     * @param matrix The input matrix
     * @return The rank of the input matrix
     */
    public static int computeRank(double[][] matrix) {
        validateInputMatrix(matrix);

        int numRows = matrix.length;
        int numColumns = matrix[0].length;
        int rank = 0;

        boolean[] rowMarked = new boolean[numRows];

        double[][] matrixCopy = deepCopy(matrix);

        for (int colIndex = 0; colIndex < numColumns; ++colIndex) {
            int pivotRow = findPivotRow(matrixCopy, rowMarked, colIndex);
            if (pivotRow != numRows) {
                ++rank;
                rowMarked[pivotRow] = true;
                normalizePivotRow(matrixCopy, pivotRow, colIndex);
                eliminateRows(matrixCopy, pivotRow, colIndex);
            }
        }
        return rank;
    }

    private static boolean isZero(double value) {
        return Math.abs(value) < EPSILON;
    }

    private static double[][] deepCopy(double[][] matrix) {
        int numRows = matrix.length;
        int numColumns = matrix[0].length;
        double[][] matrixCopy = new double[numRows][numColumns];
        for (int rowIndex = 0; rowIndex < numRows; ++rowIndex) {
            System.arraycopy(matrix[rowIndex], 0, matrixCopy[rowIndex], 0, numColumns);
        }
        return matrixCopy;
    }

    /**
     * @brief The pivot row is the row in the matrix that is used to eliminate other rows and reduce the matrix to its row echelon form.
     * The pivot row is selected as the first row (from top to bottom) where the value in the current column (the pivot column) is not zero.
     * This row is then used to "eliminate" other rows, by subtracting multiples of the pivot row from them, so that all other entries in the pivot column become zero.
     * This process is repeated for each column, each time selecting a new pivot row, until the matrix is in row echelon form.
     * The number of pivot rows (rows with a leading entry, or pivot) then gives the rank of the matrix.
     *
     * @param matrix The input matrix
     * @param rowMarked An array indicating which rows have been marked
     * @param colIndex The column index
     * @return The pivot row index, or the number of rows if no suitable pivot row was found
     */
    private static int findPivotRow(double[][] matrix, boolean[] rowMarked, int colIndex) {
        int numRows = matrix.length;
        for (int pivotRow = 0; pivotRow < numRows; ++pivotRow) {
            if (!rowMarked[pivotRow] && !isZero(matrix[pivotRow][colIndex])) {
                return pivotRow;
            }
        }
        return numRows;
    }

    /**
     * @brief This method divides all values in the pivot row by the value in the given column.
     * This ensures that the pivot value itself will be 1, which simplifies further calculations.
     *
     * @param matrix The input matrix
     * @param pivotRow The pivot row index
     * @param colIndex The column index
     */
    private static void normalizePivotRow(double[][] matrix, int pivotRow, int colIndex) {
        int numColumns = matrix[0].length;
        for (int nextCol = colIndex + 1; nextCol < numColumns; ++nextCol) {
            matrix[pivotRow][nextCol] /= matrix[pivotRow][colIndex];
        }
    }

    /**
     * @brief This method subtracts multiples of the pivot row from all other rows,
     * so that all values in the given column of other rows will be zero.
     * This is a key step in reducing the matrix to row echelon form.
     *
     * @param matrix The input matrix
     * @param pivotRow The pivot row index
     * @param colIndex The column index
     */
    private static void eliminateRows(double[][] matrix, int pivotRow, int colIndex) {
        int numRows = matrix.length;
        int numColumns = matrix[0].length;
        for (int otherRow = 0; otherRow < numRows; ++otherRow) {
            if (otherRow != pivotRow && !isZero(matrix[otherRow][colIndex])) {
                for (int col2 = colIndex + 1; col2 < numColumns; ++col2) {
                    matrix[otherRow][col2] -= matrix[pivotRow][col2] * matrix[otherRow][colIndex];
                }
            }
        }
    }
}

