            Node start = null;
            Node prev = null;
            Node fresh;
            Node ptr;
            for (int i = 0; i < a.length; i++) {
                // New nodes are created and values are added
                fresh = new Node(); // Node class is called
                fresh.val = a[i]; // Node val is stored
                if (start == null) {
                    start = fresh;
                } else {
                    prev.next = fresh;
                }
                prev = fresh;
            }
            start = nm.sortByMergeSort(start);
            // method is being called
