                fresh2 = new Node(); // Node class is created
                fresh2.val = a[i2]; // Value is stored in the value part of the Node
                if (start2 == null) {
                    start2 = fresh2;
                } else {
                    prev2.next = fresh2;
                }
                prev2 = fresh2;
            }
            start2 = mm.sortByHeapSort(start2);
            // method is being called
            int i3 = 0;
            for (ptr2 = start2; ptr2 != null; ptr2 = ptr2.next) {
                a[i3++] = ptr2.val;
