package com.thealgorithms.strings;

/**
 * Given a string, moving several characters in front of the string to the end
 * of the string. For example, move the two characters'a' and 'b' in front of
 * the string "abcdef" to the end of the string, so that the original string
 * becomes the string "cdefab"
 */
public final class Rotation {
    private Rotation() {
    }

    public static void main(String[] args) {
        assert rotation("abcdef", 2).equals("cdefab");

        char[] values = "abcdef".toCharArray();
        rotation(values, 2);
        assert new String(values).equals("cdefab");
    }

    /**
     * Move {@code n} characters in front of given string to the end of string
     * time complexity: O(n) space complexity: O(n)
     *
     * @param s given string
     * @param n the total characters to be moved
     * @return string after rotation
     */
    public static String rotation(String s, int n) {
        return s.substring(n) + s.substring(0, n);
    }

    /**
     * Move {@code n} characters in front of given character array to the end of
     * array time complexity: O(n) space complexity: O(1)
     *
     * @param values given character array
     * @param n the total characters to be moved
     */
    public static void rotation(char[] values, int n) {
        reverse(values, 0, n - 1);
        reverse(values, n, values.length - 1);
        reverse(values, 0, values.length - 1);
    }

    /**
     * Reverse character array
     *
     * @param values character array
     * @param from begin index of given array
     * @param to end index of given array
     */
    public static void reverse(char[] values, int from, int to) {
        while (from < to) {
            char temp = values[from];
            values[from] = values[to];
            values[to] = temp;
            from++;
            to--;
        }
    }
}

package com.thealgorithms.strings;

/**
 * References : https://en.wikipedia.org/wiki/Run-length_encoding
 * String compression algorithm deals with encoding the string, that is, shortening the size of the string
 * @author Swarga-codes (https://github.com/Swarga-codes)
 */
public final class StringCompression {
    private StringCompression() {
    }
    /**
     * Returns the compressed or encoded string
     *
     * @param input character array that contains the group of characters to be encoded
     * @return the compressed character array as string
     */
    public static String compress(String input) {
        // Keeping the count as 1 since every element present will have at least a count of 1
        int count = 1;
        String compressedString = "";
        // Base condition to check whether the array is of size 1, if it is then we return the array
        if (input.length() == 1) {
            return "" + input.charAt(0);
        }
        // If the array has a length greater than 1 we move into this loop
        for (int i = 0; i < input.length() - 1; i++) {
            // here we check for similarity of the adjacent elements and change the count accordingly
            if (input.charAt(i) == input.charAt(i + 1)) {
                count = count + 1;
            }
            if ((i + 1) == input.length() - 1 && input.charAt(i + 1) == input.charAt(i)) {
                compressedString = appendCount(compressedString, count, input.charAt(i));
                break;
            } else if (input.charAt(i) != input.charAt(i + 1)) {
                if ((i + 1) == input.length() - 1) {
                    compressedString = appendCount(compressedString, count, input.charAt(i)) + input.charAt(i + 1);
                    break;
                } else {
                    compressedString = appendCount(compressedString, count, input.charAt(i));
                    count = 1;
                }
            }
        }
        return compressedString;
    }
    /**
     * @param res   the resulting string
     * @param count current count
     * @param ch    the character at a particular index
     * @return the res string appended with the count
     */
    public static String appendCount(String res, int count, char ch) {
        if (count > 1) {
            res += ch + "" + count;
        } else {
            res += ch + "";
        }
        return res;
    }
}

package com.thealgorithms.strings;

import java.util.Set;
import java.util.TreeSet;

/**
 * A class to perform string matching using <a href="https://en.wikipedia.org/wiki/Finite-state_machine">finite automata</a>.
 *
 * @author <a href="https://github.com/prateekKrOraon">Prateek Kumar Oraon</a>
 */
public final class StringMatchFiniteAutomata {

    // Constants
    private static final int CHARS = Character.MAX_VALUE + 1; // Total number of characters in the input alphabet

    // Private constructor to prevent instantiation
    private StringMatchFiniteAutomata() {
    }

    /**
     * Searches for the pattern in the given text using finite automata.
     *
     * @param text    The text to search within.
     * @param pattern The pattern to search for.
     */
    public static Set<Integer> searchPattern(final String text, final String pattern) {
        final var stateTransitionTable = computeStateTransitionTable(pattern);
        FiniteAutomata finiteAutomata = new FiniteAutomata(stateTransitionTable);

        Set<Integer> indexFound = new TreeSet<>();
        for (int i = 0; i < text.length(); i++) {
            finiteAutomata.consume(text.charAt(i));

            if (finiteAutomata.getState() == pattern.length()) {
                indexFound.add(i - pattern.length() + 1);
            }
        }
        return indexFound;
    }

    /**
     * Computes the finite automata table for the given pattern.
     *
     * @param pattern The pattern to preprocess.
     * @return The state transition table.
     */
    private static int[][] computeStateTransitionTable(final String pattern) {
        final int patternLength = pattern.length();
        int[][] stateTransitionTable = new int[patternLength + 1][CHARS];

        for (int state = 0; state <= patternLength; ++state) {
            for (int x = 0; x < CHARS; ++x) {
                stateTransitionTable[state][x] = getNextState(pattern, patternLength, state, x);
            }
        }

        return stateTransitionTable;
    }

    /**
     * Gets the next state for the finite automata.
     *
     * @param pattern       The pattern being matched.
     * @param patternLength The length of the pattern.
     * @param state         The current state.
     * @param x             The current character from the input alphabet.
     * @return The next state.
     */
    private static int getNextState(final String pattern, final int patternLength, final int state, final int x) {
        // If the current state is less than the length of the pattern
        // and the character matches the pattern character, go to the next state
        if (state < patternLength && x == pattern.charAt(state)) {
            return state + 1;
        }

        // Check for the highest prefix which is also a suffix
        for (int ns = state; ns > 0; ns--) {
            if (pattern.charAt(ns - 1) == x) {
                boolean match = true;
                for (int i = 0; i < ns - 1; i++) {
                    if (pattern.charAt(i) != pattern.charAt(state - ns + i + 1)) {
                        match = false;
                        break;
                    }
                }
                if (match) {
                    return ns;
                }
            }
        }

        // If no prefix which is also a suffix is found, return 0
        return 0;
    }

    /**
     * A class representing the finite automata for pattern matching.
     */
    private static final class FiniteAutomata {
        private int state = 0;
        private final int[][] stateTransitionTable;

        private FiniteAutomata(int[][] stateTransitionTable) {
            this.stateTransitionTable = stateTransitionTable;
        }

        /**
         * Consumes an input character and transitions to the next state.
         *
         * @param input The input character.
         */
        private void consume(final char input) {
            state = stateTransitionTable[state][input];
        }

        /**
         * Gets the current state of the finite automata.
         *
         * @return The current state.
         */
        private int getState() {
            return state;
        }
    }
}

package com.thealgorithms.strings;

import java.util.Arrays;

/**
 * Suffix Array implementation in Java.
 * Builds an array of indices that represent all suffixes of a string in sorted order.
 * Wikipedia Reference: https://en.wikipedia.org/wiki/Suffix_array
 * Author: Nithin U.
 * Github: https://github.com/NithinU2802
 */

public final class SuffixArray {

    private SuffixArray() {
    }

    public static int[] buildSuffixArray(String text) {
        int n = text.length();
        Integer[] suffixArray = new Integer[n];
        int[] rank = new int[n];
        int[] tempRank = new int[n];

        // Initial ranking based on characters
        for (int i = 0; i < n; i++) {
            suffixArray[i] = i;
            rank[i] = text.charAt(i);
        }

        for (int k = 1; k < n; k *= 2) {
            final int step = k;

            // Comparator: first by rank, then by rank + step
            Arrays.sort(suffixArray, (a, b) -> {
                if (rank[a] != rank[b]) {
                    return Integer.compare(rank[a], rank[b]);
                }
                int ra = (a + step < n) ? rank[a + step] : -1;
                int rb = (b + step < n) ? rank[b + step] : -1;
                return Integer.compare(ra, rb);
            });

            // Re-rank
            tempRank[suffixArray[0]] = 0;
            for (int i = 1; i < n; i++) {
                int prev = suffixArray[i - 1];
                int curr = suffixArray[i];
                boolean sameRank = rank[prev] == rank[curr] && ((prev + step < n ? rank[prev + step] : -1) == (curr + step < n ? rank[curr + step] : -1));
                tempRank[curr] = sameRank ? tempRank[prev] : tempRank[prev] + 1;
            }

            System.arraycopy(tempRank, 0, rank, 0, n);

            if (rank[suffixArray[n - 1]] == n - 1) {
                break;
            }
        }
        return Arrays.stream(suffixArray).mapToInt(Integer::intValue).toArray();
    }
}

package com.thealgorithms.strings;

/**
 * Title Case converts a string so that the first letter of each word
 * is capitalized and the rest are lowercase.
 * Example: "the quick brown fox" -> "The Quick Brown Fox"
 *
 * @see <a href="https://en.wikipedia.org/wiki/Title_case">
 *     Wikipedia: Title Case</a>
 */
public final class TitleCase {

    private TitleCase() {
        // Utility class
    }

    /**
     * Converts a string to title case.
     *
     * @param input The string to convert
     * @return The title-cased string, or empty string if input is null/empty.
     *     If input contains only whitespace, it is returned as is.
     */
    public static String toTitleCase(final String input) {
        if (input == null || input.isEmpty()) {
            return "";
        }

        StringBuilder result = new StringBuilder(input.length());
        boolean capitalizeNext = true;
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (Character.isWhitespace(c)) {
                capitalizeNext = true;
                result.append(c);
                continue;
            }

            if (capitalizeNext) {
                if (Character.isLetter(c)) {
                    result.append(Character.toUpperCase(c));
                    capitalizeNext = false;
                } else {
                    // Keep capitalizeNext=true so the first *letter* after
                    // punctuation/digits is capitalized.
                    result.append(c);
                }
            } else {
                result.append(Character.toLowerCase(c));
            }
        }
        return result.toString();
    }
}

package com.thealgorithms.strings;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Utility class to find the top-k most frequent words.
 *
 * <p>Words are ranked by frequency in descending order. For equal frequencies,
 * words are ranked in lexicographical ascending order.
 *
 * <p>Reference:
 * https://en.wikipedia.org/wiki/Top-k_problem
 *
 */
public final class TopKFrequentWords {
    private TopKFrequentWords() {
    }

    /**
     * Finds the k most frequent words.
     *
     * @param words input array of words
     * @param k number of words to return
     * @return list of top-k words ordered by frequency then lexicographical order
     * @throws IllegalArgumentException if words is null, k is negative, or words contains null
     */
    public static List<String> findTopKFrequentWords(String[] words, int k) {
        if (words == null) {
            throw new IllegalArgumentException("Input words array cannot be null.");
        }
        if (k < 0) {
            throw new IllegalArgumentException("k cannot be negative.");
        }
        if (k == 0 || words.length == 0) {
            return List.of();
        }

        Map<String, Integer> frequency = new HashMap<>();
        for (String word : words) {
            if (word == null) {
                throw new IllegalArgumentException("Input words cannot contain null values.");
            }
            frequency.put(word, frequency.getOrDefault(word, 0) + 1);
        }

        List<String> candidates = new ArrayList<>(frequency.keySet());
        candidates.sort(Comparator.<String>comparingInt(frequency::get).reversed().thenComparing(Comparator.naturalOrder()));

        int limit = Math.min(k, candidates.size());
        return new ArrayList<>(candidates.subList(0, limit));
    }
}

