        capacity[2][3] = 10;
        capacity[1][4] = 10;
        capacity[3][5] = 10;
        capacity[4][5] = 5;
        capacity[4][6] = 10;
        capacity[5][7] = 10;
        capacity[6][7] = 15;

        int maxFlow = FordFulkerson.networkFlow(vertexCount, capacity, flow, 0, 7);
