        graph.addEdge(2, 4, 8, 4);
        graph.addEdge(3, 5, 7, 3);
        graph.addEdge(3, 6, 6, 2);
        graph.addEdge(4, 6, 3, 2);
        graph.addEdge(5, 7, 1, 1);
