        String b = "0";
        String expected = "0";
        assertEquals(expected, binaryAddition.addBinary(a, b));
    }

    @Test
    public void testAllOnes() {
        String a = "1111";
        String b = "1111";
        String expected = "11110";
        assertEquals(expected, binaryAddition.addBinary(a, b));
    }

    @Test
    public void testOneZeroString() {
