    public void testPlus() {
        assertEquals(new ADTFraction(59, 40), fraction1.plus(fraction2));
    }

    @Test
    public void testTimes() {
        assertEquals(new ADTFraction(12, 5), fraction1.times(4));
        assertEquals(new ADTFraction(21, 40), fraction1.times(fraction2));
    }

    @Test
    public void testReciprocal() {
        assertEquals(new ADTFraction(5, 3), fraction1.reciprocal());
    }

    @Test
    public void testValue() {
        assertEquals(0.6F, fraction1.value());
    }

    @Test
    public void testEqualsAndHashCode() {
        ADTFraction fraction3 = new ADTFraction(3, 5);
        assertTrue(fraction1.equals(fraction3) && fraction3.equals(fraction1));
        assertEquals(fraction1.hashCode(), fraction3.hashCode());
    }

    @Test
    public void testToString() {
        assertEquals("3/5", fraction1.toString());
    }
}

package com.thealgorithms.maths;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import org.junit.jupiter.api.Test;

public class AbsoluteMaxTest {

    @Test
    void testGetMaxValue() {
        assertEquals(16, AbsoluteMax.getMaxValue(-2, 0, 16));
        assertEquals(-22, AbsoluteMax.getMaxValue(-3, -10, -22));
        assertEquals(-888, AbsoluteMax.getMaxValue(-888));
        assertEquals(-1, AbsoluteMax.getMaxValue(-1, -1, -1, -1, -1));
    }

    @Test
    void testGetMaxValueWithNoArguments() {
        assertThrows(IllegalArgumentException.class, AbsoluteMax::getMaxValue);
    }

    @Test
    void testGetMaxValueWithSameAbsoluteValues() {
        assertEquals(5, AbsoluteMax.getMaxValue(-5, 5));
        assertEquals(5, AbsoluteMax.getMaxValue(5, -5));
        assertEquals(12, AbsoluteMax.getMaxValue(-12, 9, 3, 12, 1));
        assertEquals(12, AbsoluteMax.getMaxValue(12, 9, 3, -12, 1));
    }
}

package com.thealgorithms.maths;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import org.junit.jupiter.api.Test;

public class AbsoluteMinTest {

    @Test
    void testGetMinValue() {
        assertEquals(0, AbsoluteMin.getMinValue(4, 0, 16));
        assertEquals(-2, AbsoluteMin.getMinValue(3, -10, -2));
        assertEquals(-2, AbsoluteMin.getMinValue(-3, -10, -2));
        assertEquals(2, AbsoluteMin.getMinValue(-3, -10, 2));
        assertEquals(2, AbsoluteMin.getMinValue(-5, 2));
        assertEquals(2, AbsoluteMin.getMinValue(2, -5));
    }

    @Test
    void testGetMinValueWithNoArguments() {
        assertThrows(IllegalArgumentException.class, AbsoluteMin::getMinValue);
    }

    @Test
    void testGetMinValueWithSameAbsoluteValues() {
        assertEquals(-5, AbsoluteMin.getMinValue(-5, 5));
        assertEquals(-5, AbsoluteMin.getMinValue(5, -5));
    }

    @Test
    void testIntegerMinValueOverflow() {
        assertEquals(1, AbsoluteMin.getMinValue(Integer.MIN_VALUE, 1));
        assertEquals(-1, AbsoluteMin.getMinValue(Integer.MIN_VALUE, -1));
        assertEquals(0, AbsoluteMin.getMinValue(Integer.MIN_VALUE, 0));
        assertEquals(Integer.MIN_VALUE, AbsoluteMin.getMinValue(Integer.MIN_VALUE));
        assertEquals(Integer.MAX_VALUE, AbsoluteMin.getMinValue(Integer.MIN_VALUE, Integer.MAX_VALUE));
    }
}

package com.thealgorithms.maths;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.concurrent.ThreadLocalRandom;
import java.util.stream.Stream;
import org.junit.jupiter.api.Test;

public class AbsoluteValueTest {

    @Test
    void testGetAbsValue() {
        Stream.generate(() -> ThreadLocalRandom.current().nextInt()).limit(1000).forEach(number -> assertEquals(Math.abs(number), AbsoluteValue.getAbsValue(number)));
    }

    @Test
    void testZero() {
        assertEquals(0, AbsoluteValue.getAbsValue(0));
    }

    @Test
    void testPositiveNumbers() {
        assertEquals(5, AbsoluteValue.getAbsValue(5));
        assertEquals(123456, AbsoluteValue.getAbsValue(123456));
        assertEquals(Integer.MAX_VALUE, AbsoluteValue.getAbsValue(Integer.MAX_VALUE));
    }

    @Test
    void testNegativeNumbers() {
        assertEquals(5, AbsoluteValue.getAbsValue(-5));
        assertEquals(123456, AbsoluteValue.getAbsValue(-123456));
        assertEquals(Integer.MAX_VALUE, AbsoluteValue.getAbsValue(-Integer.MAX_VALUE));
    }

    @Test
    void testMinIntEdgeCase() {
        assertEquals(2147483648L, AbsoluteValue.getAbsValue(Integer.MIN_VALUE));
    }
}

