    public void testDuplicateXCoordinates() {
        double[] x = {1, 2, 1};
        double[] y = {5, 8, 3};
        double target = 1.5;
        assertThrows(IllegalArgumentException.class, () -> Neville.interpolate(x, y, target));
    }
}

