    }

    /**
     * Test for Fibonacci search with the first element as the key.
     */
    @Test
    void testFibonacciSearchFirstElement() {
        FibonacciSearch fibonacciSearch = new FibonacciSearch();
        Integer[] array = {1, 2, 4, 8, 16};
