        assertThrows(NullPointerException.class, () -> HorspoolSearch.findFirst(null, "Hello World"));
    }

    @Test
    void testFindFirstTextNull() {
        assertThrows(NullPointerException.class, () -> HorspoolSearch.findFirst("Hello", null));
    }
}

