 *  The robot tries to move to the bottom-right corner.
 *  The robot can only move either down or right at any point in time.
 *
 *  Given the two integers `m` and `n`,
 *  return the number of possible unique paths that the robot can take to reach the bottom-right corner.
 *  More info: https://leetcode.com/problems/unique-paths/
 */

/*
 * @param {number} m
 * @param {number} n
 * @return {number}
 */

const uniquePaths = (m, n) => {
  // only one way to reach end
  if (m === 1 || n === 1) return 1

  // build a linear grid of size m
  // base case, position 1 has only 1 move
  const paths = new Array(m).fill(1)

  for (let i = 1; i < n; i++) {
    for (let j = 1; j < m; j++) {
      // paths[j] in RHS represents the cell value stored above the current cell
      // paths[j-1] in RHS represents the cell value stored to the left of the current cell
      // paths [j] on the LHS represents the number of distinct pathways to the cell (i, j)
      paths[j] = paths[j - 1] + paths[j]
    }
  }
  return paths[m - 1]
}

export { uniquePaths }

/*
 * Unique Paths 2
 *
 * There is a robot on an `m x n` grid.
 * The robot is initially located at the top-left corner
 * The robot tries to move to the bottom-right corner.
 * The robot can only move either down or right at any point in time.
 *
 * Given grid with obstacles
 * An obstacle and space are marked as 1 or 0 respectively in grid.
 * A path that the robot takes cannot include any square that is an obstacle.
 * Return the number of possible unique paths that the robot can take to reach the bottom-right corner.
 *
 * More info: https://leetcode.com/problems/unique-paths-ii/
 */

/**
 * @description Return 'rows x columns' grid with cells filled by 'filler'
 * @param {Number} rows Number of rows in the grid
 * @param {Number} columns Number of columns in the grid
 * @param {String | Number | Boolean} filler The value to fill cells
 * @returns {Array [][]}
 */
const generateMatrix = (rows, columns, filler = 0) => {
  const matrix = []
  for (let i = 0; i < rows; i++) {
    const submatrix = []
    for (let k = 0; k < columns; k++) {
      submatrix[k] = filler
    }
    matrix[i] = submatrix
  }
  return matrix
}

/**
 * @description Return number of unique paths
 * @param {Array [][]} obstacles Obstacles grid
 * @returns {Number}
 */
const uniquePaths2 = (obstacles) => {
  if (!Array.isArray(obstacles)) {
    throw new Error('Input data must be type of Array')
  }
  // Create grid for calculating number of unique ways
  const rows = obstacles.length
  const columns = obstacles[0].length
  const grid = generateMatrix(rows, columns)
  // Fill the outermost cell with 1 b/c it has
  // the only way to reach neighbor
  for (let i = 0; i < rows; i++) {
    // If robot encounters an obstacle in these cells,
    // he cannot continue moving in that direction
    if (obstacles[i][0]) {
      break
    }
    grid[i][0] = 1
  }
  for (let j = 0; j < columns; j++) {
    if (obstacles[0][j]) {
      break
    }
    grid[0][j] = 1
  }
  // Fill the rest of grid by dynamic programming
  // using following recurrent formula:
  // K[i][j] = K[i - 1][j] + K[i][j - 1]
  for (let i = 1; i < rows; i++) {
    for (let j = 1; j < columns; j++) {
      grid[i][j] = obstacles[i][j] ? 0 : grid[i - 1][j] + grid[i][j - 1]
    }
  }
  return grid[rows - 1][columns - 1]
}

export { uniquePaths2 }

/**
 * A Dynamic Programming based solution for calculating Zero One Knapsack
 * https://en.wikipedia.org/wiki/Knapsack_problem
 *
 * Time and Space Complexity: O(n*cap)
 */
const zeroOneKnapsack = (arr, n, cap, cache) => {
  // Base Case: No capacity or no items
  if (cap === 0 || n === 0) {
    cache[n][cap] = 0
    return cache[n][cap]
  }

  // Lookup (value already calculated)
  if (cache[n][cap] !== -1) {
    return cache[n][cap]
  }

  // Profit when excluding the nth item
  let notPick = zeroOneKnapsack(arr, n - 1, cap, cache)

  // Profit when including the nth item
  let pick = 0
  if (arr[n - 1][0] <= cap) {
    // If weight of the nth item is within the capacity
    pick =
      arr[n - 1][1] + zeroOneKnapsack(arr, n - 1, cap - arr[n - 1][0], cache)
  }

  cache[n][cap] = Math.max(pick, notPick) // maximize profit
  return cache[n][cap]
}

const example = () => {
  /*
  Problem Statement:
  You are a thief carrying a single bag with limited capacity S. The museum you stole had N artifact that you could steal. Unfortunately you might not be able to steal all the artifact because of your limited bag capacity.
  You have to cherry pick the artifact in order to maximize the total value of the artifacts you stole.

  Link for the Problem: https://www.hackerrank.com/contests/srin-aadc03/challenges/classic-01-knapsack
  */
  let input = `1
    4 5
    1 8
    2 4
    3 0
    2 5
    2 3`

  input = input.trim().split('\n')
  input.shift()
  const length = input.length

  const output = []

  let i = 0
  while (i < length) {
    const cap = Number(input[i].trim().split(' ')[0])
    const currlen = Number(input[i].trim().split(' ')[1])
    let j = i + 1
    const arr = []
    while (j <= i + currlen) {
      arr.push(input[j])
      j++
    }
    const newArr = arr.map((e) => e.trim().split(' ').map(Number))
    const cache = []
    for (let i = 0; i <= currlen; i++) {
      const temp = []
      for (let j = 0; j <= cap; j++) {
        temp.push(-1)
      }
      cache.push(temp)
    }
    const result = zeroOneKnapsack(newArr, currlen, cap, cache)
    output.push(result)
    i += currlen + 1
  }

  return output
}

export { zeroOneKnapsack, example }

