/**
 * Hamming Distance: https://en.wikipedia.org/wiki/Hamming_distance
 *
 *
 * Hamming distance is a metric for comparing two binary data strings.
 *
 * While comparing two binary strings of equal length, Hamming distance
 * is the number of bit positions in which the two bits are different.
 * The Hamming distance between two strings, a and b is denoted as d(a,b)
 */

/**
 * @param {string} a
 * @param {string} b
 * @return {number}
 */

export const hammingDistance = (a, b) => {
  if (a.length !== b.length) {
    throw new Error('Strings must be of the same length')
  }

  let distance = 0

  for (let i = 0; i < a.length; i += 1) {
    if (a[i] !== b[i]) {
      distance += 1
    }
  }

  return distance
}

/**
 * @function isPalindromeIterative
 * @description isPalindromeIterative function checks whether the provided input is palindrome or not
 * @param {String | Number} x - The input to check
 * @return {boolean} - Input is palindrome or not
 * @see [Palindrome](https://en.wikipedia.org/wiki/Palindrome)
 */

/*
  * Big-O Analysis
      * Time Complexity
        - O(N) on average and worst case scenario as input is traversed in linear fashion
        - O(1) on best case scenario if the input already is a string (otherwise toString() method takes O(N))
               and the first & last characters don't match, triggering an early return
      * Space Complexity
        - O(1)
*/

export function isPalindromeIterative(x) {
  if (typeof x !== 'string' && typeof x !== 'number') {
    throw new TypeError('Input must be a string or a number')
  }

  // Convert x to string whether it's number or string
  const string = x.toString()
  const length = string.length

  if (length === 1) return true

  // Apply two pointers technique to compare first and last elements on each iteration
  for (let start = 0, end = length - 1; start < end; start++, end--) {
    // Early return if compared items are different, input is not a palindrome
    if (string[start] !== string[end]) return false
  }
  // If early return in condition inside for loop is not reached, then input is palindrome
  return true
}

// Implementing KMP Search Algorithm to search all the instances of pattern in
// given text
// Reference Book: Introduction to Algorithms, CLRS

// Explanation: https://www.topcoder.com/community/competitive-programming/tutorials/introduction-to-string-searching-algorithms/

const computeLPS = (pattern) => {
  const lps = Array(pattern.length)
  lps[0] = 0
  for (let i = 1; i < pattern.length; i++) {
    let matched = lps[i - 1]
    while (matched > 0 && pattern[i] !== pattern[matched]) {
      matched = lps[matched - 1]
    }
    if (pattern[i] === pattern[matched]) {
      matched++
    }
    lps[i] = matched
  }
  return lps
}

/**
 * Returns all indices where pattern starts in text
 * @param {*} text a big text in which pattern string is to find
 * @param {*} pattern the string to find
 */
const KMPSearch = (text, pattern) => {
  if (!pattern || !text) {
    return [] // no results
  }

  // lps[i] = length of proper prefix of pattern[0]...pattern[i-1]
  //          which is also proper suffix of it
  const lps = computeLPS(pattern)
  const result = []

  let matched = 0
  for (let i = 0; i < text.length; i++) {
    while (matched > 0 && text[i] !== pattern[matched]) {
      matched = lps[matched - 1]
    }
    if (text[i] === pattern[matched]) {
      matched++
    }
    if (matched === pattern.length) {
      result.push(i - pattern.length + 1)
      matched = lps[matched - 1]
    }
  }

  return result
}

export { KMPSearch }

/*
 * @description : Given a string, the function finds the length of the longest substring without any repeating characters
 * @param {String} str - The input string
 * @returns {Number} The Length of the longest substring in a given string without repeating characters
 * @example lengthOfLongestSubstring("abcabcbb") => 3
 * @example lengthOfLongestSubstring("bbbbb") => 1
 * @see https://leetcode.com/problems/longest-substring-without-repeating-characters/
 */

const lengthOfLongestSubstring = (s) => {
  if (typeof s !== 'string') {
    throw new TypeError('Invalid Input Type')
  }
  let maxLength = 0
  let start = 0
  const charMap = new Map()
  for (let end = 0; end < s.length; end++) {
    if (charMap.has(s[end])) {
      start = Math.max(start, charMap.get(s[end]) + 1)
    }
    charMap.set(s[end], end)
    maxLength = Math.max(maxLength, end - start + 1)
  }
  return maxLength
}

